val FILL: String = "#include <metal_stdlib>\n\nusing namespace metal;\n\ntemplate<typename T> METAL_FUNC void fill_with(\n    device T *out,\n    constant T &value,\n    constant size_t &numel,\n    uint tid [[thread_position_in_grid]]\n) {\n    if (tid >= numel) {\n        return;\n    }\n    out[tid] = value;\n}\n\n#define FILL_OP(NAME, T)                                \\\nkernel void fill_##NAME(                                \\\n    device T *out,                                      \\\n    constant T &value,                              \\\n    constant size_t &numel,                              \\\n    uint tid [[thread_position_in_grid]]                \\\n) {                                                     \\\n    fill_with<T>(out, value, numel, tid);              \\\n}                                                       \\\n\n\n#define FILL_OPS(NAME, T) \\\nFILL_OP(NAME, T)          \\\n\nFILL_OPS(u8, uchar)\nFILL_OPS(u32, uint)\nFILL_OPS(i64, long)\nFILL_OPS(f16, half)\nFILL_OPS(f32, float)\n\n#if __METAL_VERSION__ >= 310\nFILL_OPS(bf16, bfloat)\n#endif\n"

val INDEXING: String = "#include <metal_stdlib>\nusing namespace metal;\n\ntemplate <typename T>\ninline T max_value();\n\ntemplate <>\ninline int64_t max_value<int64_t>() {\n    return 0x7FFFFFFFFFFFFFFF;\n}\n\ntemplate <>\ninline uint32_t max_value<uint32_t>() {\n    return 0xFFFFFFFFu;\n}\n\ntemplate <>\ninline uint8_t max_value<uint8_t>() {\n    return 0xFF;\n}\n\nMETAL_FUNC uint get_strided_index(\n    uint idx,\n    constant size_t &num_dims,\n    constant size_t *dims,\n    constant size_t *strides\n) {\n    uint strided_i = 0;\n    for (uint d = 0; d < num_dims; d++) {\n        uint dim_idx = num_dims - 1 - d;\n        strided_i += (idx % dims[dim_idx]) * strides[dim_idx];\n        idx /= dims[dim_idx];\n    }\n    return strided_i;\n}\n\ntemplate<typename TYPENAME, typename INDEX_TYPENAME>\nMETAL_FUNC void index(\n    constant size_t &dst_size,\n    constant size_t &left_size,\n    constant size_t &src_dim_size,\n    constant size_t &right_size,\n    constant size_t &ids_size,\n    constant bool &contiguous,\n    constant size_t *src_dims,\n    constant size_t *src_strides,\n    const device TYPENAME *input,\n    const device INDEX_TYPENAME *input_ids,\n    device TYPENAME *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    if (tid >= dst_size) {\n        return;\n    }\n    const size_t id_i = (tid / right_size) % ids_size;\n    if (input_ids[id_i] == max_value<INDEX_TYPENAME>()) {\n      output[tid] = static_cast<TYPENAME>(0);\n    } else {\n      const INDEX_TYPENAME input_i = min(input_ids[id_i], (INDEX_TYPENAME)(src_dim_size - 1));\n      const size_t right_rank_i = tid % right_size;\n      const size_t left_rank_i = tid / right_size / ids_size;\n      /*\n      // Force prevent out of bounds indexing\n      // since there doesn't seem to be a good way to force crash\n      // No need to check for zero we're only allowing unsized.\n      */\n      const size_t src_i = left_rank_i * src_dim_size * right_size + input_i * right_size + right_rank_i;\n      const size_t strided_src_i = contiguous ? src_i : get_strided_index(src_i, src_dim_size, src_dims, src_strides);\n      output[tid] = input[strided_src_i];\n    }\n}\n\n# define INDEX_OP(NAME, INDEX_TYPENAME, TYPENAME) \\\nkernel void NAME( \\\n    constant size_t &dst_size, \\\n    constant size_t &left_size, \\\n    constant size_t &src_dim_size, \\\n    constant size_t &right_size, \\\n    constant size_t &ids_size, \\\n    constant bool &contiguous, \\\n    constant size_t *src_dims, \\\n    constant size_t *src_strides, \\\n    const device TYPENAME *input, \\\n    const device INDEX_TYPENAME *input_ids, \\\n    device TYPENAME *output, \\\n    uint tid [[ thread_position_in_grid ]] \\\n) { \\\n    index<TYPENAME, INDEX_TYPENAME>(dst_size, left_size, src_dim_size, right_size, ids_size, contiguous, src_dims, src_strides, input, input_ids, output, tid); \\\n}\n\n\ntemplate<typename TYPENAME, typename INDEX_TYPENAME>\nMETAL_FUNC void gather(\n    constant size_t &dst_size,\n    constant size_t &left_size,\n    constant size_t &src_dim_size,\n    constant size_t &right_size,\n    constant size_t &ids_size,\n    const device TYPENAME *input,\n    const device INDEX_TYPENAME *input_ids,\n    device TYPENAME *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    if (tid >= dst_size) {\n        return;\n    }\n    const INDEX_TYPENAME input_i = input_ids[tid];\n    if (input_i == max_value<INDEX_TYPENAME>()) {\n      output[tid] = static_cast<TYPENAME>(0);\n    } else {\n      const size_t right_rank_i = tid % right_size;\n      const size_t left_rank_i = tid / right_size / ids_size;\n      const size_t src_i = (left_rank_i * src_dim_size + input_i) * right_size + right_rank_i;\n      output[tid] = input[src_i];\n    }\n}\n\n# define GATHER_OP(NAME, INDEX_TYPENAME, TYPENAME) \\\nkernel void NAME( \\\n    constant size_t &dst_size, \\\n    constant size_t &left_size, \\\n    constant size_t &src_dim_size, \\\n    constant size_t &right_size, \\\n    constant size_t &ids_size, \\\n    const device TYPENAME *input, \\\n    const device INDEX_TYPENAME *input_ids, \\\n    device TYPENAME *output, \\\n    uint tid [[ thread_position_in_grid ]] \\\n) { \\\n    gather<TYPENAME, INDEX_TYPENAME>(dst_size, left_size, src_dim_size, right_size, ids_size, input, input_ids, output, tid); \\\n}\n\ntemplate<typename TYPENAME, typename INDEX_TYPENAME>\nMETAL_FUNC void scatter(\n    constant size_t &dst_size,\n    constant size_t &left_size,\n    constant size_t &src_dim_size,\n    constant size_t &right_size,\n    constant size_t &dst_dim_size,\n    const device TYPENAME *input,\n    const device INDEX_TYPENAME *input_ids,\n    device TYPENAME *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    if (tid >= dst_size) {\n        return;\n    }\n    const size_t right_rank_i = tid % right_size;\n    const size_t left_rank_i = tid / right_size;\n    for (unsigned int j = 0; j < src_dim_size; ++j) {\n        const size_t src_i = (left_rank_i * src_dim_size + j) * right_size + right_rank_i;\n        const INDEX_TYPENAME idx = input_ids[src_i];\n        if (idx < max_value<INDEX_TYPENAME>()) {\n          const size_t dst_i = (left_rank_i * dst_dim_size + idx) * right_size + right_rank_i;\n          output[dst_i] = input[src_i];\n        }\n    }\n}\n\ntemplate<typename TYPENAME, typename INDEX_TYPENAME>\nMETAL_FUNC void scatter_add(\n    constant size_t &dst_size,\n    constant size_t &left_size,\n    constant size_t &src_dim_size,\n    constant size_t &right_size,\n    constant size_t &dst_dim_size,\n    const device TYPENAME *input,\n    const device INDEX_TYPENAME *input_ids,\n    device TYPENAME *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    if (tid >= dst_size) {\n        return;\n    }\n    const size_t right_rank_i = tid % right_size;\n    const size_t left_rank_i = tid / right_size;\n    for (unsigned int j = 0; j < src_dim_size; ++j) {\n        const size_t src_i = (left_rank_i * src_dim_size + j) * right_size + right_rank_i;\n        const INDEX_TYPENAME idx = input_ids[src_i];\n        if (idx < max_value<INDEX_TYPENAME>()) {\n          const size_t dst_i = (left_rank_i * dst_dim_size + idx) * right_size + right_rank_i;\n          output[dst_i] += input[src_i];\n        }\n    }\n}\n\n# define SCATTER_OP(NAME, INDEX_TYPENAME, TYPENAME) \\\nkernel void NAME( \\\n    constant size_t &dst_size, \\\n    constant size_t &left_size, \\\n    constant size_t &src_dim_size, \\\n    constant size_t &right_size, \\\n    constant size_t &dst_dim_size, \\\n    const device TYPENAME *input, \\\n    const device INDEX_TYPENAME *input_ids, \\\n    device TYPENAME *output, \\\n    uint tid [[ thread_position_in_grid ]] \\\n) { \\\n    scatter<TYPENAME, INDEX_TYPENAME>(dst_size, left_size, src_dim_size, right_size, dst_dim_size, input, input_ids, output, tid); \\\n}\n\n# define SCATTER_ADD_OP(NAME, INDEX_TYPENAME, TYPENAME) \\\nkernel void NAME( \\\n    constant size_t &dst_size, \\\n    constant size_t &left_size, \\\n    constant size_t &src_dim_size, \\\n    constant size_t &right_size, \\\n    constant size_t &dst_dim_size, \\\n    const device TYPENAME *input, \\\n    const device INDEX_TYPENAME *input_ids, \\\n    device TYPENAME *output, \\\n    uint tid [[ thread_position_in_grid ]] \\\n) { \\\n    scatter_add<TYPENAME, INDEX_TYPENAME>(dst_size, left_size, src_dim_size, right_size, dst_dim_size, input, input_ids, output, tid); \\\n}\n\ntemplate<typename TYPENAME, typename INDEX_TYPENAME>\nMETAL_FUNC void index_add(\n    constant size_t &dst_size,\n    constant size_t &left_size,\n    constant size_t &src_dim_size,\n    constant size_t &right_size,\n    constant size_t &dst_dim_size,\n    constant size_t &ids_dim_size,\n    const device TYPENAME *input,\n    const device INDEX_TYPENAME *input_ids,\n    device TYPENAME *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    if (tid >= dst_size) {\n        return;\n    }\n    const size_t right_rank_i = tid % right_size;\n    const size_t left_rank_i = tid / right_size;\n    for (unsigned int j = 0; j < ids_dim_size; ++j) {\n        const INDEX_TYPENAME idx = input_ids[j];\n        if (idx < max_value<INDEX_TYPENAME>()) {\n          const size_t src_i = (left_rank_i * src_dim_size + j) * right_size + right_rank_i;\n          const size_t dst_i = (left_rank_i * dst_dim_size + idx) * right_size + right_rank_i;\n          output[dst_i] += input[src_i];\n        }\n    }\n}\n\n# define INDEX_ADD_OP(NAME, INDEX_TYPENAME, TYPENAME) \\\nkernel void NAME( \\\n    constant size_t &dst_size, \\\n    constant size_t &left_size, \\\n    constant size_t &src_dim_size, \\\n    constant size_t &right_size, \\\n    constant size_t &dst_dim_size, \\\n    constant size_t &ids_dim_size, \\\n    const device TYPENAME *input, \\\n    const device INDEX_TYPENAME *input_ids, \\\n    device TYPENAME *output, \\\n    uint tid [[ thread_position_in_grid ]] \\\n) { \\\n    index_add<TYPENAME, INDEX_TYPENAME>(dst_size, left_size, src_dim_size, right_size, dst_dim_size, ids_dim_size, input, input_ids, output, tid); \\\n}\n\n\nINDEX_OP(is_i64_i64, int64_t, int64_t)\nINDEX_OP(is_i64_f32, int64_t, float)\nINDEX_OP(is_i64_f16, int64_t, half)\n#if defined(__HAVE_BFLOAT__)\nINDEX_OP(is_i64_bf16, int64_t, bfloat)\n#endif\n\nINDEX_OP(is_u32_u8, uint32_t, uint8_t)\nINDEX_OP(is_u32_u32, uint32_t, uint32_t)\nINDEX_OP(is_u32_i64, uint32_t, int64_t)\nINDEX_OP(is_u32_f32, uint32_t, float)\nINDEX_OP(is_u32_f16, uint32_t, half)\n#if defined(__HAVE_BFLOAT__)\nINDEX_OP(is_u32_bf16, uint32_t, bfloat)\n#endif\n\nINDEX_OP(is_u8_u8, uint8_t, uint8_t)\nINDEX_OP(is_u8_u32, uint8_t, uint32_t)\nINDEX_OP(is_u8_i64, uint8_t, int64_t)\nINDEX_OP(is_u8_f32, uint8_t, float)\nINDEX_OP(is_u8_f16, uint8_t, half)\n#if defined(__HAVE_BFLOAT__)\nINDEX_OP(is_u8_bf16, uint8_t, bfloat)\n#endif\n\nGATHER_OP(gather_u8_f32, uint8_t, float)\nGATHER_OP(gather_u8_f16, uint8_t, half)\nGATHER_OP(gather_i64_f32, int64_t, float)\nGATHER_OP(gather_i64_f16, int64_t, half)\nGATHER_OP(gather_u32_f32, uint, float)\nGATHER_OP(gather_u32_f16, uint, half)\n#if defined(__HAVE_BFLOAT__)\nGATHER_OP(gather_u8_bf16, uint8_t, bfloat)\nGATHER_OP(gather_i64_bf16, int64_t, bfloat)\nGATHER_OP(gather_u32_bf16, uint, bfloat)\n#endif\nGATHER_OP(gather_u8_u8, uint8_t, uint8_t)\nGATHER_OP(gather_u8_i64, uint8_t, int64_t)\nGATHER_OP(gather_u8_u32, uint8_t, uint)\nGATHER_OP(gather_u32_u32, uint, uint)\nGATHER_OP(gather_u32_i64, uint, int64_t)\nGATHER_OP(gather_i64_u32, int64_t, uint)\nGATHER_OP(gather_i64_i64, int64_t, int64_t)\n\nSCATTER_ADD_OP(sa_u32_f32, uint32_t, float)\nSCATTER_ADD_OP(sa_u8_f32, uint8_t, float)\nSCATTER_ADD_OP(sa_i64_f32, int64_t, float)\nSCATTER_ADD_OP(sa_u32_u32, uint32_t, uint32_t)\nSCATTER_ADD_OP(sa_u32_f16, uint32_t, half)\nSCATTER_ADD_OP(sa_u8_f16, uint8_t, half)\nSCATTER_ADD_OP(sa_i64_f16, int64_t, half)\n#if defined(__HAVE_BFLOAT__)\nSCATTER_ADD_OP(sa_u32_bf16, uint32_t, bfloat)\nSCATTER_ADD_OP(sa_u8_bf16, uint8_t, bfloat)\nSCATTER_ADD_OP(sa_i64_bf16, int64_t, bfloat)\n#endif\n\nSCATTER_OP(s_u32_f32, uint32_t, float)\nSCATTER_OP(s_u8_f32, uint8_t, float)\nSCATTER_OP(s_i64_f32, int64_t, float)\nSCATTER_OP(s_u32_u32, uint32_t, uint32_t)\nSCATTER_OP(s_u32_f16, uint32_t, half)\nSCATTER_OP(s_u8_f16, uint8_t, half)\nSCATTER_OP(s_i64_f16, int64_t, half)\n#if defined(__HAVE_BFLOAT__)\nSCATTER_OP(s_u32_bf16, uint32_t, bfloat)\nSCATTER_OP(s_u8_bf16, uint8_t, bfloat)\nSCATTER_OP(s_i64_bf16, int64_t, bfloat)\n#endif\n\n// i64\nINDEX_ADD_OP(ia_i64_f16, int64_t, half)\nINDEX_ADD_OP(ia_i64_f32, int64_t, float)\nINDEX_ADD_OP(ia_i64_i64, int64_t, int64_t)\nINDEX_ADD_OP(ia_i64_u32, int64_t, uint32_t)\nINDEX_ADD_OP(ia_i64_u8, int64_t, uint8_t)\n#if defined(__HAVE_BFLOAT__)\nINDEX_ADD_OP(ia_i64_bf16, int64_t, bfloat)\n#endif\n\n// u32\nINDEX_ADD_OP(ia_u32_f16, uint32_t, half)\nINDEX_ADD_OP(ia_u32_f32, uint32_t, float)\nINDEX_ADD_OP(ia_u32_i64, uint32_t, int64_t)\nINDEX_ADD_OP(ia_u32_u32, uint32_t, uint32_t)\nINDEX_ADD_OP(ia_u32_u8, uint32_t, uint8_t)\n#if defined(__HAVE_BFLOAT__)\nINDEX_ADD_OP(ia_u32_bf16, uint32_t, bfloat)\n#endif\n\n// u8\nINDEX_ADD_OP(ia_u8_f16, uint8_t, half)\nINDEX_ADD_OP(ia_u8_f32, uint8_t, float)\nINDEX_ADD_OP(ia_u8_i64, uint8_t, int64_t)\nINDEX_ADD_OP(ia_u8_u32, uint8_t, uint32_t)\nINDEX_ADD_OP(ia_u8_u8, uint8_t, uint8_t)\n#if defined(__HAVE_BFLOAT__)\nINDEX_ADD_OP(ia_u8_bf16, uint8_t, bfloat)\n#endif\n"

val GEMV: String = "// GEMV kernel adapted from MLX:\n// https://github.com/ml-explore/mlx/blob/main/mlx/backend/metal/kernels/gemv.metal\n// Copyright \u00a9 2023-2024 Apple Inc.\n\n#include <metal_simdgroup>\n#include <metal_stdlib>\n\nusing namespace metal;\n\n#define MLX_MTL_CONST static constant constexpr const\n#define MLX_MTL_PRAGMA_UNROLL _Pragma(\"clang loop unroll(full)\")\n\n// elem_to_loc for nc=1 batch handling\ntemplate <typename stride_t>\nMETAL_FUNC stride_t gemv_elem_to_loc(\n    uint elem,\n    constant const int* shape,\n    constant const stride_t* strides,\n    int ndim) {\n  stride_t loc = 0;\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    loc += (elem % shape[i]) * strides[i];\n    elem /= shape[i];\n  }\n  return loc;\n}\n\ntemplate <typename U>\nstruct GemvDefaultAccT {\n  using type = float;\n};\n\n///////////////////////////////////////////////////////////////////////////////\n/// Matrix-vector: mat [M_out, K] \u00d7 vec [K] \u2192 out [M_out]\n/// (mat rows = output dimension, mat cols = K)\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    const int BM,       // Threadgroup rows (in simdgroups)\n    const int BN,       // Threadgroup cols (in simdgroups)\n    const int SM,       // Simdgroup rows (in threads)\n    const int SN,       // Simdgroup cols (in threads)\n    const int TM,       // Thread rows (in elements)\n    const int TN,       // Thread cols (in elements)\n    const bool kDoAxpby,\n    typename AccT = typename GemvDefaultAccT<T>::type>\nstruct GEMVKernel {\n  using acc_type = AccT;\n\n  MLX_MTL_CONST int threadsM = BM * SM;\n  MLX_MTL_CONST int threadsN = BN * SN;\n\n  MLX_MTL_CONST int blockM = threadsM * TM;\n  MLX_MTL_CONST int blockN = threadsN * TN;\n\n  static_assert(SM * SN == 32, \"simdgroup must have 32 threads\");\n  static_assert(SN == 4 || SN == 8 || SN == 16 || SN == 32,\n                \"gemv block must have width 4, 8, 16, or 32\");\n\n  MLX_MTL_CONST short tgp_mem_size = BN > 1 ? BN * (blockM + TM) : 0;\n  MLX_MTL_CONST bool needs_tgp_reduction = BN > 1;\n\n  template <typename U = T>\n  static METAL_FUNC void load_unsafe(\n      const device T* src, thread U dst[TN], const int src_offset = 0) {\n    MLX_MTL_PRAGMA_UNROLL\n    for (int tn = 0; tn < TN; tn++) {\n      dst[tn] = static_cast<U>(src[src_offset + tn]);\n    }\n  }\n\n  template <typename U = T>\n  static METAL_FUNC void load_safe(\n      const device T* src,\n      thread U dst[TN],\n      const int src_offset = 0,\n      const int src_size = TN) {\n    if (src_offset + TN <= src_size) {\n      MLX_MTL_PRAGMA_UNROLL\n      for (int tn = 0; tn < TN; tn++) {\n        dst[tn] = static_cast<U>(src[src_offset + tn]);\n      }\n    } else {\n      MLX_MTL_PRAGMA_UNROLL\n      for (int tn = 0; tn < TN; tn++) {\n        dst[tn] = src_offset + tn < src_size\n            ? static_cast<U>(src[src_offset + tn])\n            : U(0);\n      }\n    }\n  }\n\n  static METAL_FUNC void run(\n      const device T* mat,\n      const device T* in_vec,\n      const device T* bias,\n      device T* out_vec,\n      const int in_vec_size,\n      const int out_vec_size,\n      const int matrix_ld,\n      const float alpha,\n      const float beta,\n      const int bias_stride,\n      threadgroup AccT* tgp_memory,\n      uint3 tid,\n      uint3 lid,\n      uint simd_gid,\n      uint simd_lid) {\n    (void)lid;\n\n    thread AccT result[TM] = {0};\n    thread T inter[TN];\n    thread AccT v_coeff[TN];\n\n    const int thrM = SN != 32 ? (int)(simd_lid / SN) : 0;\n    const int thrN = SN != 32 ? (int)(simd_lid % SN) : (int)simd_lid;\n\n    const int sgN = BN != 1 ? (int)(simd_gid % BN) : 0;\n    const int simdM = BN != 1 ? SM * (int)(simd_gid / BN) : (int)(SM * simd_gid);\n    const int simdN = BN != 1 ? SN * (int)(simd_gid % BN) : 0;\n\n    int bm = (simdM + thrM) * TM;\n    int bn = (simdN + thrN) * TN;\n\n    // Block position (output row)\n    int out_row = tid.x * blockM + bm;\n\n    if (out_row >= out_vec_size) return;\n\n    out_row = out_row + TM <= out_vec_size ? out_row : out_vec_size - TM;\n\n    mat += out_row * matrix_ld;\n\n    const int loop_stride = blockN;\n    const int in_size = in_vec_size;\n    const int n_iter = in_size / loop_stride;\n    const int last_iter = loop_stride * n_iter;\n    const int leftover = in_size - last_iter;\n\n    for (int i = 0; i < n_iter; ++i) {\n      load_unsafe<AccT>(in_vec, v_coeff, bn);\n\n      int mat_offset = 0;\n      MLX_MTL_PRAGMA_UNROLL\n      for (int tm = 0; tm < TM; tm++) {\n        load_unsafe(mat, inter, mat_offset + bn);\n        MLX_MTL_PRAGMA_UNROLL\n        for (int tn = 0; tn < TN; tn++) {\n          result[tm] += inter[tn] * v_coeff[tn];\n        }\n        mat_offset += matrix_ld;\n      }\n      bn += blockN;\n    }\n\n    if (leftover > 0) {\n      load_safe<AccT>(in_vec, v_coeff, bn, in_size);\n      MLX_MTL_PRAGMA_UNROLL\n      for (int tm = 0; tm < TM; tm++) {\n        load_safe(&mat[tm * matrix_ld], inter, bn, in_size);\n        MLX_MTL_PRAGMA_UNROLL\n        for (int tn = 0; tn < TN; tn++) {\n          result[tm] += inter[tn] * v_coeff[tn];\n        }\n      }\n    }\n\n    MLX_MTL_PRAGMA_UNROLL\n    for (int tm = 0; tm < TM; tm++) {\n      MLX_MTL_PRAGMA_UNROLL\n      for (ushort sn = (SN / 2); sn >= 1; sn >>= 1) {\n        result[tm] += simd_shuffle_down(result[tm], sn);\n      }\n    }\n\n    if (needs_tgp_reduction) {\n      threadgroup AccT* tgp_results = tgp_memory + sgN * (blockM + TM) + bm;\n      if (thrN == 0) {\n        MLX_MTL_PRAGMA_UNROLL\n        for (int tm = 0; tm < TM; tm++) {\n          tgp_results[tm] = result[tm];\n        }\n        threadgroup_barrier(mem_flags::mem_none);\n        if (sgN == 0) {\n          MLX_MTL_PRAGMA_UNROLL\n          for (int sgn = 1; sgn < BN; sgn++) {\n            MLX_MTL_PRAGMA_UNROLL\n            for (int tm = 0; tm < TM; tm++) {\n              result[tm] += tgp_results[sgn * (blockM + TM) + tm];\n            }\n          }\n        }\n      }\n    }\n\n    if (simdN == 0 && thrN == 0) {\n      MLX_MTL_PRAGMA_UNROLL\n      for (int tm = 0; tm < TM; tm++) {\n        if (kDoAxpby) {\n          out_vec[out_row + tm] =\n              static_cast<T>(alpha) * static_cast<T>(result[tm]) +\n              static_cast<T>(beta) * bias[(out_row + tm) * bias_stride];\n        } else {\n          out_vec[out_row + tm] = static_cast<T>(result[tm]);\n        }\n      }\n    }\n  }\n};\n\n///////////////////////////////////////////////////////////////////////////////\n/// Vector-matrix: vec [K] \u00d7 mat [K, N_out] \u2192 out [N_out]\n/// (mat rows = K, mat cols = output dimension)\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    const int BM,\n    const int BN,\n    const int SM,\n    const int SN,\n    const int TM,\n    const int TN,\n    const bool kDoAxpby,\n    typename AccT = typename GemvDefaultAccT<T>::type>\nstruct GEMVTKernel {\n  using acc_type = AccT;\n\n  MLX_MTL_CONST int threadsM = BM * SM;\n  MLX_MTL_CONST int threadsN = BN * SN;\n\n  MLX_MTL_CONST int blockM = threadsM * TM;\n  MLX_MTL_CONST int blockN = threadsN * TN;\n\n  static_assert(SM * SN == 32, \"simdgroup must have 32 threads\");\n\n  MLX_MTL_CONST short tgp_mem_size = BM > 1 ? BM * (blockN + TN) : 0;\n  MLX_MTL_CONST bool needs_tgp_reduction = BM > 1;\n\n  static METAL_FUNC void run(\n      const device T* mat,\n      const device T* in_vec,\n      const device T* bias,\n      device T* out_vec,\n      const int in_vec_size,\n      const int out_vec_size,\n      const int marix_ld,\n      const float alpha,\n      const float beta,\n      const int bias_stride,\n      threadgroup AccT* tgp_memory,\n      uint3 tid,\n      uint3 lid,\n      uint simd_gid,\n      uint simd_lid) {\n    (void)lid;\n\n    AccT result[TN] = {0};\n    T inter[TN];\n    AccT v_coeff[TM];\n\n    const int thrM = SN != 32 ? (int)(simd_lid / SN) : 0;\n    const int thrN = SN != 32 ? (int)(simd_lid % SN) : (int)simd_lid;\n\n    const int sgM = BN != 1 ? (int)(simd_gid / BN) : (int)simd_gid;\n    const int sgN = BN != 1 ? (int)(simd_gid % BN) : 0;\n\n    const int simdM = SM * sgM;\n    const int simdN = SN * sgN;\n\n    int cm = (simdM + thrM);\n    int cn = (simdN + thrN);\n\n    int bm = cm * TM;\n    int bn = cn * TN;\n\n    int out_col = tid.x * blockN + bn;\n\n    const int loop_stride = blockM;\n    const int in_size = in_vec_size;\n    const int n_iter = in_size / loop_stride;\n    const int last_iter = loop_stride * n_iter;\n    const int leftover = in_size - last_iter;\n\n    if (out_col < out_vec_size) {\n      out_col = out_col + TN <= out_vec_size ? out_col : out_vec_size - TN;\n\n      for (int i = 0; i < n_iter; ++i) {\n        threadgroup_barrier(mem_flags::mem_none);\n\n        MLX_MTL_PRAGMA_UNROLL\n        for (int tm = 0; tm < TM; tm++) {\n          v_coeff[tm] = static_cast<AccT>(in_vec[bm + tm]);\n        }\n\n        MLX_MTL_PRAGMA_UNROLL\n        for (int tm = 0; tm < TM; tm++) {\n          auto vc = static_cast<AccT>(v_coeff[tm]);\n          MLX_MTL_PRAGMA_UNROLL\n          for (int tn = 0; tn < TN; tn++) {\n            inter[tn] = mat[(bm + tm) * marix_ld + out_col + tn];\n          }\n          MLX_MTL_PRAGMA_UNROLL\n          for (int tn = 0; tn < TN; tn++) {\n            result[tn] += vc * inter[tn];\n          }\n        }\n\n        bm += blockM;\n      }\n\n      if (leftover > 0) {\n        for (int tm = 0; tm < TM && bm + tm < in_vec_size; tm++) {\n          v_coeff[tm] = static_cast<AccT>(in_vec[bm + tm]);\n          MLX_MTL_PRAGMA_UNROLL\n          for (int tn = 0; tn < TN; tn++) {\n            inter[tn] = mat[(bm + tm) * marix_ld + out_col + tn];\n          }\n          MLX_MTL_PRAGMA_UNROLL\n          for (int tn = 0; tn < TN; tn++) {\n            result[tn] += v_coeff[tm] * inter[tn];\n          }\n        }\n      }\n    }\n\n    MLX_MTL_PRAGMA_UNROLL\n    for (int tn = 0; tn < TN; tn++) {\n      MLX_MTL_PRAGMA_UNROLL\n      for (ushort sm = (SM / 2); sm >= 1; sm >>= 1) {\n        result[tn] += simd_shuffle_down(result[tn], SN * sm);\n      }\n    }\n\n    if (needs_tgp_reduction) {\n      threadgroup AccT* tgp_results = tgp_memory + sgM * (blockN + TN) + bn;\n      if (thrM == 0) {\n        MLX_MTL_PRAGMA_UNROLL\n        for (int tn = 0; tn < TN; tn++) {\n          tgp_results[tn] = result[tn];\n        }\n        threadgroup_barrier(mem_flags::mem_none);\n        if (sgM == 0) {\n          MLX_MTL_PRAGMA_UNROLL\n          for (int sgm = 1; sgm < BM; sgm++) {\n            MLX_MTL_PRAGMA_UNROLL\n            for (int tn = 0; tn < TN; tn++) {\n              result[tn] += tgp_results[sgm * (blockN + TN) + tn];\n            }\n          }\n        }\n      }\n    }\n\n    if (cm == 0 && out_col < out_vec_size) {\n      MLX_MTL_PRAGMA_UNROLL\n      for (int j = 0; j < TN; j++) {\n        if (kDoAxpby) {\n          out_vec[out_col + j] =\n              static_cast<T>(alpha) * static_cast<T>(result[j]) +\n              static_cast<T>(beta) * bias[(out_col + j) * bias_stride];\n        } else {\n          out_vec[out_col + j] = static_cast<T>(result[j]);\n        }\n      }\n    }\n  }\n};\n\n///////////////////////////////////////////////////////////////////////////////\n/// gemv kernel: mat [M, K] \u00d7 vec [K] \u2192 out [M]\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    const int BM, const int BN,\n    const int SM, const int SN,\n    const int TM, const int TN,\n    const bool kDoNCBatch,\n    const bool kDoAxpby>\n[[kernel, max_total_threads_per_threadgroup(BM * BN * 32)]]\nvoid gemv(\n    const device T* mat [[buffer(0)]],\n    const device T* in_vec [[buffer(1)]],\n    const device T* bias [[buffer(2)]],\n    device T* out_vec [[buffer(3)]],\n    const constant int& in_vec_size [[buffer(4)]],\n    const constant int& out_vec_size [[buffer(5)]],\n    const constant int& matrix_ld [[buffer(6)]],\n    const constant float& alpha [[buffer(7)]],\n    const constant float& beta [[buffer(8)]],\n    const constant int& batch_ndim [[buffer(9)]],\n    const constant int* batch_shape [[buffer(10)]],\n    const constant int64_t* vector_batch_stride [[buffer(11)]],\n    const constant int64_t* matrix_batch_stride [[buffer(12)]],\n    const constant int64_t* bias_batch_stride [[buffer(13)]],\n    const constant int& bias_stride [[buffer(14)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]],\n    uint simd_gid [[simdgroup_index_in_threadgroup]],\n    uint simd_lid [[thread_index_in_simdgroup]]) {\n  using kernel_t = GEMVKernel<T, BM, BN, SM, SN, TM, TN, kDoAxpby>;\n  threadgroup typename kernel_t::acc_type tgp_memory[kernel_t::tgp_mem_size == 0 ? 1 : kernel_t::tgp_mem_size];\n\n  if (kDoNCBatch) {\n    in_vec += gemv_elem_to_loc(tid.z, batch_shape, vector_batch_stride, batch_ndim);\n    mat    += gemv_elem_to_loc(tid.z, batch_shape, matrix_batch_stride, batch_ndim);\n    if (kDoAxpby)\n      bias += gemv_elem_to_loc(tid.z, batch_shape, bias_batch_stride, batch_ndim);\n  } else {\n    in_vec += tid.z * vector_batch_stride[0];\n    mat    += tid.z * matrix_batch_stride[0];\n    if (kDoAxpby)\n      bias += tid.z * bias_batch_stride[0];\n  }\n  out_vec += tid.z * out_vec_size;\n\n  kernel_t::run(mat, in_vec, bias, out_vec,\n                in_vec_size, out_vec_size, matrix_ld,\n                alpha, beta, bias_stride,\n                kernel_t::tgp_mem_size == 0 ? nullptr : tgp_memory,\n                tid, lid, simd_gid, simd_lid);\n}\n\n///////////////////////////////////////////////////////////////////////////////\n/// gemv_t kernel: vec [K] \u00d7 mat [K, N] \u2192 out [N]\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    const int BM, const int BN,\n    const int SM, const int SN,\n    const int TM, const int TN,\n    const bool kDoNCBatch,\n    const bool kDoAxpby>\n[[kernel, max_total_threads_per_threadgroup(BM * BN * 32)]]\nvoid gemv_t(\n    const device T* mat [[buffer(0)]],\n    const device T* in_vec [[buffer(1)]],\n    const device T* bias [[buffer(2)]],\n    device T* out_vec [[buffer(3)]],\n    const constant int& in_vec_size [[buffer(4)]],\n    const constant int& out_vec_size [[buffer(5)]],\n    const constant int& matrix_ld [[buffer(6)]],\n    const constant float& alpha [[buffer(7)]],\n    const constant float& beta [[buffer(8)]],\n    const constant int& batch_ndim [[buffer(9)]],\n    const constant int* batch_shape [[buffer(10)]],\n    const constant int64_t* vector_batch_stride [[buffer(11)]],\n    const constant int64_t* matrix_batch_stride [[buffer(12)]],\n    const constant int64_t* bias_batch_stride [[buffer(13)]],\n    const constant int& bias_stride [[buffer(14)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]],\n    uint simd_gid [[simdgroup_index_in_threadgroup]],\n    uint simd_lid [[thread_index_in_simdgroup]]) {\n  using kernel_t = GEMVTKernel<T, BM, BN, SM, SN, TM, TN, kDoAxpby>;\n  threadgroup typename kernel_t::acc_type tgp_memory[kernel_t::tgp_mem_size == 0 ? 1 : kernel_t::tgp_mem_size];\n\n  if (kDoNCBatch) {\n    in_vec += gemv_elem_to_loc(tid.z, batch_shape, vector_batch_stride, batch_ndim);\n    mat    += gemv_elem_to_loc(tid.z, batch_shape, matrix_batch_stride, batch_ndim);\n    if (kDoAxpby)\n      bias += gemv_elem_to_loc(tid.z, batch_shape, bias_batch_stride, batch_ndim);\n  } else {\n    in_vec += tid.z * vector_batch_stride[0];\n    mat    += tid.z * matrix_batch_stride[0];\n    if (kDoAxpby)\n      bias += tid.z * bias_batch_stride[0];\n  }\n  out_vec += tid.z * out_vec_size;\n\n  kernel_t::run(mat, in_vec, bias, out_vec,\n                in_vec_size, out_vec_size, matrix_ld,\n                alpha, beta, bias_stride,\n                kernel_t::tgp_mem_size == 0 ? nullptr : tgp_memory,\n                tid, lid, simd_gid, simd_lid);\n}\n\n///////////////////////////////////////////////////////////////////////////////\n/// Instantiations\n///////////////////////////////////////////////////////////////////////////////\n\n// Use decltype-based instantiation (MLX defines.h pattern):\n//   template [[host_name(...)]] [[kernel]] decltype(func<...>) func<...>;\n// This avoids redeclaring parameter attributes, which Metal rejects.\n#define instantiate_gemv_helper(func, nm, itype, bm, bn, sm, sn, tm, tn, nc, axpby) \\\n  template [[host_name(                                                               \\\n      #func \"_\" #nm \"_bm\" #bm \"_bn\" #bn \"_sm\" #sm \"_sn\" #sn                         \\\n            \"_tm\" #tm \"_tn\" #tn \"_nc\" #nc \"_axpby\" #axpby)]]                         \\\n  [[kernel]] decltype(func<itype, bm, bn, sm, sn, tm, tn, (bool)nc, (bool)axpby>)   \\\n             func<itype, bm, bn, sm, sn, tm, tn, (bool)nc, (bool)axpby>;\n\n#define instantiate_gemv_nc_axpby(func, nm, itype, bm, bn, sm, sn, tm, tn) \\\n  instantiate_gemv_helper(func, nm, itype, bm, bn, sm, sn, tm, tn, 0, 0)   \\\n  instantiate_gemv_helper(func, nm, itype, bm, bn, sm, sn, tm, tn, 0, 1)   \\\n  instantiate_gemv_helper(func, nm, itype, bm, bn, sm, sn, tm, tn, 1, 0)   \\\n  instantiate_gemv_helper(func, nm, itype, bm, bn, sm, sn, tm, tn, 1, 1)\n\n// gemv blocks: mat\u00d7vec (output size = M)\n// bm=4/8 for large output; bm=1,bn=8 for K-heavy; bm=1,bn=1,sm=8,sn=4 for small K\n#define instantiate_gemv_blocks(nm, itype)                              \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 1,  8, 1, 32, 4, 4)      \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 1,  8, 1, 32, 1, 4)      \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 1,  1, 8,  4, 4, 4)      \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 1,  1, 8,  4, 1, 4)      \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 4,  1, 1, 32, 1, 4)      \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 4,  1, 1, 32, 4, 4)      \\\n  instantiate_gemv_nc_axpby(gemv, nm, itype, 8,  1, 1, 32, 4, 4)\n\n// gemv_t blocks: vec\u00d7mat (output size = N)\n// bn=2/4/16 for various output sizes; sm/sn tuned for K size\n#define instantiate_gemv_t_blocks(nm, itype)                              \\\n  instantiate_gemv_nc_axpby(gemv_t, nm, itype, 1,  2,  8, 4, 4, 1)      \\\n  instantiate_gemv_nc_axpby(gemv_t, nm, itype, 1,  2,  8, 4, 4, 4)      \\\n  instantiate_gemv_nc_axpby(gemv_t, nm, itype, 1,  4,  8, 4, 4, 4)      \\\n  instantiate_gemv_nc_axpby(gemv_t, nm, itype, 1, 16,  8, 4, 4, 4)      \\\n  instantiate_gemv_nc_axpby(gemv_t, nm, itype, 1, 16,  4, 8, 4, 4)\n\ninstantiate_gemv_blocks(float32, float)\ninstantiate_gemv_blocks(float16, half)\ninstantiate_gemv_blocks(bfloat16, bfloat)\n\ninstantiate_gemv_t_blocks(float32, float)\ninstantiate_gemv_t_blocks(float16, half)\ninstantiate_gemv_t_blocks(bfloat16, bfloat)\n"

private val MLX_GEMM_PARTS: List<String> =
    listOf(
        "// MLX Kernel extracted from:\n// https://github.com/ml-explore/mlx/blob/main/mlx/backend/metal/kernels/steel/gemm\n// Copyright \u00a9 2024 Apple Inc.\n\n#include <metal_simdgroup>\n#include <metal_simdgroup_matrix>\n#include <metal_stdlib>\n\n#define STEEL_CONST static constant constexpr const\n#define STEEL_PRAGMA_UNROLL _Pragma(\"clang loop unroll(full)\")\n\nusing namespace metal;\n\n// https://github.com/ml-explore/mlx/blob/02efb310cac667bc547d1b96f21596c221f84fe7/mlx/backend/metal/kernels/steel/gemm/params.h#L1\n///////////////////////////////////////////////////////////////////////////////\n// GEMM param classes\n///////////////////////////////////////////////////////////////////////////////\n\nstruct GEMMParams {\n  const int M;\n  const int N;\n  const int K;\n\n  const int lda;\n  const int ldb;\n  const int ldd;\n\n  const int tiles_n;\n  const int tiles_m;\n\n  const size_t batch_stride_a;\n  const size_t batch_stride_b;\n  const size_t batch_stride_d;\n\n  const int swizzle_log;\n  const int gemm_k_iterations_aligned;\n\n  const int batch_ndim;\n};\n\nstruct GEMMSpiltKParams {\n  const int M;\n  const int N;\n  const int K;\n\n  const int lda;\n  const int ldb;\n  const int ldc;\n\n  const int tiles_n;\n  const int tiles_m;\n\n  const int split_k_partitions;\n  const int split_k_partition_stride;\n  const int split_k_partition_size;\n\n  const int gemm_k_iterations_aligned;\n};\n\nstruct GEMMAddMMParams {\n  const int ldc;\n  const int fdc;\n\n  const size_t batch_stride_c;\n\n  const float alpha;\n  const float beta;\n};\n\n// https://github.com/ml-explore/mlx/blob/02efb310cac667bc547d1b96f21596c221f84fe7/mlx/backend/metal/kernels/steel/gemm/loader.h#L1\n///////////////////////////////////////////////////////////////////////////////\n// Loading helper\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    short BROWS,\n    short BCOLS,\n    short dst_ld,\n    short reduction_dim,\n    short tgp_size,\n    short alignment = 1,\n    short n_reads = (BCOLS * BROWS) / (tgp_size),\n    short TCOLS = BCOLS / n_reads,\n    short TROWS = tgp_size / TCOLS>\nstruct BlockLoader {\n  STEEL_CONST short n_rows = (BROWS + TROWS - 1) / TROWS;\n  STEEL_CONST short vec_size = n_reads;\n\n  // Leading dimension for src\n  const int src_ld;\n  const int tile_stride;\n\n  // Thread location indices\n  const short thread_idx;\n  const short bi;\n  const short bj;\n\n  // threadgroup and device memory\n  threadgroup T* dst;\n  const device T* src;\n\n  struct alignas(alignment * sizeof(T)) ReadVector {\n    uint8_t v[sizeof(T) * vec_size];\n  };\n\n  /* Constructor */\n  METAL_FUNC BlockLoader(\n      const device T* src_,\n      const int src_ld_,\n      threadgroup T* dst_,\n      ushort simd_group_id [[simdgroup_index_in_threadgroup]],\n      ushort simd_lane_id [[thread_index_in_simdgroup]])\n      : src_ld(src_ld_),\n        tile_stride(reduction_dim ? BCOLS : BROWS * src_ld),\n        thread_idx(simd_group_id * 32 + simd_lane_id),\n        bi(thread_idx / TCOLS),\n        bj(vec_size * (thread_idx % TCOLS)),\n        dst(dst_ + bi * dst_ld + bj),\n        src(src_ + bi * src_ld + bj) {}\n\n  /* Apply operation to threadgroup without bound checking */\n  template <typename UnaryOp>\n  METAL_FUNC void apply_inplace_op(thread const UnaryOp& op) const {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < BROWS; i += TROWS) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < vec_size; j++) {\n        dst[i * dst_ld + j] = op.apply(dst[i * dst_ld + j]);\n      }\n    }\n  }\n\n  /* Load from device memory into threadgroup memory - without bound checking */\n  METAL_FUNC void load_unsafe() const {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < BROWS; i += TROWS) {\n      *((threadgroup ReadVector*)(&dst[i * dst_ld])) =\n          *((const device ReadVector*)(&src[i * src_ld]));\n    }\n  }\n\n  /* Load from device memory into threadgroup memory - with bound checking */\n  METAL_FUNC void load_safe(short2 src_tile_dim) const {\n    src_tile_dim = src_tile_dim - short2(bj, bi);\n\n    // Skip loading if thread has no valid reads\n    if (src_tile_dim.x <= 0 || src_tile_dim.y <= 0) {\n      STEEL_PRAGMA_UNROLL\n      for (short i = 0; i < BROWS; i += TROWS) {\n        STEEL_PRAGMA_UNROLL\n        for (short j = 0; j < vec_size; j++) {\n          dst[i * dst_ld + j] = T(0);\n        }\n      }\n      return;\n    }\n\n    // Use fast thread memory for bound checks\n    bool tmp_idx[vec_size];\n    T tmp_val[vec_size];\n\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < BROWS; i += TROWS) {\n      // Make sure tmp_idx only contains valid indices\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < vec_size; j++) {\n        tmp_idx[j] = (i < src_tile_dim.y) && (j < src_tile_dim.x);\n      }\n\n      // Read valid indices into tmp_val\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < vec_size; j++) {\n        tmp_val[j] = src[(tmp_idx[j] ? i * src_ld + j : 0)];\n      }\n\n      // Zero out unneeded values\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < vec_size; j++) {\n        tmp_val[j] = tmp_idx[j] ? tmp_val[j] : T(0);\n      }\n\n      // Copy values to threadgroup memory\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < vec_size; j++) {\n        dst[i * dst_ld + j] = tmp_val[j];\n      }\n    }\n  }\n\n  /* Iteration helper */\n  METAL_FUNC void next() {\n    src += tile_stride;\n  }\n};\n\n// https://github.com/ml-explore/mlx/blob/02efb310cac667bc547d1b96f21596c221f84fe7/mlx/backend/metal/kernels/steel/gemm/transforms.h#L1\n///////////////////////////////////////////////////////////////////////////////\n// Transforms and Epilogues\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <typename OutT, typename InT>\nstruct TransformNone {\n  static METAL_FUNC OutT apply(InT x) {\n    return static_cast<OutT>(x);\n  }\n\n  static METAL_FUNC OutT apply(InT x, OutT) {\n    return static_cast<OutT>(x);\n  }\n};\n\ntemplate <typename OutT, typename InT>\nstruct TransformAdd {\n  TransformAdd(const float, const float) {}\n\n  static METAL_FUNC OutT apply(InT x) {\n    return static_cast<OutT>(x);\n  }\n\n  static METAL_FUNC OutT apply(InT x, OutT c) {\n    return static_cast<OutT>(x) + c;\n  }\n};\n\ntemplate <typename OutT, typename InT>\nstruct TransformAxpby {\n  const float alpha;\n  const float beta;\n\n  TransformAxpby(const float alpha_, const float beta_)\n      : alpha(alpha_), beta(beta_) {}\n\n  static METAL_FUNC OutT apply(InT x) {\n    return static_cast<OutT>(x);\n  }\n\n  METAL_FUNC OutT apply(InT x, OutT c) const {\n    return static_cast<OutT>(x * alpha + (beta * c));\n  }\n};\n\ntemplate <typename T>\nstruct AccumHelper {\n  typedef float accum_type;\n};\n\nstruct BlockSwizzle {\n  static METAL_FUNC int2\n  swizzle(uint3 tid [[threadgroup_position_in_grid]], const int swizzle_log) {\n    const int tid_x = (tid.x) >> swizzle_log;\n    const int tid_y =\n        ((tid.y) << swizzle_log) + ((tid.x) & ((1 << swizzle_log) - 1));\n    return int2(tid_x, tid_y);\n  }\n};\n\n// https://github.com/ml-explore/mlx/blob/02efb310cac667bc547d1b96f21596c221f84fe7/mlx/backend/metal/kernels/steel/gemm/mma.h#L1\n///////////////////////////////////////////////////////////////////////////////\n// MMA helper\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    typename U,\n    int BM,\n    int BN,\n    int BK,\n    int WM,\n    int WN,\n    bool transpose_a,\n    bool transpose_b,\n    short lda_tgp,\n    short ldb_tgp,\n    typename AccumType = float,\n    typename Epilogue = TransformNone<U, AccumType>>\nstruct BlockMMA {\n  // Warp tile simdgroup matrix strides along M\n  STEEL_CONST short TM_stride = 8 * WM;\n  // Warp tile simdgroup matrix strides along M\n  STEEL_CONST short TN_stride = 8 * WN;\n\n  // Warp tile size along M\n  STEEL_CONST short TM = BM / TM_stride;\n  // Warp tile size along N\n  STEEL_CONST short TN = BN / TN_stride;\n\n  // Strides of A, B along reduction axis\n  STEEL_CONST short simd_stride_a = {\n      transpose_a ? TM_stride : TM_stride * lda_tgp};\n  STEEL_CONST short simd_stride_b = {\n      transpose_b ? TN_stride * ldb_tgp : TN_stride};\n\n  // Jump between elements\n  STEEL_CONST short jump_a = {transpose_a ? lda_tgp : 1};\n  STEEL_CONST short jump_b = {transpose_b ? ldb_tgp : 1};\n\n  STEEL_CONST short tile_stride_a = {transpose_a ? 8 * lda_tgp : 8};\n  STEEL_CONST short tile_stride_b = {transpose_b ? 8 : 8 * ldb_tgp};\n\n  // Simdgroup matrices\n  simdgroup_matrix<AccumType, 8, 8> Asimd[TM];\n  simdgroup_matrix<AccumType, 8, 8> Bsimd[TN];\n  simdgroup_matrix<AccumType, 8, 8> results[TM * TN] = {\n      simdgroup_matrix<AccumType, 8, 8>(0)};\n\n  // Offsets within threadgroup\n  const short tm;\n  const short tn;\n\n  short sm;\n  short sn;\n\n  short As_offset;\n  short Bs_offset;\n\n  /* Constructor */\n  METAL_FUNC BlockMMA(\n      ushort simd_group_id [[simdgroup_index_in_threadgroup]],\n      ushort simd_lane_id [[thread_index_in_simdgroup]])\n      : tm(8 * (simd_group_id / WN)), tn(8 * (simd_group_id % WN)) {\n    // Determine thread position in simdgroup matrix\n    short qid = simd_lane_id / 4;\n    sm = (qid & 4) + (simd_lane_id / 2) % 4;\n    sn = (qid & 2) * 2 + (simd_lane_id % 2) * 2;\n\n    // Determine thread and simdgroup offset\n    As_offset =\n        transpose_a ? ((sn)*lda_tgp + (tm + sm)) : ((sn) + (tm + sm) * lda_tgp);\n    Bs_offset =\n        transpose_b ? ((tn + sn) * ldb_tgp + (sm)) : ((sm)*ldb_tgp + (tn + sn));\n  }\n\n  /* (BM, BK) X (BK, BN) multiply accumulate function */\n  METAL_FUNC void mma(const threadgroup T* As, const threadgroup T* Bs) {\n    // Adjust for simdgroup and thread location\n    As += As_offset;\n    Bs += Bs_offset;\n\n    // Iterate over BK in blocks of 8\n    STEEL_PRAGMA_UNROLL\n    for (short kk = 0; kk < BK; kk += 8) {\n      simdgroup_barrier(mem_flags::mem_none);\n\n      // Load elements from threadgroup A as simdgroup matrices\n      STEEL_PRAGMA_UNROLL\n      for (short i = 0; i < TM; i++) {\n        Asimd[i].thread_elements()[0] =\n            static_cast<AccumType>(As[i * simd_stride_a + 0]);\n        Asimd[i].thread_elements()[1] =\n            static_cast<AccumType>(As[i * simd_stride_a + jump_a]);\n      }\n\n      simdgroup_barrier(mem_flags::mem_none);\n\n      // Load elements from threadgroup B as simdgroup matrices\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        Bsimd[j].thread_elements()[0] =\n            static_cast<AccumType>(Bs[j * simd_stride_b + 0]);\n        Bsimd[j].thread_elements()[1] =\n            static_cast<AccumType>(Bs[j * simd_stride_b + jump_b]);\n      }\n\n      simdgroup_barrier(mem_flags::mem_none);\n\n      // Multiply and accumulate into result simdgroup matrices\n      STEEL_PRAGMA_UNROLL\n      for (short i = 0; i < TM; i++) {\n        STEEL_PRAGMA_UNROLL\n        for (short j = 0; j < TN; j++) {\n          short j_serp = (i % 2) ? (TN - 1 - j) : j;\n\n          simdgroup_multiply_accumulate(\n              results[i * TN + j_serp],\n              Asimd[i],\n              Bsimd[j_serp],\n              results[i * TN + j_serp]);\n        }\n      }\n\n      // Progress to next simdgroup tile\n      As += tile_stride_a;\n      Bs += tile_stride_b;\n    }\n  }\n\n  /* Store results from simdgroup_matrix results into device memory */\n  METAL_FUNC void store_result(device U* D, const int ldd) const {\n    // Adjust for simdgroup and thread location\n    D += (sm + tm) * ldd + tn + sn;\n\n    // Loop over all simdgroup tiles\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < TM; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        // Get accumulated result and associated offset in C\n        thread const auto& accum = results[i * TN + j].thread_elements();\n        int offset = (i * TM_stride) * ldd + (j * TN_stride);\n\n        // Apply epilogue\n        U outs[2] = {Epilogue::apply(accum[0]), Epilogue::apply(accum[1])};\n\n        // Write out D\n        D[offset] = outs[0];\n        D[offset + 1] = outs[1];\n      }\n    }\n  }\n\n  METAL_FUNC void\n  store_result_safe(device U* D, const int ldd, short2 dst_tile_dims) const {\n    // Adjust for simdgroup and thread location\n    D += (sm + tm) * ldd + (tn + sn);\n    dst_tile_dims -= short2(tn + sn, sm + tm);\n\n    if (dst_tile_dims.x <= 0 || dst_tile_dims.y <= 0)\n      return;\n\n    STEEL_PRAGMA_UNROLL\n    for (int i = 0; i < TM; i++) {\n      if (i * TM_stride < dst_tile_dims.y) {\n        STEEL_PRAGMA_UNROLL\n        for (int j = 0; j < TN; j++) {\n          // Get accumulated result and associated offset in C\n          thread const auto& accum = results[i * TN + j].thread_elements();\n          int offset = (i * TM_stride) * ldd + (j * TN_stride);\n\n          // Apply epilogue and output C\n          if (j * TN_stride < dst_tile_dims.x) {\n            D[offset] = Epilogue::apply(accum[0]);\n          }\n\n          if (j * TN_stride + 1 < dst_tile_dims.x) {\n            D[offset + 1] = Epilogue::apply(accum[1]);\n          }\n        }\n      }\n    }\n  }\n\n  /* Apply epilogue */\n  template <typename UnaryEpilogue>\n  METAL_FUNC void apply_epilogue(thread const UnaryEpilogue& epilogue_op) {\n    // Loop over all simdgroup tiles\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < TM; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        // Get accumulated result and associated offset in C\n        thread auto& accum = results[i * TN + j].thread_elements();\n\n        // Apply epilogue\n        accum[0] = epilogue_op.apply(accum[0]);\n        accum[1] = epilogue_op.apply(accum[1]);\n      }\n    }\n  }\n\n  /* Apply epilogue */\n  template <typename BinaryEpilogue>\n  METAL_FUNC void apply_epilogue(\n      const device U* C,\n      const int ldc,\n      const int fdc,\n      thread const BinaryEpilogue& epilogue_op) {\n    // Adjust for simdgroup and thread location\n    C += (sm + tm) * ldc + (tn + sn) * fdc;\n\n    // Loop over all simdgroup tiles\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < TM; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        // Get accumulated result and associated offset in C\n        thread auto& accum = results[i * TN + j].thread_elements();\n        int offset_c = (i * TM_stride) * ldc + (j * TN_stride) * fdc;\n\n        // Apply epilogue\n        accum[0] = epilogue_op.apply(accum[0], C[offset_c]);\n        accum[1] = epilogue_op.apply(accum[1], C[offset_c + fdc]);\n      }\n    }\n  }\n\n  /* Apply epilogue */\n  template <typename BinaryEpilogue>\n  METAL_FUNC void apply_epilogue_safe(\n      const device U* C,\n      const int ldc,\n      const int fdc,\n      short2 dst_tile_dims,\n      thread const BinaryEpilogue& epilogue_op) {\n    // Adjust for simdgroup and thread location\n    C += (sm + tm) * ldc + (tn + sn) * fdc;\n    dst_tile_dims -= short2(tn + sn, sm + tm);\n\n    if (dst_tile_dims.x <= 0 || dst_tile_dims.y <= 0)\n      return;\n\n    // Loop over all simdgroup tiles\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < TM; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        // Get accumulated result and associated offset in C\n        thread auto& accum = results[i * TN + j].thread_elements();\n        int offset_c = (i * TM_stride) * ldc + (j * TN_stride) * fdc;\n\n        // Read C\n        U c_elems[2] = {0};\n\n        if ((j * TN_stride + 1) < dst_tile_dims.x) {\n          c_elems[0] = C[offset_c];\n          c_elems[1] = C[offset_c + fdc];\n        } else if ((j * TN_stride) < dst_tile_dims.x) {\n          c_elems[0] = C[offset_c];\n        }\n\n        // Apply epilogue\n        accum[0] = epilogue_op.apply(accum[0], c_elems[0]);\n        accum[1] = epilogue_op.apply(accum[1], c_elems[1]);\n      }\n    }\n  }\n\n  /* Store results from simdgroup_matrix results into device memory */\n  METAL_FUNC void store_result(\n      device U* D,\n      const int ldd,\n      const device U* C,\n      const int ldc,\n      const int fdc,\n      thread const Epilogue& epilogue_op) const {\n    // Adjust for simdgroup and thread location\n    C += (sm + tm) * ldc + (tn + sn) * fdc;\n    D += (sm + tm) * ldd + tn + sn;\n\n    // Loop over all simdgroup tiles\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < TM; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        // Get accumulated result and associated offset in C\n        thread const auto& accum = results[i * TN + j].thread_elements();\n        int offset_c = (i * TM_stride) * ldc + (j * TN_stride) * fdc;\n        int offset_d = (i * TM_stride) * ldd + (j * TN_stride);\n\n        // Apply epilogue\n        U outs[2] = {\n            epilogue_op.apply(accum[0], C[offset_c]),\n            epilogue_op.apply(accum[1], C[offset_c + fdc])};\n\n        // Write out D\n        D[offset_d] = outs[0];\n        D[offset_d + 1] = outs[1];\n      }\n    }\n  }\n\n  METAL_FUNC void store_result_safe(\n      device U* D,\n      const int ldd,\n      const device U* C,\n      const int ldc,\n      const int fdc,\n      short2 dst_tile_dims,\n      thread const Epilogue& epilogue_op) const {\n    // Adjust for simdgroup and thread location\n    C += (sm + tm) * ldc + (tn + sn) * fdc;\n    D += (sm + tm) * ldd + tn + sn;\n    dst_tile_dims -= short2(tn + sn, sm + tm);\n\n    if (dst_tile_dims.x <= 0 || dst_tile_dims.y <= 0)\n      return;\n\n    STEEL_PRAGMA_UNROLL\n    for (int i = 0; i < TM; i++) {\n      if (i * TM_stride < dst_tile_dims.y) {\n        STEEL_PRAGMA_UNROLL\n        for (int j = 0; j < TN; j++) {\n          // Get accumulated result and associated offset in C\n          thread const auto& accum = results[i * TN + j].thread_elements();\n          int offset_c = (i * TM_stride) * ldc + (j * TN_stride) * fdc;\n          int offset_d = (i * TM_stride) * ldd + (j * TN_stride);\n\n          // Apply epilogue and output C\n          if (j * TN_stride < dst_tile_dims.x) {\n            D[offset_d] = epilogue_op.apply(accum[0], C[offset_c]);\n          }\n\n          if (j * TN_stride + 1 < dst_tile_dims.x) {\n            D[offset_d + 1] = epilogue_op.apply(accum[1], C[offset_c + fdc]);\n          }\n        }\n      }\n    }\n  }\n};\n\n// https://github.com/ml-explore/mlx/blob/02efb310cac667bc547d1b96f21596c221f84fe7/mlx/backend/metal/kernels/steel/gemm/gemm.h#L1\n///////////////////////////////////////////////////////////////////////////////\n// GEMM kernel class\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <bool M_aligned, bool N_aligned, bool K_aligned>\nstruct LoopAlignment {};\n\ntemplate <\n    typename T,\n    typename U,\n    int BM,\n    int BN,\n    int BK,\n    int WM,\n    int WN,\n    bool transpose_a,\n    bool transpose_b,\n    bool MN_aligned,\n    bool K_aligned,\n    typename AccumType = typename AccumHelper<T>::accum_type,\n    typename Epilogue = TransformNone<U, AccumType>>\nstruct GEMMKernel {\n  STEEL_CONST short tgp_padding_a = 16 / sizeof(T);\n  STEEL_CONST short tgp_padding_b = 16 / sizeof(T);\n  STEEL_CONST short tgp_mem_size_a =\n      transpose_a ? BK * (BM + tgp_padding_a) : BM * (BK + tgp_padding_a);\n  STEEL_CONST short tgp_mem_size_b =\n      transpose_b ? BN * (BK + tgp_padding_b) : BK * (BN + tgp_padding_b);\n  STEEL_CONST short tgp_mem_size = tgp_mem_size_a + tgp_mem_size_b;\n\n  STEEL_CONST short tgp_size = WM * WN * 32;\n\n  using loader_a_t = BlockLoader<\n      T,\n      transpose_a ? BK : BM,\n      transpose_a ? BM : BK,\n      transpose_a ? BM + tgp_padding_a : BK + tgp_padding_a,\n      !transpose_a,\n      tgp_size>;\n  using loader_b_t = BlockLoader<\n      T,\n      transpose_b ? BN : BK,\n      transpose_b ? BK : BN,\n      transpose_b ? BK + tgp_padding_b : BN + tgp_padding_b,\n      transpose_b,\n      tgp_size>;\n  using mma_t = BlockMMA<\n      T,\n      U,\n      BM,\n      BN,\n      BK,\n      WM,\n      WN,\n      transpose_a,\n      transpose_b,\n      transpose_a ? BM + tgp_padding_a : BK + tgp_padding_a,\n      transpose_b ? BK + tgp_padding_b : BN + tgp_padding_b,\n      AccumType,\n      Epilogue>;\n\n  /* Main kernel function */\n  template <bool M_aligned, bool N_aligned, bool K_aligned_>\n  static METAL_FUNC void gemm_loop(\n      threadgroup T* As [[threadgroup(0)]],\n      threadgroup T* Bs [[threadgroup(1)]],\n      const int gemm_k_iterations,\n      thread loader_a_t& loader_a,\n      thread loader_b_t& loader_b,\n      thread mma",
        "_t& mma_op,\n      thread const short& tgp_bm,\n      thread const short& tgp_bn,\n      thread const short& lbk,\n      LoopAlignment<M_aligned, N_aligned, K_aligned_> l = {}) {\n    // Appease the compiler\n    (void)l;\n\n    short2 tile_dims_A = transpose_a ? short2(tgp_bm, BK) : short2(BK, tgp_bm);\n\n    short2 tile_dims_B = transpose_b ? short2(BK, tgp_bn) : short2(tgp_bn, BK);\n\n    for (int k = 0; k < gemm_k_iterations; k++) {\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n      // Load elements into threadgroup\n      if (M_aligned) {\n        loader_a.load_unsafe();\n      } else {\n        loader_a.load_safe(tile_dims_A);\n      }\n\n      if (N_aligned) {\n        loader_b.load_unsafe();\n      } else {\n        loader_b.load_safe(tile_dims_B);\n      }\n\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n\n      // Multiply and accumulate threadgroup elements\n      mma_op.mma(As, Bs);\n\n      // Prepare for next iteration\n      loader_a.next();\n      loader_b.next();\n    }\n\n    if (!K_aligned_) {\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n\n      short2 tile_dims_A_last =\n          transpose_a ? short2(tgp_bm, lbk) : short2(lbk, tgp_bm);\n      short2 tile_dims_B_last =\n          transpose_b ? short2(lbk, tgp_bn) : short2(tgp_bn, lbk);\n\n      loader_a.load_safe(tile_dims_A_last);\n      loader_b.load_safe(tile_dims_B_last);\n\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n\n      mma_op.mma(As, Bs);\n    }\n  }\n\n  /* Main kernel function */\n  static METAL_FUNC void run(\n      const device T* A [[buffer(0)]],\n      const device T* B [[buffer(1)]],\n      device U* D [[buffer(2)]],\n      const constant GEMMParams* params [[buffer(3)]],\n      threadgroup T* As [[threadgroup(0)]],\n      threadgroup T* Bs [[threadgroup(1)]],\n      uint simd_lane_id [[thread_index_in_simdgroup]],\n      uint simd_group_id [[simdgroup_index_in_threadgroup]],\n      uint3 tid [[threadgroup_position_in_grid]],\n      uint3 lid [[thread_position_in_threadgroup]]) {\n    // Pacifying compiler\n    (void)lid;\n\n    const int tid_y = ((tid.y) << params->swizzle_log) +\n        ((tid.x) & ((1 << params->swizzle_log) - 1));\n    const int tid_x = (tid.x) >> params->swizzle_log;\n\n    if (params->tiles_n <= tid_x || params->tiles_m <= tid_y) {\n      return;\n    }\n\n    threadgroup_barrier(mem_flags::mem_none);\n\n    // Find block in A, B, C\n    const int c_row = tid_y * BM;\n    const int c_col = tid_x * BN;\n    const size_t c_row_long = size_t(c_row);\n    const size_t c_col_long = size_t(c_col);\n\n    A += transpose_a ? c_row_long : c_row_long * params->lda;\n    B += transpose_b ? c_col_long * params->ldb : c_col_long;\n    D += c_row_long * params->ldd + c_col_long;\n\n    // Prepare threadgroup loading operations\n    thread loader_a_t loader_a(A, params->lda, As, simd_group_id, simd_lane_id);\n    thread loader_b_t loader_b(B, params->ldb, Bs, simd_group_id, simd_lane_id);\n\n    // Prepare threadgroup mma operation\n    thread mma_t mma_op(simd_group_id, simd_lane_id);\n\n    int gemm_k_iterations = params->gemm_k_iterations_aligned;\n\n    ///////////////////////////////////////////////////////////////////////////////\n    // MNK aligned loop\n    if (MN_aligned) {\n      for (int k = 0; k < gemm_k_iterations; k++) {\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n        // Load elements into threadgroup\n        loader_a.load_unsafe();\n        loader_b.load_unsafe();\n\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n\n        // Multiply and accumulate threadgroup elements\n        mma_op.mma(As, Bs);\n\n        // Prepare for next iteration\n        loader_a.next();\n        loader_b.next();\n      }\n\n      threadgroup_barrier(mem_flags::mem_none);\n\n      // Loop tail\n      if (!K_aligned) {\n        int lbk = params->K - params->gemm_k_iterations_aligned * BK;\n        short2 tile_dims_A = transpose_a ? short2(BM, lbk) : short2(lbk, BM);\n        short2 tile_dims_B = transpose_b ? short2(lbk, BN) : short2(BN, lbk);\n\n        loader_a.load_safe(tile_dims_A);\n        loader_b.load_safe(tile_dims_B);\n\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n\n        mma_op.mma(As, Bs);\n      }\n\n      // Store results to device memory\n      mma_op.store_result(D, params->ldd);\n      return;\n\n    }\n    ///////////////////////////////////////////////////////////////////////////////\n    // MN unaligned loop\n    else { // Loop over K - unaligned case\n      short tgp_bm = min(BM, params->M - c_row);\n      short tgp_bn = min(BN, params->N - c_col);\n      short leftover_bk = params->K - params->gemm_k_iterations_aligned * BK;\n\n      if (tgp_bm == BM && tgp_bn == BN) {\n        gemm_loop<true, true, K_aligned>(\n            As,\n            Bs,\n            gemm_k_iterations,\n            loader_a,\n            loader_b,\n            mma_op,\n            tgp_bm,\n            tgp_bn,\n            leftover_bk);\n\n        mma_op.store_result(D, params->ldd);\n        return;\n\n      } else if (tgp_bn == BN) {\n        gemm_loop<false, true, K_aligned>(\n            As,\n            Bs,\n            gemm_k_iterations,\n            loader_a,\n            loader_b,\n            mma_op,\n            tgp_bm,\n            tgp_bn,\n            leftover_bk);\n\n        mma_op.store_result_safe(D, params->ldd, short2(tgp_bn, tgp_bm));\n        return;\n\n      } else if (tgp_bm == BM) {\n        gemm_loop<true, false, K_aligned>(\n            As,\n            Bs,\n            gemm_k_iterations,\n            loader_a,\n            loader_b,\n            mma_op,\n            tgp_bm,\n            tgp_bn,\n            leftover_bk);\n\n        mma_op.store_result_safe(D, params->ldd, short2(tgp_bn, tgp_bm));\n        return;\n\n      } else {\n        gemm_loop<false, false, K_aligned>(\n            As,\n            Bs,\n            gemm_k_iterations,\n            loader_a,\n            loader_b,\n            mma_op,\n            tgp_bm,\n            tgp_bn,\n            leftover_bk);\n\n        mma_op.store_result_safe(D, params->ldd, short2(tgp_bn, tgp_bm));\n        return;\n      }\n    }\n  }\n};\n\n// utils.h\n///////////////////////////////////////////////////////////////////////////////\n// Single Array with generic dims\n\ntemplate <typename stride_t>\nMETAL_FUNC stride_t elem_to_loc(\n    uint elem,\n    device const int* shape,\n    device const stride_t* strides,\n    int ndim) {\n  stride_t loc = 0;\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    loc += (elem % shape[i]) * strides[i];\n    elem /= shape[i];\n  }\n  return loc;\n}\n\ntemplate <typename stride_t>\nMETAL_FUNC stride_t elem_to_loc(\n    uint elem,\n    constant const int* shape,\n    constant const stride_t* strides,\n    int ndim) {\n  stride_t loc = 0;\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    loc += (elem % shape[i]) * strides[i];\n    elem /= shape[i];\n  }\n  return loc;\n}\n\ntemplate <typename stride_t>\nMETAL_FUNC stride_t elem_to_loc(\n    stride_t elem,\n    device const int* shape,\n    device const stride_t* strides,\n    int ndim) {\n  stride_t loc = 0;\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    loc += (elem % shape[i]) * strides[i];\n    elem /= shape[i];\n  }\n  return loc;\n}\n\ntemplate <typename stride_t>\nMETAL_FUNC stride_t elem_to_loc(\n    stride_t elem,\n    constant const int* shape,\n    constant const stride_t* strides,\n    int ndim) {\n  stride_t loc = 0;\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    loc += (elem % shape[i]) * strides[i];\n    elem /= shape[i];\n  }\n  return loc;\n}\n\n// Non templated version to handle arbitrary dims\ntemplate <typename stride_t>\nMETAL_FUNC stride_t elem_to_loc(\n    uint3 elem,\n    constant const int* shape,\n    constant const stride_t* strides,\n    int ndim) {\n  stride_t loc = elem.x * strides[ndim - 1] + elem.y * strides[ndim - 2];\n  for (int d = ndim - 3; d >= 0; --d) {\n    loc += (elem.z % shape[d]) * strides[d];\n    elem.z /= shape[d];\n  }\n  return loc;\n}\n\n\nMETAL_FUNC ulong2 elem_to_loc_broadcast(\n    uint elem,\n    constant const int* shape,\n    constant const size_t* a_strides,\n    constant const size_t* b_strides,\n    int ndim) {\n  ulong loc_a{0};\n  ulong loc_b{0};\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    int pos_in_dim = (elem % shape[i]);\n    elem /= shape[i];\n    loc_a += pos_in_dim * a_strides[i];\n    loc_b += pos_in_dim * b_strides[i];\n  }\n  return ulong2(loc_a, loc_b);\n}\n\nMETAL_FUNC ulong3 elem_to_loc_broadcast(\n    uint elem,\n    constant const int* shape,\n    constant const size_t* a_strides,\n    constant const size_t* b_strides,\n    constant const size_t* c_strides,\n    int ndim) {\n  ulong loc_a{0};\n  ulong loc_b{0};\n  ulong loc_c{0};\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    int pos_in_dim = (elem % shape[i]);\n    elem /= shape[i];\n    loc_a += pos_in_dim * a_strides[i];\n    loc_b += pos_in_dim * b_strides[i];\n    loc_c += pos_in_dim * c_strides[i];\n  }\n  return ulong3(loc_a, loc_b, loc_c);\n}\n\n\n// https://github.com/ml-explore/mlx/blob/02efb310cac667bc547d1b96f21596c221f84fe7/mlx/backend/metal/kernels/steel/gemm/kernels/steel_gemm_fused.h#L1\n///////////////////////////////////////////////////////////////////////////////\n// GEMM kernels\n///////////////////////////////////////////////////////////////////////////////\n\nconstant bool has_batch [[function_constant(10)]];\n\nconstant bool use_out_source [[function_constant(100)]];\nconstant bool do_axpby [[function_constant(110)]];\n\nconstant bool align_M [[function_constant(200)]];\nconstant bool align_N [[function_constant(201)]];\nconstant bool align_K [[function_constant(202)]];\n\nconstant bool do_gather [[function_constant(300)]];\n\nconstant bool gather_bias = do_gather && use_out_source;\n\n// clang-format off\ntemplate <\n    typename T,\n    int BM,\n    int BN,\n    int BK,\n    int WM,\n    int WN,\n    bool transpose_a,\n    bool transpose_b,\n    typename AccumType = float>\n[[kernel, max_total_threads_per_threadgroup(WM* WN * 32)]] void gemm(\n    const device T* A [[buffer(0)]],\n    const device T* B [[buffer(1)]],\n    const device T* C [[buffer(2), function_constant(use_out_source)]],\n    device T* D [[buffer(3)]],\n    const constant GEMMParams* params [[buffer(4)]],\n    const constant GEMMAddMMParams* addmm_params [[buffer(5), function_constant(use_out_source)]],\n    const constant int* batch_shape [[buffer(6), function_constant(has_batch)]],\n    const constant size_t* batch_strides [[buffer(7), function_constant(has_batch)]],\n    const constant uint32_t* lhs_indices [[buffer(10), function_constant(do_gather)]],\n    const constant uint32_t* rhs_indices [[buffer(11), function_constant(do_gather)]],\n    const constant uint32_t* C_indices [[buffer(12), function_constant(gather_bias)]],\n    const constant int* operand_shape [[buffer(13), function_constant(do_gather)]],\n    const constant size_t* operand_strides [[buffer(14), function_constant(do_gather)]],\n    const constant packed_int3& operand_batch_ndim [[buffer(15), function_constant(do_gather)]],\n    uint simd_lane_id [[thread_index_in_simdgroup]],\n    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]]) { // clang-format on\n  // Pacifying compiler\n  (void)lid;\n\n  using gemm_kernel = GEMMKernel<\n      T,\n      T,\n      BM,\n      BN,\n      BK,\n      WM,\n      WN,\n      transpose_a,\n      transpose_b,\n      true,\n      true,\n      AccumType>;\n\n  using loader_a_t = typename gemm_kernel::loader_a_t;\n  using loader_b_t = typename gemm_kernel::loader_b_t;\n  using mma_t = typename gemm_kernel::mma_t;\n\n  // Find block\n  const int tid_y = ((tid.y) << params->swizzle_log) +\n      ((tid.x) & ((1 << params->swizzle_log) - 1));\n  const int tid_x = (tid.x) >> params->swizzle_log;\n\n  // Exit early if out of bounds\n  if (params->tiles_n <= tid_x || params->tiles_m <= tid_y) {\n    return;\n  }\n\n  // Adjust for batch\n\n  // Handle gather\n  if (do_gather) {\n    // Read indices\n    uint32_t indx_A, indx_B, indx_C;\n\n    if (has_batch) {\n      const constant size_t* indx_A_bstrides = batch_strides;\n      const constant size_t* indx_B_bstrides =\n          batch_strides + params->batch_ndim;\n\n      ulong2 indx_offsets = elem_to_loc_broadcast(\n          tid.z,\n          batch_shape,\n          indx_A_bstrides,\n          indx_B_bstrides,\n          params->batch_ndim);\n      indx_A = lhs_indices[indx_offsets.x];\n      indx_B = rhs_indices[indx_offsets.y];\n\n      if (use_out_source) {\n        const constant size_t* indx_C_bstrides =\n            indx_B_bstrides + params->batch_ndim;\n        auto indx_offset_C = elem_to_loc(\n            tid.z, batch_shape, indx_C_bstrides, params->batch_ndim);\n        indx_C = C_indices[indx_offset_C];\n      }\n    } else {\n      indx_A = lhs_indices[params->batch_stride_a * tid.z];\n      indx_B = rhs_indices[params->batch_stride_b * tid.z];\n\n      if (use_out_source) {\n        indx_C = C_indices[addmm_params->batch_stride_c * tid.z];\n      }\n    }\n\n    // Translate indices to offsets\n    int batch_ndim_A = operand_batch_ndim.x;\n    const constant int* batch_shape_A = operand_shape;\n    const constant size_t* batch_strides_A = operand_strides;\n    A += elem_to_loc(indx_A, batch_shape_A, batch_strides_A, batch_ndim_A);\n\n    int batch_ndim_B = operand_batch_ndim.y;\n    const constant int* batch_shape_B = batch_shape_A + batch_ndim_A;\n    const constant size_t* batch_strides_B = batch_strides_A + batch_ndim_A;\n    B += elem_to_loc(indx_B, batch_shape_B, batch_strides_B, batch_ndim_B);\n\n    if (use_out_source) {\n      int batch_ndim_C = operand_batch_ndim.z;\n      const constant int* batch_shape_C = batch_shape_B + batch_ndim_B;\n      const constant size_t* batch_strides_C = batch_strides_B + batch_ndim_B;\n      C += elem_to_loc(indx_C, batch_shape_C, batch_strides_C, batch_ndim_C);\n    }\n\n  }\n\n  // Handle regular batch\n  else {\n    if (has_batch) {\n      const constant size_t* A_bstrides = batch_strides;\n      const constant size_t* B_bstrides = batch_strides + params->batch_ndim;\n\n      ulong2 batch_offsets = elem_to_loc_broadcast(\n          tid.z, batch_shape, A_bstrides, B_bstrides, params->batch_ndim);\n\n      A += batch_offsets.x;\n      B += batch_offsets.y;\n\n      if (use_out_source) {\n        const constant size_t* C_bstrides = B_bstrides + params->batch_ndim;\n        C += elem_to_loc(tid.z, batch_shape, C_bstrides, params->batch_ndim);\n      }\n    } else {\n      A += params->batch_stride_a * tid.z;\n      B += params->batch_stride_b * tid.z;\n\n      if (use_out_source) {\n        C += addmm_params->batch_stride_c * tid.z;\n      }\n    }\n  }\n\n  D += params->batch_stride_d * tid.z;\n\n  // Prepare threadgroup memory\n  threadgroup T As[gemm_kernel::tgp_mem_size_a];\n  threadgroup T Bs[gemm_kernel::tgp_mem_size_b];\n\n  threadgroup_barrier(mem_flags::mem_none);\n\n  // Find block in A, B, C\n  const int c_row = tid_y * BM;\n  const int c_col = tid_x * BN;\n  const size_t c_row_long = size_t(c_row);\n  const size_t c_col_long = size_t(c_col);\n\n  A += transpose_a ? c_row_long : c_row_long * params->lda;\n  B += transpose_b ? c_col_long * params->ldb : c_col_long;\n  D += c_row_long * params->ldd + c_col_long;\n\n  if (use_out_source) {\n    C += c_row_long * addmm_params->ldc + c_col_long * addmm_params->fdc;\n  }\n\n  // Prepare threadgroup mma operation\n  thread mma_t mma_op(simd_group_id, simd_lane_id);\n\n  // Prepare threadgroup loading operations\n  thread loader_a_t loader_a(A, params->lda, As, simd_group_id, simd_lane_id);\n  thread loader_b_t loader_b(B, params->ldb, Bs, simd_group_id, simd_lane_id);\n\n  // Prepare threadgroup bounds\n  const short tgp_bm = align_M ? BM : short(min(BM, params->M - c_row));\n  const short tgp_bn = align_N ? BN : short(min(BN, params->N - c_col));\n\n  // Prepare iterations\n  int gemm_k_iterations = params->gemm_k_iterations_aligned;\n\n  // Do unaligned K iterations first\n  if (!align_K) {\n    const int k_last = params->gemm_k_iterations_aligned * BK;\n    const int k_remain = params->K - k_last;\n    const size_t k_jump_a =\n        transpose_a ? params->lda * size_t(k_last) : size_t(k_last);\n    const size_t k_jump_b =\n        transpose_b ? size_t(k_last) : params->ldb * size_t(k_last);\n\n    // Move loader source ahead to end\n    loader_a.src += k_jump_a;\n    loader_b.src += k_jump_b;\n\n    // Load tile\n    const short2 tile_dims_A =\n        transpose_a ? short2(tgp_bm, k_remain) : short2(k_remain, tgp_bm);\n    const short2 tile_dims_B =\n        transpose_b ? short2(k_remain, tgp_bn) : short2(tgp_bn, k_remain);\n\n    loader_a.load_safe(tile_dims_A);\n    loader_b.load_safe(tile_dims_B);\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    // Do matmul\n    mma_op.mma(As, Bs);\n\n    // Reset source back to start\n    loader_a.src -= k_jump_a;\n    loader_b.src -= k_jump_b;\n  }\n\n  const TransformAdd<AccumType, AccumType> epilogue_op_add(\n      addmm_params->alpha, addmm_params->beta);\n  const TransformAxpby<AccumType, AccumType> epilogue_op_axpby(\n      addmm_params->alpha, addmm_params->beta);\n\n  ///////////////////////////////////////////////////////////////////////////////\n  // MNK aligned loop\n  if (align_M && align_N) {\n    // Do gemm\n    for (int k = 0; k < gemm_k_iterations; k++) {\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n      // Load elements into threadgroup\n      loader_a.load_unsafe();\n      loader_b.load_unsafe();\n\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n\n      // Multiply and accumulate threadgroup elements\n      mma_op.mma(As, Bs);\n\n      // Prepare for next iteration\n      loader_a.next();\n      loader_b.next();\n    }\n\n    threadgroup_barrier(mem_flags::mem_none);\n\n    // Do epilogue\n    if (use_out_source) {\n      if (do_axpby) {\n        mma_op.apply_epilogue(\n            C, addmm_params->ldc, addmm_params->fdc, epilogue_op_axpby);\n      } else {\n        mma_op.apply_epilogue(\n            C, addmm_params->ldc, addmm_params->fdc, epilogue_op_add);\n      }\n    }\n\n    // Store results to device memory\n    return mma_op.store_result(D, params->ldd);\n\n  }\n  ///////////////////////////////////////////////////////////////////////////////\n  // MN unaligned loop\n  else { // Loop over K - unaligned case\n    const int leftover_bk = 0;\n\n    if ((align_M || tgp_bm == BM) && (align_N || tgp_bn == BN)) {\n      // Do gemm\n      gemm_kernel::gemm_loop(\n          As,\n          Bs,\n          gemm_k_iterations,\n          loader_a,\n          loader_b,\n          mma_op,\n          tgp_bm,\n          tgp_bn,\n          leftover_bk,\n          LoopAlignment<true, true, true>{});\n\n      // Do epilogue\n      if (use_out_source) {\n        if (do_axpby) {\n          mma_op.apply_epilogue(\n              C, addmm_params->ldc, addmm_params->fdc, epilogue_op_axpby);\n        } else {\n          mma_op.apply_epilogue(\n              C, addmm_params->ldc, addmm_params->fdc, epilogue_op_add);\n        }\n      }\n\n      // Store results to device memory\n      return mma_op.store_result(D, params->ldd);\n\n    } else if (align_N || tgp_bn == BN) {\n      gemm_kernel::gemm_loop(\n          As,\n          Bs,\n          gemm_k_iterations,\n          loader_a,\n          loader_b,\n          mma_op,\n          tgp_bm,\n          tgp_bn,\n          leftover_bk,\n          LoopAlignment<false, true, true>{});\n\n      // Do epilogue\n      if (use_out_source) {\n        if (do_axpby) {\n          mma_op.apply_epilogue_safe(\n              C,\n              addmm_params->ldc,\n              addmm_params->fdc,\n              short2(tgp_bn, tgp_bm),\n              epilogue_op_axpby);\n        } else {\n          mma_op.apply_epilogue_safe(\n              C,\n              addmm_params->ldc,\n              addmm_params->fdc,\n              short2(tgp_bn, tgp_bm),\n              epilogue_op_add);\n        }\n      }\n\n      // Store results to device memory\n      return mma_op.store_result_safe(D, params->ldd, short2(tgp_bn, tgp_bm));\n\n    } else if (align_M || tgp_bm == BM) {\n      gemm_kernel::gemm_loop(\n          As,\n          Bs,\n          gemm_k_iterations,\n          loader_a,\n          loader_b,\n          mma_op,\n          tgp_bm,\n          tgp_bn,\n          leftover_bk,\n          LoopAlignment<true, false,",
        " true>{});\n\n      // Do epilogue\n      if (use_out_source) {\n        if (do_axpby) {\n          mma_op.apply_epilogue_safe(\n              C,\n              addmm_params->ldc,\n              addmm_params->fdc,\n              short2(tgp_bn, tgp_bm),\n              epilogue_op_axpby);\n        } else {\n          mma_op.apply_epilogue_safe(\n              C,\n              addmm_params->ldc,\n              addmm_params->fdc,\n              short2(tgp_bn, tgp_bm),\n              epilogue_op_add);\n        }\n      }\n\n      // Store results to device memory\n      return mma_op.store_result_safe(D, params->ldd, short2(tgp_bn, tgp_bm));\n\n    } else {\n      gemm_kernel::gemm_loop(\n          As,\n          Bs,\n          gemm_k_iterations,\n          loader_a,\n          loader_b,\n          mma_op,\n          tgp_bm,\n          tgp_bn,\n          leftover_bk,\n          LoopAlignment<false, false, true>{});\n\n      // Do epilogue\n      if (use_out_source) {\n        if (do_axpby) {\n          mma_op.apply_epilogue_safe(\n              C,\n              addmm_params->ldc,\n              addmm_params->fdc,\n              short2(tgp_bn, tgp_bm),\n              epilogue_op_axpby);\n        } else {\n          mma_op.apply_epilogue_safe(\n              C,\n              addmm_params->ldc,\n              addmm_params->fdc,\n              short2(tgp_bn, tgp_bm),\n              epilogue_op_add);\n        }\n      }\n\n      // Store results to device memory\n      return mma_op.store_result_safe(D, params->ldd, short2(tgp_bn, tgp_bm));\n    }\n  }\n}\n\n#define instantiate_gemm(tname, trans_a, trans_b, iname, itype, oname, otype, bm, bn, bk, wm, wn) \\\n  template [[host_name(\"gemm_\" #tname \"_\"  #iname \"_\" #oname \"_\" #bm \"_\" #bn \"_\" #bk \"_\" #wm \"_\" #wn)]] \\\n  [[kernel]] void gemm<itype, bm, bn, bk, wm, wn, trans_a, trans_b, float>( \\\n      const device itype *A [[buffer(0)]], \\\n      const device itype *B [[buffer(1)]], \\\n      const device itype *C [[buffer(2), function_constant(use_out_source)]], \\\n      device itype *D [[buffer(3)]], \\\n      const constant GEMMParams* params [[buffer(4)]], \\\n      const constant GEMMAddMMParams* addmm_params [[buffer(5), function_constant(use_out_source)]], \\\n      const constant int* batch_shape [[buffer(6)]], \\\n      const constant size_t* batch_strides [[buffer(7)]], \\\n      const constant uint32_t* lhs_indices [[buffer(10), function_constant(do_gather)]], \\\n      const constant uint32_t* rhs_indices [[buffer(11), function_constant(do_gather)]], \\\n      const constant uint32_t* C_indices [[buffer(12), function_constant(gather_bias)]], \\\n      const constant int* operand_shape [[buffer(13), function_constant(do_gather)]], \\\n      const constant size_t* operand_strides [[buffer(14), function_constant(do_gather)]], \\\n      const constant packed_int3& operand_batch_ndim [[buffer(15), function_constant(do_gather)]], \\\n      uint simd_lane_id [[thread_index_in_simdgroup]], \\\n      uint simd_group_id [[simdgroup_index_in_threadgroup]], \\\n      uint3 tid [[threadgroup_position_in_grid]], \\\n      uint3 lid [[thread_position_in_threadgroup]]);\n\n#define instantiate_gemm_transpose_helper(iname, itype, oname, otype, bm, bn, bk, wm, wn) \\\n    instantiate_gemm(nn, false, false, iname, itype, oname, otype, bm, bn, bk, wm, wn) \\\n    instantiate_gemm(nt, false, true , iname, itype, oname, otype, bm, bn, bk, wm, wn) \\\n    instantiate_gemm(tn, true , false, iname, itype, oname, otype, bm, bn, bk, wm, wn) \\\n    instantiate_gemm(tt, true , true , iname, itype, oname, otype, bm, bn, bk, wm, wn)\n\n// ============================================================\n// Tile Configuration: (32, 32, 16, 2, 2) - Original/fallback configuration\n// ============================================================\ninstantiate_gemm_transpose_helper(f32, float, f32, float, 32, 32, 16, 2, 2)\ninstantiate_gemm_transpose_helper(f16, half, f16, half, 32, 32, 16, 2, 2)\n#if defined(__HAVE_BFLOAT__)\ninstantiate_gemm_transpose_helper(bf16, bfloat, bf16, bfloat, 32, 32, 16, 2, 2)\n#endif\n\n// ============================================================\n// Tile Configuration: (64, 64, 16, 2, 2) - Default for medium devices\n// Reference: MLX steel_gemm_fused.metal\n// ============================================================\ninstantiate_gemm_transpose_helper(f32, float, f32, float, 64, 64, 16, 2, 2)\ninstantiate_gemm_transpose_helper(f16, half, f16, half, 64, 64, 16, 2, 2)\n#if defined(__HAVE_BFLOAT__)\ninstantiate_gemm_transpose_helper(bf16, bfloat, bf16, bfloat, 64, 64, 16, 2, 2)\n#endif\n\n// ============================================================\n// Tile Configuration: (64, 64, 16, 1, 2) - For half/bfloat with small K\n// Reference: MLX steel_gemm_fused.metal\n// ============================================================\ninstantiate_gemm_transpose_helper(f32, float, f32, float, 64, 64, 16, 1, 2)\ninstantiate_gemm_transpose_helper(f16, half, f16, half, 64, 64, 16, 1, 2)\n#if defined(__HAVE_BFLOAT__)\ninstantiate_gemm_transpose_helper(bf16, bfloat, bf16, bfloat, 64, 64, 16, 1, 2)\n#endif\n\n// ============================================================\n// Tile Configuration: (64, 32, 32, 2, 2) - For nt mode with large K\n// Reference: MLX steel_gemm_fused.metal\n// ============================================================\ninstantiate_gemm_transpose_helper(f32, float, f32, float, 64, 32, 32, 2, 2)\ninstantiate_gemm_transpose_helper(f16, half, f16, half, 64, 32, 32, 2, 2)\n#if defined(__HAVE_BFLOAT__)\ninstantiate_gemm_transpose_helper(bf16, bfloat, bf16, bfloat, 64, 32, 32, 2, 2)\n#endif\n\n// ============================================================\n// Tile Configuration: (32, 64, 16, 1, 2) - For nn mode with large K\n// Reference: MLX steel_gemm_fused.metal\n// ============================================================\ninstantiate_gemm_transpose_helper(f32, float, f32, float, 32, 64, 16, 1, 2)\ninstantiate_gemm_transpose_helper(f16, half, f16, half, 32, 64, 16, 1, 2)\n#if defined(__HAVE_BFLOAT__)\ninstantiate_gemm_transpose_helper(bf16, bfloat, bf16, bfloat, 32, 64, 16, 1, 2)\n#endif\n",
    )
val MLX_GEMM: String = MLX_GEMM_PARTS.joinToString("")

private val MLX_SORT_PARTS: List<String> =
    listOf(
        "// The implementation below comes from MLX.\n// https://github.com/ml-explore/mlx/blob/0cea88bcc5e98e81a24d92eed8870a6976999f05/mlx/backend/metal/kernels/sort.h\n// Copyright \u00a9 2023-2024 Apple Inc.\n\n#define MLX_MTL_CONST static constant constexpr const\n#define MLX_MTL_LOOP_UNROLL _Pragma(\"clang loop unroll(full)\")\n\n#include <metal_stdlib>\nusing namespace metal;\ntypedef bfloat bfloat16_t;\n\n// From utils.h\n///////////////////////////////////////////////////////////////////////////////\n// Type limits utils\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <typename U>\nstruct Limits {\n  static const constant U max = metal::numeric_limits<U>::max();\n  static const constant U min = metal::numeric_limits<U>::min();\n  static const constant U finite_max = metal::numeric_limits<U>::max();\n  static const constant U finite_min = metal::numeric_limits<U>::min();\n};\n\n#define instantiate_default_limit(type)                                      \\\n  template <>                                                                \\\n  struct Limits<type> {                                                      \\\n    static constexpr constant type max = metal::numeric_limits<type>::max(); \\\n    static constexpr constant type min = metal::numeric_limits<type>::min(); \\\n    static constexpr constant type finite_max =                              \\\n        metal::numeric_limits<type>::max();                                  \\\n    static constexpr constant type finite_min =                              \\\n        metal::numeric_limits<type>::min();                                  \\\n  };\n\ninstantiate_default_limit(uint8_t);\ninstantiate_default_limit(uint16_t);\ninstantiate_default_limit(uint32_t);\ninstantiate_default_limit(uint64_t);\ninstantiate_default_limit(int8_t);\ninstantiate_default_limit(int16_t);\ninstantiate_default_limit(int32_t);\ninstantiate_default_limit(int64_t);\n\n#define instantiate_float_limit(type)             \\\n  template <>                                     \\\n  struct Limits<type> {                           \\\n    static constexpr constant type max =          \\\n        metal::numeric_limits<type>::infinity();  \\\n    static constexpr constant type min =          \\\n        -metal::numeric_limits<type>::infinity(); \\\n    static constexpr constant type finite_max =   \\\n        metal::numeric_limits<type>::max();       \\\n    static constexpr constant type finite_min =   \\\n        -metal::numeric_limits<type>::max();      \\\n  };\n\ninstantiate_float_limit(half);\ninstantiate_float_limit(float);\ninstantiate_float_limit(bfloat16_t);\n\ntemplate <>\nstruct Limits<bool> {\n  static constexpr constant bool max = true;\n  static constexpr constant bool min = false;\n};\n\n///////////////////////////////////////////////////////////////////////////////\n// Single Array with generic dims\n\ntemplate <typename IdxT = int64_t>\nMETAL_FUNC IdxT elem_to_loc(\n    IdxT elem,\n    constant const int* shape,\n    constant const int64_t* strides,\n    int ndim) {\n  IdxT loc = 0;\n  for (int i = ndim - 1; i >= 0 && elem > 0; --i) {\n    loc += (elem % shape[i]) * IdxT(strides[i]);\n    elem /= shape[i];\n  }\n  return loc;\n}\n\n// Non templated version to handle arbitrary dims\ntemplate <typename IdxT = int64_t>\nMETAL_FUNC IdxT elem_to_loc(\n    uint3 elem,\n    constant const int* shape,\n    constant const int64_t* strides,\n    int ndim) {\n  IdxT loc =\n      elem.x * IdxT(strides[ndim - 1]) + elem.y * IdxT(strides[ndim - 2]);\n  for (int d = ndim - 3; d >= 0; --d) {\n    loc += (elem.z % shape[d]) * IdxT(strides[d]);\n    elem.z /= shape[d];\n  }\n  return loc;\n}\n\n\n// Instantiate a templated kernel.\n// Extra args are used as template parameters:\n// e.g. instantiate_kernel(binary_int, binary, a, b) ->\n// [[host_name(binary_int)]] [kernel] binary<a, b>\n#define instantiate_kernel(name, func, ...) \\\n  template [[host_name(                     \\\n      name)]] [[kernel]] decltype(func<__VA_ARGS__>) func<__VA_ARGS__>;\n\n// Based on GPU merge sort algorithm at\n// https://github.com/NVIDIA/cccl/tree/main/cub/cub\n\n///////////////////////////////////////////////////////////////////////////////\n// Thread-level sort\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <typename T>\nMETAL_FUNC void thread_swap(thread T& a, thread T& b) {\n  T w = a;\n  a = b;\n  b = w;\n}\n\ntemplate <typename T>\nstruct LessThan {\n  static constexpr constant T init = Limits<T>::max;\n\n  METAL_FUNC bool operator()(T a, T b) {\n    return a < b;\n  }\n};\n\ntemplate <\n    typename val_t,\n    typename idx_t,\n    bool ARG_SORT,\n    short N_PER_THREAD,\n    typename CompareOp>\nstruct ThreadSort {\n  static METAL_FUNC void sort(\n      thread val_t (&vals)[N_PER_THREAD],\n      thread idx_t (&idxs)[N_PER_THREAD]) {\n    CompareOp op;\n\n    MLX_MTL_LOOP_UNROLL\n    for (short i = 0; i < N_PER_THREAD; ++i) {\n      MLX_MTL_LOOP_UNROLL\n      for (short j = i & 1; j < N_PER_THREAD - 1; j += 2) {\n        if (op(vals[j + 1], vals[j])) {\n          thread_swap(vals[j + 1], vals[j]);\n          thread_swap(idxs[j + 1], idxs[j]);\n        }\n      }\n    }\n  }\n};\n\n///////////////////////////////////////////////////////////////////////////////\n// Threadgroup-level sort\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename val_t,\n    typename idx_t,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD,\n    typename CompareOp>\nstruct BlockMergeSort {\n  using thread_sort_t =\n      ThreadSort<val_t, idx_t, ARG_SORT, N_PER_THREAD, CompareOp>;\n  static METAL_FUNC int merge_partition(\n      const threadgroup val_t* As,\n      const threadgroup val_t* Bs,\n      short A_sz,\n      short B_sz,\n      short sort_md) {\n    CompareOp op;\n\n    short A_st = max(0, sort_md - B_sz);\n    short A_ed = min(sort_md, A_sz);\n\n    while (A_st < A_ed) {\n      short md = A_st + (A_ed - A_st) / 2;\n      auto a = As[md];\n      auto b = Bs[sort_md - 1 - md];\n\n      if (op(b, a)) {\n        A_ed = md;\n      } else {\n        A_st = md + 1;\n      }\n    }\n\n    return A_ed;\n  }\n\n  static METAL_FUNC void merge_step(\n      const threadgroup val_t* As,\n      const threadgroup val_t* Bs,\n      const threadgroup idx_t* As_idx,\n      const threadgroup idx_t* Bs_idx,\n      short A_sz,\n      short B_sz,\n      thread val_t (&vals)[N_PER_THREAD],\n      thread idx_t (&idxs)[N_PER_THREAD]) {\n    CompareOp op;\n    short a_idx = 0;\n    short b_idx = 0;\n\n    for (int i = 0; i < N_PER_THREAD; ++i) {\n      auto a = As[a_idx];\n      auto b = Bs[b_idx];\n      bool pred = (b_idx < B_sz) && (a_idx >= A_sz || op(b, a));\n\n      vals[i] = pred ? b : a;\n      idxs[i] = pred ? Bs_idx[b_idx] : As_idx[a_idx];\n\n      b_idx += short(pred);\n      a_idx += short(!pred);\n    }\n  }\n\n  static METAL_FUNC void sort(\n      threadgroup val_t* tgp_vals [[threadgroup(0)]],\n      threadgroup idx_t* tgp_idxs [[threadgroup(1)]],\n      int size_sorted_axis,\n      uint3 lid [[thread_position_in_threadgroup]]) {\n    // Get thread location\n    int idx = lid.x * N_PER_THREAD;\n\n    // Load from shared memory\n    thread val_t thread_vals[N_PER_THREAD];\n    thread idx_t thread_idxs[N_PER_THREAD];\n    for (int i = 0; i < N_PER_THREAD; ++i) {\n      thread_vals[i] = tgp_vals[idx + i];\n      if (ARG_SORT) {\n        thread_idxs[i] = tgp_idxs[idx + i];\n      }\n    }\n\n    // Per thread sort\n    if (idx < size_sorted_axis) {\n      thread_sort_t::sort(thread_vals, thread_idxs);\n    }\n\n    // Do merges using threadgroup memory\n    for (int merge_threads = 2; merge_threads <= BLOCK_THREADS;\n         merge_threads *= 2) {\n      // Update threadgroup memory\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n      for (int i = 0; i < N_PER_THREAD; ++i) {\n        tgp_vals[idx + i] = thread_vals[i];\n        if (ARG_SORT) {\n          tgp_idxs[idx + i] = thread_idxs[i];\n        }\n      }\n      threadgroup_barrier(mem_flags::mem_threadgroup);\n\n      // Find location in merge step\n      int merge_group = lid.x / merge_threads;\n      int merge_lane = lid.x % merge_threads;\n\n      int sort_sz = N_PER_THREAD * merge_threads;\n      int sort_st = N_PER_THREAD * merge_threads * merge_group;\n\n      // As = tgp_vals[A_st:A_ed] is sorted\n      // Bs = tgp_vals[B_st:B_ed] is sorted\n      int A_st = sort_st;\n      int A_ed = sort_st + sort_sz / 2;\n      int B_st = sort_st + sort_sz / 2;\n      int B_ed = sort_st + sort_sz;\n\n      const threadgroup val_t* As = tgp_vals + A_st;\n      const threadgroup val_t* Bs = tgp_vals + B_st;\n      int A_sz = A_ed - A_st;\n      int B_sz = B_ed - B_st;\n\n      // Find a partition of merge elements\n      //  Ci = merge(As[partition:], Bs[sort_md - partition:])\n      //       of size N_PER_THREAD for each merge lane i\n      //  C = [Ci] is sorted\n      int sort_md = N_PER_THREAD * merge_lane;\n      int partition = merge_partition(As, Bs, A_sz, B_sz, sort_md);\n\n      As += partition;\n      Bs += sort_md - partition;\n\n      A_sz -= partition;\n      B_sz -= sort_md - partition;\n\n      const threadgroup idx_t* As_idx =\n          ARG_SORT ? tgp_idxs + A_st + partition : nullptr;\n      const threadgroup idx_t* Bs_idx =\n          ARG_SORT ? tgp_idxs + B_st + sort_md - partition : nullptr;\n\n      // Merge starting at the partition and store results in thread registers\n      merge_step(As, Bs, As_idx, Bs_idx, A_sz, B_sz, thread_vals, thread_idxs);\n    }\n\n    // Write out to shared memory\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    for (int i = 0; i < N_PER_THREAD; ++i) {\n      tgp_vals[idx + i] = thread_vals[i];\n      if (ARG_SORT) {\n        tgp_idxs[idx + i] = thread_idxs[i];\n      }\n    }\n  }\n};\n\n///////////////////////////////////////////////////////////////////////////////\n// Kernel sort\n///////////////////////////////////////////////////////////////////////////////\n\ntemplate <\n    typename T,\n    typename U,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD,\n    typename CompareOp = LessThan<T>>\nstruct KernelMergeSort {\n  using val_t = T;\n  using idx_t = uint;\n  using block_merge_sort_t = BlockMergeSort<\n      val_t,\n      idx_t,\n      ARG_SORT,\n      BLOCK_THREADS,\n      N_PER_THREAD,\n      CompareOp>;\n\n  MLX_MTL_CONST short N_PER_BLOCK = BLOCK_THREADS * N_PER_THREAD;\n\n  static METAL_FUNC void block_sort(\n      const device T* inp,\n      device U* out,\n      const constant int& size_sorted_axis,\n      const constant int& in_stride_sorted_axis,\n      const constant int& out_stride_sorted_axis,\n      const constant int& in_stride_segment_axis,\n      const constant int& out_stride_segment_axis,\n      threadgroup val_t* tgp_vals,\n      threadgroup idx_t* tgp_idxs,\n      uint3 tid [[threadgroup_position_in_grid]],\n      uint3 lid [[thread_position_in_threadgroup]]) {\n    // tid.y tells us the segment index\n    inp += tid.y * in_stride_segment_axis;\n    out += tid.y * out_stride_segment_axis;\n\n    // Copy into threadgroup memory\n    for (short i = lid.x; i < N_PER_BLOCK; i += BLOCK_THREADS) {\n      tgp_vals[i] = i < size_sorted_axis ? inp[i * in_stride_sorted_axis]\n                                         : val_t(CompareOp::init);\n      if (ARG_SORT) {\n        tgp_idxs[i] = i;\n      }\n    }\n\n    // Sort elements within the block\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    block_merge_sort_t::sort(tgp_vals, tgp_idxs, size_sorted_axis, lid);\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    // Write output\n    for (int i = lid.x; i < size_sorted_axis; i += BLOCK_THREADS) {\n      if (ARG_SORT) {\n        out[i * out_stride_sorted_axis] = tgp_idxs[i];\n      } else {\n        out[i * out_stride_sorted_axis] = tgp_vals[i];\n      }\n    }\n  }\n};\n\ntemplate <\n    typename T,\n    typename U,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD>\n[[kernel, max_total_threads_per_threadgroup(BLOCK_THREADS)]] void block_sort(\n    const device T* inp [[buffer(0)]],\n    device U* out [[buffer(1)]],\n    const constant int& size_sorted_axis [[buffer(2)]],\n    const constant int& in_stride_sorted_axis [[buffer(3)]],\n    const constant int& out_stride_sorted_axis [[buffer(4)]],\n    const constant int& in_stride_segment_axis [[buffer(5)]],\n    const constant int& out_stride_segment_axis [[buffer(6)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]]) {\n  using sort_kernel =\n      KernelMergeSort<T, U, ARG_SORT, BLOCK_THREADS, N_PER_THREAD>;\n  using val_t = typename sort_kernel::val_t;\n  using idx_t = typename sort_kernel::idx_t;\n\n  if (ARG_SORT) {\n    threadgroup val_t tgp_vals[sort_kernel::N_PER_BLOCK];\n    threadgroup idx_t tgp_idxs[sort_kernel::N_PER_BLOCK];\n    sort_kernel::block_sort(\n        inp,\n        out,\n        size_sorted_axis,\n        in_stride_sorted_axis,\n        out_stride_sorted_axis,\n        in_stride_segment_axis,\n        out_stride_segment_axis,\n        tgp_vals,\n        tgp_idxs,\n        tid,\n        lid);\n  } else {\n    threadgroup val_t tgp_vals[sort_kernel::N_PER_BLOCK];\n    sort_kernel::block_sort(\n        inp,\n        out,\n        size_sorted_axis,\n        in_stride_sorted_axis,\n        out_stride_sorted_axis,\n        in_stride_segment_axis,\n        out_stride_segment_axis,\n        tgp_vals,\n        nullptr,\n        tid,\n        lid);\n  }\n}\n\nconstant constexpr const int zero_helper = 0;\n\ntemplate <\n    typename T,\n    typename U,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD>\n[[kernel, max_total_threads_per_threadgroup(BLOCK_THREADS)]] void block_sort_nc(\n    const device T* inp [[buffer(0)]],\n    device U* out [[buffer(1)]],\n    const constant int& size_sorted_axis [[buffer(2)]],\n    const constant int& in_stride_sorted_axis [[buffer(3)]],\n    const constant int& out_stride_sorted_axis [[buffer(4)]],\n    const constant int& nc_dim [[buffer(5)]],\n    const constant int* nc_shape [[buffer(6)]],\n    const constant int64_t* in_nc_strides [[buffer(7)]],\n    const constant int64_t* out_nc_strides [[buffer(8)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]]) {\n  using sort_kernel =\n      KernelMergeSort<T, U, ARG_SORT, BLOCK_THREADS, N_PER_THREAD>;\n  using val_t = typename sort_kernel::val_t;\n  using idx_t = typename sort_kernel::idx_t;\n\n  auto in_block_idx = elem_to_loc(tid.y, nc_shape, in_nc_strides, nc_dim);\n  auto out_block_idx = elem_to_loc(tid.y, nc_shape, out_nc_strides, nc_dim);\n  inp += in_block_idx;\n  out += out_block_idx;\n\n  if (ARG_SORT) {\n    threadgroup val_t tgp_vals[sort_kernel::N_PER_BLOCK];\n    threadgroup idx_t tgp_idxs[sort_kernel::N_PER_BLOCK];\n    sort_kernel::block_sort(\n        inp,\n        out,\n        size_sorted_axis,\n        in_stride_sorted_axis,\n        out_stride_sorted_axis,\n        zero_helper,\n        zero_helper,\n        tgp_vals,\n        tgp_idxs,\n        tid,\n        lid);\n  } else {\n    threadgroup val_t tgp_vals[sort_kernel::N_PER_BLOCK];\n    sort_kernel::block_sort(\n        inp,\n        out,\n        size_sorted_axis,\n        in_stride_sorted_axis,\n        out_stride_sorted_axis,\n        zero_helper,\n        zero_helper,\n        tgp_vals,\n        nullptr,\n        tid,\n        lid);\n  }\n}\n\ntemplate <\n    typename val_t,\n    typename idx_t,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD,\n    typename CompareOp = LessThan<val_t>>\nstruct KernelMultiBlockMergeSort {\n  using block_merge_sort_t = BlockMergeSort<\n      val_t,\n      idx_t,\n      ARG_SORT,\n      BLOCK_THREADS,\n      N_PER_THREAD,\n      CompareOp>;\n\n  MLX_MTL_CONST short N_PER_BLOCK = BLOCK_THREADS * N_PER_THREAD;\n\n  static METAL_FUNC void block_sort(\n      const device val_t* inp,\n      device val_t* out_vals,\n      device idx_t* out_idxs,\n      const constant int& size_sorted_axis,\n      const constant int& stride_sorted_axis,\n      threadgroup val_t* tgp_vals,\n      threadgroup idx_t* tgp_idxs,\n      uint3 tid [[threadgroup_position_in_grid]],\n      uint3 lid [[thread_position_in_threadgroup]]) {\n    // tid.y tells us the segment index\n    int base_idx = tid.x * N_PER_BLOCK;\n\n    // Copy into threadgroup memory\n    for (short i = lid.x; i < N_PER_BLOCK; i += BLOCK_THREADS) {\n      int idx = base_idx + i;\n      tgp_vals[i] = idx < size_sorted_axis ? inp[idx * stride_sorted_axis]\n                                           : val_t(CompareOp::init);\n      tgp_idxs[i] = idx;\n    }\n\n    // Sort elements within the block\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    block_merge_sort_t::sort(tgp_vals, tgp_idxs, size_sorted_axis, lid);\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    // Write output\n    for (int i = lid.x; i < N_PER_BLOCK; i += BLOCK_THREADS) {\n      int idx = base_idx + i;\n      if (idx < size_sorted_axis) {\n        out_vals[idx] = tgp_vals[i];\n        out_idxs[idx] = tgp_idxs[i];\n      }\n    }\n  }\n\n  static METAL_FUNC int merge_partition(\n      const device val_t* As,\n      const device val_t* Bs,\n      int A_sz,\n      int B_sz,\n      int sort_md) {\n    CompareOp op;\n\n    int A_st = max(0, sort_md - B_sz);\n    int A_ed = min(sort_md, A_sz);\n\n    while (A_st < A_ed) {\n      int md = A_st + (A_ed - A_st) / 2;\n      auto a = As[md];\n      auto b = Bs[sort_md - 1 - md];\n\n      if (op(b, a)) {\n        A_ed = md;\n      } else {\n        A_st = md + 1;\n      }\n    }\n\n    return A_ed;\n  }\n};\n\ntemplate <\n    typename val_t,\n    typename idx_t,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD>\n[[kernel, max_total_threads_per_threadgroup(BLOCK_THREADS)]] void mb_block_sort(\n    const device val_t* inp [[buffer(0)]],\n    device val_t* out_vals [[buffer(1)]],\n    device idx_t* out_idxs [[buffer(2)]],\n    const constant int& size_sorted_axis [[buffer(3)]],\n    const constant int& stride_sorted_axis [[buffer(4)]],\n    const constant int& nc_dim [[buffer(5)]],\n    const constant int* nc_shape [[buffer(6)]],\n    const constant int64_t* nc_strides [[buffer(7)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]]) {\n  using sort_kernel = KernelMultiBlockMergeSort<\n      val_t,\n      idx_t,\n      ARG_SORT,\n      BLOCK_THREADS,\n      N_PER_THREAD>;\n\n  auto block_idx = elem_to_loc(tid.y, nc_shape, nc_strides, nc_dim);\n  inp += block_idx;\n  out_vals += tid.y * size_sorted_axis;\n  out_idxs += tid.y * size_sorted_axis;\n\n  threadgroup val_t tgp_vals[sort_kernel::N_PER_BLOCK];\n  threadgroup idx_t tgp_idxs[sort_kernel::N_PER_BLOCK];\n\n  sort_kernel::block_sort(\n      inp,\n      out_vals,\n      out_idxs,\n      size_sorted_axis,\n      stride_sorted_axis,\n      tgp_vals,\n      tgp_idxs,\n      tid,\n      lid);\n}\n\ntemplate <\n    typename val_t,\n    typename idx_t,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD>\n[[kernel]] void mb_block_partition(\n    device idx_t* block_partitions [[buffer(0)]],\n    const device val_t* dev_vals [[buffer(1)]],\n    const device idx_t* dev_idxs [[buffer(2)]],\n    const constant int& size_sorted_axis [[buffer(3)]],\n    const constant int& merge_tiles [[buffer(4)]],\n    const constant int& n_blocks [[buffer(5)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]],\n    uint3 tgp_dims [[threads_per_threadgroup]]) {\n  using sort_kernel = KernelMultiBlockMergeSort<\n      val_t,\n      idx_t,\n      ARG_SORT,\n      BLOCK_THREADS,\n      N_PER_THREAD>;\n\n  block_partitions += tid.y * tgp_dims.x;\n  dev_vals += tid.y * size_sorted_axis;\n  dev_idxs += tid.y * size_sorted_axis;\n\n  for (int i = lid.x; i <= n_blocks; i += tgp_dims.x) {\n    // Find location in merge step\n    int merge_group = i / merge_tiles;\n    int merge_lane = i % merge_tiles;\n\n    int sort_sz = sort_kernel::N_PER_BLOCK * merge_tiles;\n    int sort_st = sort_kernel::N_PER_BLOCK * merge_tiles * merge_group;\n\n    int A_st = min(size_sorted_axis, sort_st);\n    int A_ed = min(size_sorted_axis, sort_st + sort_sz / 2);\n    int B_st = A_ed;\n    int B_ed = min(size_sorted_axis, B_st + sort_sz / 2);\n\n    int partition_at = min(B_ed - A_st, sort_kernel::N_PER_BLOCK * merge_lane);\n    int partition = sort_kernel::merge_par",
        "tition(\n        dev_vals + A_st,\n        dev_vals + B_st,\n        A_ed - A_st,\n        B_ed - B_st,\n        partition_at);\n\n    block_partitions[i] = A_st + partition;\n  }\n}\n\ntemplate <\n    typename val_t,\n    typename idx_t,\n    bool ARG_SORT,\n    short BLOCK_THREADS,\n    short N_PER_THREAD,\n    typename CompareOp = LessThan<val_t>>\n[[kernel, max_total_threads_per_threadgroup(BLOCK_THREADS)]] void\nmb_block_merge(\n    const device idx_t* block_partitions [[buffer(0)]],\n    const device val_t* dev_vals_in [[buffer(1)]],\n    const device idx_t* dev_idxs_in [[buffer(2)]],\n    device val_t* dev_vals_out [[buffer(3)]],\n    device idx_t* dev_idxs_out [[buffer(4)]],\n    const constant int& size_sorted_axis [[buffer(5)]],\n    const constant int& merge_tiles [[buffer(6)]],\n    const constant int& num_tiles [[buffer(7)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint3 lid [[thread_position_in_threadgroup]]) {\n  using sort_kernel = KernelMultiBlockMergeSort<\n      val_t,\n      idx_t,\n      ARG_SORT,\n      BLOCK_THREADS,\n      N_PER_THREAD,\n      CompareOp>;\n\n  using block_sort_t = typename sort_kernel::block_merge_sort_t;\n\n  block_partitions += tid.y * (num_tiles + 1);\n  dev_vals_in += tid.y * size_sorted_axis;\n  dev_idxs_in += tid.y * size_sorted_axis;\n  dev_vals_out += tid.y * size_sorted_axis;\n  dev_idxs_out += tid.y * size_sorted_axis;\n\n  int block_idx = tid.x;\n  int merge_group = block_idx / merge_tiles;\n  int sort_st = sort_kernel::N_PER_BLOCK * merge_tiles * merge_group;\n  int sort_sz = sort_kernel::N_PER_BLOCK * merge_tiles;\n  int sort_md = sort_kernel::N_PER_BLOCK * block_idx - sort_st;\n\n  int A_st = block_partitions[block_idx + 0];\n  int A_ed = block_partitions[block_idx + 1];\n  int B_st = min(size_sorted_axis, 2 * sort_st + sort_sz / 2 + sort_md - A_st);\n  int B_ed = min(\n      size_sorted_axis,\n      2 * sort_st + sort_sz / 2 + sort_md + sort_kernel::N_PER_BLOCK - A_ed);\n\n  if ((block_idx % merge_tiles) == merge_tiles - 1) {\n    A_ed = min(size_sorted_axis, sort_st + sort_sz / 2);\n    B_ed = min(size_sorted_axis, sort_st + sort_sz);\n  }\n\n  int A_sz = A_ed - A_st;\n  int B_sz = B_ed - B_st;\n\n  // Load from global memory\n  thread val_t thread_vals[N_PER_THREAD];\n  thread idx_t thread_idxs[N_PER_THREAD];\n  for (int i = 0; i < N_PER_THREAD; i++) {\n    int idx = BLOCK_THREADS * i + lid.x;\n    if (idx < (A_sz + B_sz)) {\n      thread_vals[i] = (idx < A_sz) ? dev_vals_in[A_st + idx]\n                                    : dev_vals_in[B_st + idx - A_sz];\n      thread_idxs[i] = (idx < A_sz) ? dev_idxs_in[A_st + idx]\n                                    : dev_idxs_in[B_st + idx - A_sz];\n    } else {\n      thread_vals[i] = CompareOp::init;\n      thread_idxs[i] = 0;\n    }\n  }\n\n  // Write to shared memory\n  threadgroup val_t tgp_vals[sort_kernel::N_PER_BLOCK];\n  threadgroup idx_t tgp_idxs[sort_kernel::N_PER_BLOCK];\n  threadgroup_barrier(mem_flags::mem_threadgroup);\n  for (int i = 0; i < N_PER_THREAD; i++) {\n    int idx = BLOCK_THREADS * i + lid.x;\n    tgp_vals[idx] = thread_vals[i];\n    tgp_idxs[idx] = thread_idxs[i];\n  }\n  threadgroup_barrier(mem_flags::mem_threadgroup);\n\n  // Merge\n  int sort_md_local = min(A_sz + B_sz, N_PER_THREAD * int(lid.x));\n\n  int A_st_local = block_sort_t::merge_partition(\n      tgp_vals, tgp_vals + A_sz, A_sz, B_sz, sort_md_local);\n  int A_ed_local = A_sz;\n\n  int B_st_local = sort_md_local - A_st_local;\n  int B_ed_local = B_sz;\n\n  int A_sz_local = A_ed_local - A_st_local;\n  int B_sz_local = B_ed_local - B_st_local;\n\n  // Do merge\n  block_sort_t::merge_step(\n      tgp_vals + A_st_local,\n      tgp_vals + A_ed_local + B_st_local,\n      tgp_idxs + A_st_local,\n      tgp_idxs + A_ed_local + B_st_local,\n      A_sz_local,\n      B_sz_local,\n      thread_vals,\n      thread_idxs);\n\n  threadgroup_barrier(mem_flags::mem_threadgroup);\n  for (int i = 0; i < N_PER_THREAD; ++i) {\n    int idx = lid.x * N_PER_THREAD;\n    tgp_vals[idx + i] = thread_vals[i];\n    tgp_idxs[idx + i] = thread_idxs[i];\n  }\n\n  threadgroup_barrier(mem_flags::mem_threadgroup);\n  // Write output\n  int base_idx = tid.x * sort_kernel::N_PER_BLOCK;\n  for (int i = lid.x; i < sort_kernel::N_PER_BLOCK; i += BLOCK_THREADS) {\n    int idx = base_idx + i;\n    if (idx < size_sorted_axis) {\n      dev_vals_out[idx] = tgp_vals[i];\n      dev_idxs_out[idx] = tgp_idxs[i];\n    }\n  }\n}\n\n#define instantiate_block_sort(                                          \\\n    name, itname, itype, otname, otype, arg_sort, bn, tn)                \\\n  instantiate_kernel(\"c\" #name \"_\" #itname \"_\" #otname \"_bn\" #bn \"_tn\" #tn, \\\n                     block_sort, itype, otype, arg_sort, bn, tn) \\\n  instantiate_kernel(\"nc\" #name \"_\" #itname \"_\" #otname \"_bn\" #bn \"_tn\" #tn, \\\n                     block_sort_nc, itype, otype, arg_sort, bn, tn)\n\n#define instantiate_arg_block_sort_base(itname, itype, bn, tn) \\\n  instantiate_block_sort(                                      \\\n      arg_block_sort, itname, itype, uint32, uint32_t, true, bn, tn)\n\n#define instantiate_block_sort_base(itname, itype, bn, tn) \\\n  instantiate_block_sort(                                  \\\n      _block_sort, itname, itype, itname, itype, false, bn, tn)\n\n#define instantiate_block_sort_tn(itname, itype, bn) \\\n  instantiate_block_sort_base(itname, itype, bn, 8)  \\\n  instantiate_arg_block_sort_base(itname, itype, bn, 8)\n\n#define instantiate_block_sort_bn(itname, itype) \\\n  instantiate_block_sort_tn(itname, itype, 128)  \\\n  instantiate_block_sort_tn(itname, itype, 256)  \\\n  instantiate_block_sort_tn(itname, itype, 512)\n\ninstantiate_block_sort_bn(uint8, uint8_t)\ninstantiate_block_sort_bn(uint32, uint32_t)\ninstantiate_block_sort_bn(float16, half)\ninstantiate_block_sort_bn(float32, float)\ninstantiate_block_sort_bn(bfloat16, bfloat16_t)\n\n#define instantiate_block_sort_long(itname, itype) \\\n  instantiate_block_sort_tn(itname, itype, 128)    \\\n  instantiate_block_sort_tn(itname, itype, 256)\n\ninstantiate_block_sort_long(int64, int64_t)\n\n#define instantiate_multi_block_sort(                                      \\\n    vtname, vtype, itname, itype, arg_sort, bn, tn)                        \\\n  instantiate_kernel(\"sort_mbsort_\" #vtname \"_\" #itname \"_bn\" #bn \"_tn\" #tn, \\\n                     mb_block_sort, vtype, itype, arg_sort, bn, tn) \\\n  instantiate_kernel(\"partition_mbsort_\" #vtname \"_\" #itname \"_bn\" #bn \"_tn\" #tn, \\\n                     mb_block_partition, vtype, itype, arg_sort, bn, tn) \\\n  instantiate_kernel(\"merge_mbsort_\" #vtname \"_\" #itname \"_bn\" #bn \"_tn\" #tn, \\\n                     mb_block_merge, vtype, itype, arg_sort, bn, tn)\n\n#define instantiate_multi_block_sort_base(vtname, vtype) \\\n  instantiate_multi_block_sort(vtname, vtype, uint32, uint32_t, true, 512, 8)\n\ninstantiate_multi_block_sort_base(uint8, uint8_t)\ninstantiate_multi_block_sort_base(uint32, uint32_t)\ninstantiate_multi_block_sort_base(float16, half)\ninstantiate_multi_block_sort_base(float32, float)\ninstantiate_multi_block_sort_base(bfloat16, bfloat16_t)\n\n#define instantiate_multi_block_sort_long(vtname, vtype) \\\n  instantiate_multi_block_sort(vtname, vtype, uint32, uint32_t, true, 256, 8)\n\ninstantiate_multi_block_sort_long(int64, int64_t) // clang-format on\n",
    )
