sition_in_threadgroup]]);\n\ntemplate<ggml_sort_order order>\nkernel void kernel_argsort_f32_i32(\n        device const float   * x,\n        device       int32_t * dst,\n        constant     int64_t & ncols,\n        constant     int64_t & ncols_pad,\n        threadgroup int32_t  * shared_values [[threadgroup(0)]],\n        uint3 tgpig[[threadgroup_position_in_grid]],\n        uint3 tpitg[[thread_position_in_threadgroup]]) {\n    // bitonic sort\n    int col = tpitg[0];\n    int row = tgpig[1];\n\n    if (col >= ncols_pad) return;\n\n    device const float   * x_row   = x + row * nc",
        "ols;\n    threadgroup int32_t  * dst_row = shared_values;\n\n    // initialize indices\n    dst_row[col] = col;\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    for (int k = 2; k <= ncols_pad; k *= 2) {\n        for (int j = k / 2; j > 0; j /= 2) {\n            int ixj = col ^ j;\n            if (ixj > col) {\n                if ((col & k) == 0) {\n                    if (dst_row[col] >= ncols ||\n                        (dst_row[ixj] < ncols && (order == GGML_SORT_ORDER_ASC ?\n                            x_row[dst_row[col]] > x_row[dst_row[ixj]] :\n                            x_row[dst_row[col]] < x_row[dst_row[ixj]]))\n                    ) {\n                        SWAP(dst_row[col], dst_row[ixj]);\n                    }\n                } else {\n                    if (dst_row[ixj] >= ncols ||\n                        (dst_row[col] < ncols && (order == GGML_SORT_ORDER_ASC ?\n                            x_row[dst_row[col]] < x_row[dst_row[ixj]] :\n                            x_row[dst_row[col]] > x_row[dst_row[ixj]]))\n                    ) {\n                        SWAP(dst_row[col], dst_row[ixj]);\n                    }\n                }\n            }\n            threadgroup_barrier(mem_flags::mem_threadgroup);\n        }\n    }\n\n    // copy the result to dst without the padding\n    if (col < ncols) {\n        dst[row * ncols + col] = dst_row[col];\n    }\n}\n\ntemplate [[host_name(\"kernel_argsort_f32_i32_asc\")]]  kernel argsort_t kernel_argsort_f32_i32<GGML_SORT_ORDER_ASC>;\ntemplate [[host_name(\"kernel_argsort_f32_i32_desc\")]] kernel argsort_t kernel_argsort_f32_i32<GGML_SORT_ORDER_DESC>;\n\nkernel void kernel_leaky_relu_f32(\n        device const float * src0,\n        device       float * dst,\n        constant     float & slope,\n        uint tpig[[thread_position_in_grid]]) {\n    dst[tpig] = src0[tpig] > 0.0f ? src0[tpig] : src0[tpig] * slope;\n}\n\ntypedef void (flash_attn_ext_f16_t)(\n        device const  char * q,\n        device const  char * k,\n        device const  char * v,\n        device const  char * mask,\n        device       float * dst,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne11,\n        constant   int64_t & ne12,\n        constant   int64_t & ne13,\n        constant  uint64_t & nb11,\n        constant  uint64_t & nb12,\n        constant  uint64_t & nb13,\n        constant  uint64_t & nb21,\n        constant  uint64_t & nb22,\n        constant  uint64_t & nb23,\n        constant  uint64_t & nb31,\n        constant   int64_t & ne1,\n        constant   int64_t & ne2,\n        constant     float & scale,\n        constant     float & max_bias,\n        constant     float & m0,\n        constant     float & m1,\n        constant  uint32_t & n_head_log2,\n        constant     float & logit_softcap,\n        threadgroup   half * shared,\n        uint3  tgpig[[threadgroup_position_in_grid]],\n        uint3  tpitg[[thread_position_in_threadgroup]],\n        uint3    ntg[[threads_per_threadgroup]],\n        ushort tiisg[[thread_index_in_simdgroup]],\n        ushort sgitg[[simdgroup_index_in_threadgroup]]);\n\n// ref: https://arxiv.org/pdf/2307.08691.pdf\ntemplate<int64_t D, int64_t Q = 8, int64_t C = 32> // head size, queries per threadgroup, cache items per threadgroup\nkernel void kernel_flash_attn_ext_f16(\n        device const  char * q,\n        device const  char * k,\n        device const  char * v,\n        device const  char * mask,\n        device       float * dst,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne11,\n        constant   int64_t & ne12,\n        constant   int64_t & ne13,\n        constant  uint64_t & nb11,\n        constant  uint64_t & nb12,\n        constant  uint64_t & nb13,\n        constant  uint64_t & nb21,\n        constant  uint64_t & nb22,\n        constant  uint64_t & nb23,\n        constant  uint64_t & nb31,\n        constant   int64_t & ne1,\n        constant   int64_t & ne2,\n        constant     float & scale,\n        constant     float & max_bias,\n        constant     float & m0,\n        constant     float & m1,\n        constant  uint32_t & n_head_log2,\n        constant     float & logit_softcap,\n        threadgroup   half * shared [[threadgroup(0)]],\n        uint3  tgpig[[threadgroup_position_in_grid]],\n        uint3  tpitg[[thread_position_in_threadgroup]],\n        uint3    ntg[[threads_per_threadgroup]],\n        ushort tiisg[[thread_index_in_simdgroup]],\n        ushort sgitg[[simdgroup_index_in_threadgroup]]) {\n    const short nsg = ntg.y; // number of simdgroups\n\n    const short iq3 = tgpig[2];\n    const short iq2 = tgpig[1];\n    const short iq1 = tgpig[0]*Q;\n\n    const short D4 = D/4;\n    const short D8 = D/8;\n  //const short Q8 = Q/8;\n    const short NW = N_SIMDWIDTH;\n    const short SH = (C + Q); // shared memory per simdgroup in (half)\n\n    const short T  = D + 2*nsg*SH; // shared memory size per query in (half)\n    const short TF = T/2;        // shared memory size per query in (float)\n    const short T4 = T/4;        // shared memory size per query in (half4)\n\n    threadgroup half  * sq  = (threadgroup half  *) (shared +              0*D); // holds the query data\n    threadgroup half4 * sq4 = (threadgroup half4 *) (shared +              0*D); // same as above but in half4\n    threadgroup float * ss  = (threadgroup float *) (shared + 2*sgitg*SH + 1*D); // scratch buffer for attention and diagonal matrix\n\n    // store the result for all queries in local memory in 8x8 matrices (the O matrix from the paper)\n    simdgroup_half8x8 lo[D8];\n\n    // load heads from Q to shared memory\n    for (short j = sgitg; j < Q; j += nsg) {\n        device const float4 * q4 = (device const float4 *) ((device const char *) q + ((iq1 + j)*nb01 + iq2*nb02 + iq3*nb03));\n\n        for (short i = tiisg; i < D4; i += NW) {\n            if (iq1 + j < ne01) {\n                sq4[j*T4 + i] = (half4) q4[i];\n            } else {\n                sq4[j*T4 + i] = 0.0h;\n            }\n        }\n    }\n\n    // zero out lo\n    for (short i = 0; i < D8; ++i) {\n        lo[i] = make_filled_simdgroup_matrix<half, 8>(0.0h);\n    }\n\n    // zero out shared memory SH\n    for (short j = 0; j < Q; ++j) {\n        for (short i = tiisg; i < SH; i += NW) {\n            ss[j*TF + i] = 0.0f;\n        }\n    }\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    {\n        float S[Q] = { [0 ... Q-1] = 0.0h };\n        float M[Q] = { [0 ... Q-1] = -FLT_MAX/2 };\n\n        // assume K and V are same shape\n        const short ne22 = ne12;\n        const short ne23 = ne13;\n\n        // broadcast\n        const short rk2 = ne02/ne12;\n        const short rk3 = ne03/ne13;\n\n        const short rv2 = ne02/ne22;\n        const short rv3 = ne03/ne23;\n\n        // k indices\n        const short ik2 = iq2/rk2;\n        const short ik3 = iq3/rk3;\n\n        // v indices\n        const short iv2 = iq2/rv2;\n        const short iv3 = iq3/rv3;\n\n        // load the queries from shared memory into local memory\n        simdgroup_half8x8 mq[D8];\n\n        for (short i = 0; i < D8; ++i) {\n            simdgroup_load(mq[i], sq + i*8, T);\n        }\n\n        // pointer to the mask\n        device const half * mp = (device const half *) (mask + iq1*nb31);\n\n        float slope = 1.0f;\n\n        // ALiBi\n        if (max_bias > 0.0f) {\n            const uint32_t h = iq2;\n\n            const float base = h < n_head_log2 ? m0 : m1;\n            const int   exph = h < n_head_log2 ? h + 1 : 2*(h - n_head_log2) + 1;\n\n            slope = pow(base, exph);\n        }\n\n        // loop over the KV cache\n        // each simdgroup handles blocks of Q rows and C columns\n        for (int ic0 = 0; ic0 < ne11; ic0 += C*nsg) {\n            const int ic = ic0 + C*sgitg;\n            if (ic >= ne11) {\n                break;\n            }\n\n            // Q*K^T\n            {\n                for (short cc = 0; cc < C/8; ++cc) {\n                    simdgroup_float8x8 mqk = make_filled_simdgroup_matrix<float, 8>(0.h);\n\n                    device const half * pk = (device const half *) ((device const char *) k + ((ic + 8*cc)*nb11 + ik2*nb12 + ik3*nb13));\n\n                    for (short i = 0; i < D8; ++i) {\n                        simdgroup_half8x8 mk;\n                        simdgroup_load(mk, pk + i*8, nb11/sizeof(half), 0, true); // transpose\n\n                        simdgroup_multiply_accumulate(mqk, mq[i], mk, mqk);\n                    }\n\n                    simdgroup_store(mqk, ss + 8*cc, TF, 0, false);\n                }\n            }\n\n            // used to detect blocks full of -INF\n            float smax = -INFINITY;\n\n            // online softmax\n            {\n                float ms[Q];\n\n                for (short j = 0; j < Q; ++j) {\n                    const float m = M[j];\n\n                    // scale and apply the logitcap / mask\n                    float s = ss[j*TF + tiisg]*scale;\n\n                    if (logit_softcap != 0.0f) {\n                        s = logit_softcap*precise::tanh(s);\n                    }\n\n                    if (mask != q) {\n                        // mqk = mqk + mask*slope\n                        s += slope*mp[ic + j*nb31/sizeof(half) + tiisg];\n                    }\n\n                    smax = simd_max(max(smax, s));\n                    M[j] = simd_max(max(M[j], s));\n\n                                ms[j] = exp(m - M[j]);\n                    const float vs    = exp(s - M[j]);\n\n                    S[j] = S[j]*ms[j] + simd_sum(vs);\n\n                    // the P matrix from the paper (Q rows, C columns)\n                    ss[j*TF + tiisg] = vs;\n                }\n\n                // create a QxQ diagonal matrix for rescaling the output\n                if (tiisg < Q) {\n                    ss[tiisg*TF + C + tiisg] = ms[tiisg];\n                }\n            }\n\n            // skip -INF blocks\n            if (smax == -INFINITY) {\n                continue;\n            }\n\n            // O = diag(ms)*O\n            {\n                simdgroup_float8x8 mm;\n                simdgroup_load(mm, ss + C, TF, 0, false);\n\n                for (short i = 0; i < D8; ++i) {\n                    simdgroup_multiply(lo[i], mm, lo[i]);\n                }\n            }\n\n            // O = O + (Q*K^T)*V\n            {\n                for (short cc = 0; cc < C/8; ++cc) {\n                    device const half * pv = (device const half *) ((device const char *) v + ((ic + 8*cc)*nb21 + iv2*nb22 + iv3*nb23));\n\n                    for (short i = 0; i < D8; ++i) {\n                        simdgroup_half8x8 mk;\n                        simdgroup_load(mk, pv + i*8, nb21/sizeof(half), 0, false);\n\n                        simdgroup_float8x8 mv;\n                        simdgroup_load(mv, ss + 8*cc, TF, 0, false);\n\n                        simdgroup_multiply_accumulate(lo[i], mv, mk, lo[i]);\n                    }\n                }\n            }\n        }\n\n        // these are needed for reducing the results from the simdgroups (reuse the ss buffer)\n        for (short j = 0; j < Q; ++j) {\n            if (tiisg == 0) {\n                ss[j*TF + 0] = S[j];\n                ss[j*TF + 1] = M[j];\n            }\n        }\n    }\n\n    // reduce the warps sequentially\n    for (short sg = 1; sg < nsg; ++sg) {\n        float S = { 0.0h };\n        float M = { -FLT_MAX/2 };\n\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n\n        // each simdgroup stores its output to shared memory, reusing sq\n        if (sgitg == sg) {\n            for (short i = 0; i < D8; ++i) {\n                simdgroup_store(lo[i], sq + i*8, T, 0, false);\n            }\n        }\n\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n\n        // the first simdgroup accumulates the results from the other simdgroups\n        if (sgitg == 0) {\n            for (short j = 0; j < Q; ++j) {\n                const float S0 = ss[j*TF +         0];\n                const float S1 = ss[j*TF + sg*SH + 0];\n\n                const float M0 = ss[j*TF +         1];\n                const float M1 = ss[j*TF + sg*SH + 1];\n\n                M = max(M0, M1);\n\n                const float ms0 = exp(M0 - M);\n                const float ms1 = exp(M1 - M);\n\n                S = S0*ms0 + S1*ms1;\n\n                if (tiisg == 0) {\n                    ss[j*TF + 0] = S;\n                    ss[j*TF + 1] = M;\n\n                    ss[j*TF + C + j        ] = ms0;\n                    ss[j*TF + C + j + sg*SH] = ms1;\n                }\n            }\n\n            // O_0 = diag(ms0)*O_0 + diag(ms1)*O_1\n            {\n                simdgroup_half8x8 t;\n                simdgroup_float8x8 ms0;\n                simdgroup_float8x8 ms1;\n\n                simdgroup_load(ms0, ss + C,         TF, 0, false);\n                simdgroup_load(ms1, ss + C + sg*SH, TF, 0, false);\n\n                for (short i = 0; i < D8; ++i) {\n                    simdgroup_load    (t, sq + i*8, T, 0, false);\n                    simdgroup_multiply(t, ms1, t);\n\n                    simdgroup_multiply_accumulate(lo[i], ms0, lo[i], t);\n                }\n            }\n        }\n    }\n\n    // store result to shared memory (reuse sq)\n    if (sgitg == 0) {\n        for (short i = 0; i < D8; ++i) {\n            simdgroup_store(lo[i], sq + i*8, T, 0, false);\n        }\n    }\n\n    device float4 * dst4 = (device float4 *) dst;\n\n    // final rescale with 1/S and store to global memory\n    if (sgitg == 0) {\n        for (short j = 0; j < Q && iq1 + j < ne01; ++j) {\n            const float S = ss[j*TF + 0];\n\n            for (short i = tiisg; i < D4; i += NW) {\n                dst4[(iq3*ne2*ne1 + iq2 + (iq1 + j)*ne1)*D4 + i] = (float4) sq4[j*T4 + i]/S;\n            }\n        }\n    }\n}\n\ntemplate [[host_name(\"kernel_flash_attn_ext_f16_h64\" )]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_f16<64>;\ntemplate [[host_name(\"kernel_flash_attn_ext_f16_h80\" )]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_f16<80>;\ntemplate [[host_name(\"kernel_flash_attn_ext_f16_h96\" )]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_f16<96>;\ntemplate [[host_name(\"kernel_flash_attn_ext_f16_h112\")]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_f16<112>;\ntemplate [[host_name(\"kernel_flash_attn_ext_f16_h128\")]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_f16<128>;\n//template [[host_name(\"kernel_flash_attn_ext_f16_h256\")]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_f16<256>;\n\ntemplate<int64_t D, int64_t Q = 1, int64_t C = 32> // head size, queries per threadgroup, cache items per threadgroup\nkernel void kernel_flash_attn_ext_vec_f16(\n        device const  char * q,\n        device const  char * k,\n        device const  char * v,\n        device const  char * mask,\n        device       float * dst,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne11,\n        constant   int64_t & ne12,\n        constant   int64_t & ne13,\n        constant  uint64_t & nb11,\n        constant  uint64_t & nb12,\n        constant  uint64_t & nb13,\n        constant  uint64_t & nb21,\n        constant  uint64_t & nb22,\n        constant  uint64_t & nb23,\n        constant  uint64_t & nb31,\n        constant   int64_t & ne1,\n        constant   int64_t & ne2,\n        constant     float & scale,\n        constant     float & max_bias,\n        constant     float & m0,\n        constant     float & m1,\n        constant  uint32_t & n_head_log2,\n        constant     float & logit_softcap,\n        threadgroup   half * shared [[threadgroup(0)]],\n        uint3  tgpig[[threadgroup_position_in_grid]],\n        uint3  tpitg[[thread_position_in_threadgroup]],\n        uint3    ntg[[threads_per_threadgroup]],\n        ushort tiisg[[thread_index_in_simdgroup]],\n        ushort sgitg[[simdgroup_index_in_threadgroup]]) {\n    const short nsg = ntg.y; // number of simdgroups\n\n    const short iq3 = tgpig[2];\n    const short iq2 = tgpig[1];\n    const short iq1 = tgpig[0];\n\n    const short D4 = D/4;\n    const short NW = N_SIMDWIDTH;\n    const short SH = (C + Q); // shared memory per simdgroup in (half)\n\n    const short T  = D + 2*nsg*SH; // shared memory size per query in (half)\n\n    float slope = 1.0f;\n\n    // ALiBi\n    if (max_bias > 0.0f) {\n        const uint32_t h = iq2;\n\n        const float base = h < n_head_log2 ? m0 : m1;\n        const int   exp  = h < n_head_log2 ? h + 1 : 2*(h - n_head_log2) + 1;\n\n        slope = pow(base, exp);\n    }\n\n  //threadgroup half   * sq  = (threadgroup half   *) (shared +              0*D); // holds the query data\n    threadgroup half4  * sq4 = (threadgroup half4  *) (shared +              0*D); // same as above but in half4\n    threadgroup float  * ss  = (threadgroup float  *) (shared + 2*sgitg*SH + 1*D); // scratch buffer for attention and diagonal matrix\n    threadgroup float4 * ss4 = (threadgroup float4 *) (shared + 2*sgitg*SH + 1*D); // same as above but in half4\n    threadgroup half4  * sr4 = (threadgroup half4  *) (shared +   sgitg*D  + 1*T); // scratch buffer for the results\n\n    // store the result for all queries in local memory in 8x8 matrices (the O matrix from the paper)\n    half4 lo[D4/NW];\n\n    // load heads from Q to shared memory\n    device const float4 * q4 = (device const float4 *) ((device const char *) q + (iq1*nb01 + iq2*nb02 + iq3*nb03));\n\n    for (short i = tiisg; i < D4; i += NW) {\n        if (iq1 < ne01) {\n            sq4[i] = (half4) q4[i];\n        } else {\n            sq4[i] = 0.0h;\n        }\n    }\n\n    // zero out lo\n    for (short i = tiisg; i < D4; i += NW) {\n        lo[i/NW] = 0.0h;\n    }\n\n    // zero out shared memory SH\n    for (short i = tiisg; i < SH/4; i += NW) {\n        ss4[i] = 0.0h;\n    }\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    {\n        float S = { 0.0h };\n        float M = { -FLT_MAX/2 };\n\n        // assume K and V are same shape\n        const short ne22 = ne12;\n        const short ne23 = ne13;\n\n        // broadcast\n        const short rk2 = ne02/ne12;\n        const short rk3 = ne03/ne13;\n\n        const short rv2 = ne02/ne22;\n        const short rv3 = ne03/ne23;\n\n        // k indices\n        const short ik2 = iq2 / rk2;\n        const short ik3 = iq3 / rk3;\n\n        // v indices\n        const short iv2 = iq2 / rv2;\n        const short iv3 = iq3 / rv3;\n\n        // load the queries from shared memory into local memory\n        float4 mq[D4];\n\n        for (short ii = 0; ii < D4; ii += NW) {\n            short i = ii + tiisg;\n            mq[i] = (float4) sq4[i];\n        }\n\n        // pointer to the mask\n        device const half4 * mp4 = (device const half4 *) (mask + iq1*nb31);\n\n        // loop over the KV cache\n        // each simdgroup handles blocks of Q rows and C columns\n        for (int ic0 = 0; ic0 < ne11; ic0 += C*nsg) {\n            const int ic = ic0 + C*sgitg;\n            if (ic >= ne11) {\n                break;\n            }\n\n            // Q*K^T\n            {\n#pragma unroll\n                for (short cc = 0; cc < C/4; ++cc) {\n                    float4 mqk = { 0.0h };\n\n                    device const half4 * pk4 = (device const half4 *) ((device const char *) k + ((ic + 4*cc)*nb11 + ik2*nb12 + ik3*nb13));\n\n#pragma unroll\n                    for (short ii = 0; ii < D4; ii += NW) {\n                        const short i = ii + tiisg;\n\n                        float4x4 mk;\n                        mk[0] = (float4) pk4[i + 0*(nb11/8)];\n                        mk[1] = (float4) pk4[i + 1*(nb11/8)];\n                        mk[2] = (float4) pk4[i + 2*(nb11/8)];\n                        mk[3] = (float4) pk4[i + 3*(nb11/8)];\n\n                        mqk += (float4) (mq[i] * mk);\n                    }\n\n                    // reduce the results from the threads in the simdgroup\n                    ",
        "mqk += simd_shuffle_down(mqk, 16);\n                    mqk += simd_shuffle_down(mqk,  8);\n                    mqk += simd_shuffle_down(mqk,  4);\n                    mqk += simd_shuffle_down(mqk,  2);\n                    mqk += simd_shuffle_down(mqk,  1);\n\n                    // mqk = mqk*scale + mask*slope\n                    if (tiisg == 0) {\n                        mqk *= scale;\n\n                        if (logit_softcap != 0.0f) {\n                            mqk = logit_softcap*precise::tanh(mqk);\n                        }\n\n                        mqk += (mask != q) ? ((float4) mp4[ic/4 + cc])*slope : (float4) 0.0f;\n\n                        ss4[cc] = mqk;\n                    }\n                }\n            }\n\n            // online softmax\n            {\n                const short p = tiisg;\n\n                const float m = M;\n                const float s = ss[p];\n\n                M = simd_max(max(M, s));\n\n                const float ms = exp(m - M);\n                const float vs = exp(s - M);\n\n                S = S*ms + simd_sum(vs);\n\n                // the P matrix from the paper (Q rows, C columns)\n                ss[p] = vs;\n\n                // O = diag(ms)*O\n#pragma unroll\n                for (short ii = 0; ii < D4; ii += NW) {\n                    const short i = ii + tiisg;\n                    lo[i/NW] *= ms;\n                }\n            }\n\n            // O = O + (Q*K^T)*V\n            {\n#pragma unroll\n                for (short cc = 0; cc < C/4; ++cc) {\n                    device const half4 * pv4 = (device const half4 *) ((device const char *) v + ((ic + 4*cc)*nb21 + iv2*nb22 + iv3*nb23));\n\n#pragma unroll\n                    for (short ii = 0; ii < D4; ii += NW) {\n                        const short i = ii + tiisg;\n\n                        lo[i/NW] += pv4[i + 0*(nb21/8)] * ss[4*cc + 0];\n                        lo[i/NW] += pv4[i + 1*(nb21/8)] * ss[4*cc + 1];\n                        lo[i/NW] += pv4[i + 2*(nb21/8)] * ss[4*cc + 2];\n                        lo[i/NW] += pv4[i + 3*(nb21/8)] * ss[4*cc + 3];\n                    }\n                }\n            }\n\n        }\n\n        // these are needed for reducing the results from the simdgroups (reuse the ss buffer)\n        if (tiisg == 0) {\n            ss[0] = S;\n            ss[1] = M;\n        }\n    }\n\n    // store results to shared memory\n    for (short ii = 0; ii < D4; ii += NW) {\n        short i = ii + tiisg;\n        sr4[i] = lo[ii/NW];\n    }\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    // parallel reduce\n    for (short r = nsg/2; r > 0; r >>= 1) {\n        if (sgitg < r) {\n            const float S0 = ss[       0];\n            const float S1 = ss[r*SH + 0];\n\n            const float M0 = ss[       1];\n            const float M1 = ss[r*SH + 1];\n\n            const float M = max(M0, M1);\n\n            const float ms0 = exp(M0 - M);\n            const float ms1 = exp(M1 - M);\n\n            const float S = S0*ms0 + S1*ms1;\n\n            if (tiisg == 0) {\n                ss[0] = S;\n                ss[1] = M;\n            }\n\n            // O_0 = diag(ms0)*O_0 + diag(ms1)*O_1\n            for (short ii = 0; ii < D4; ii += NW) {\n                short i = ii + tiisg;\n                sr4[i] = sr4[i]*ms0 + sr4[i + r*D4]*ms1;\n            }\n        }\n\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n    }\n\n    device float4 * dst4 = (device float4 *) dst;\n\n    // final rescale with 1/S and store to global memory\n    if (sgitg == 0) {\n        const float S = ss[0];\n\n        for (short ii = 0; ii < D4; ii += NW) {\n            short i = ii + tiisg;\n            dst4[(iq3*ne2*ne1 + iq2 + (iq1)*ne1)*D4 + i] = (float4) sr4[i]/S;\n        }\n    }\n}\n\ntemplate [[host_name(\"kernel_flash_attn_ext_vec_f16_h128\")]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_vec_f16<128>;\n//template [[host_name(\"kernel_flash_attn_ext_vec_f16_h256\")]] kernel flash_attn_ext_f16_t kernel_flash_attn_ext_vec_f16<256>;\n\ntemplate<typename T0, typename T1>\nkernel void kernel_cpy(\n        device  const void * src0,\n        device        void * dst,\n        constant   int64_t & ne00,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb00,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne0,\n        constant   int64_t & ne1,\n        constant   int64_t & ne2,\n        constant   int64_t & ne3,\n        constant  uint64_t & nb0,\n        constant  uint64_t & nb1,\n        constant  uint64_t & nb2,\n        constant  uint64_t & nb3,\n        uint3 tgpig[[threadgroup_position_in_grid]],\n        uint3 tpitg[[thread_position_in_threadgroup]],\n        uint3   ntg[[threads_per_threadgroup]]) {\n    const int64_t i03 = tgpig[2];\n    const int64_t i02 = tgpig[1];\n    const int64_t i01 = tgpig[0];\n\n    const int64_t n = i03*ne02*ne01*ne00 + i02*ne01*ne00 + i01*ne00;\n\n    const int64_t i3 = n / (ne2*ne1*ne0);\n    const int64_t i2 = (n - i3*ne2*ne1*ne0) / (ne1*ne0);\n    const int64_t i1 = (n - i3*ne2*ne1*ne0 - i2*ne1*ne0) / ne0;\n    const int64_t i0 = (n - i3*ne2*ne1*ne0 - i2*ne1*ne0 - i1*ne0);\n\n    device T1 * dst_data = (device T1 *) ((device char *) dst + i3*nb3 + i2*nb2 + i1*nb1 + i0*nb0);\n\n    for (int64_t i00 = tpitg.x; i00 < ne00; i00 += ntg.x) {\n        device const T0 * src = (device T0 *)((device char *) src0 + i03*nb03 + i02*nb02 + i01*nb01 + i00*nb00);\n        dst_data[i00] = (T1) src[0];\n    }\n}\n\ntypedef decltype(kernel_cpy<float, float>) kernel_cpy_t;\n\ntemplate [[host_name(\"kernel_cpy_f32_f32\")]]  kernel kernel_cpy_t kernel_cpy<float,  float>;\ntemplate [[host_name(\"kernel_cpy_f32_f16\")]]  kernel kernel_cpy_t kernel_cpy<float,  half>;\ntemplate [[host_name(\"kernel_cpy_f16_f16\")]]  kernel kernel_cpy_t kernel_cpy<half,  