ice float *)((device char *) src0 + i03*nb03 + i02*nb02 + i01*nb01 + i00*nb00);\n\n        float min = FLT_MAX;\n        float max = -FLT_MAX;\n\n        for (int j = 0; j < QK4_1; j++) {\n            const float v = src[j];\n            if (min > v) min = v;\n            if (max < v) max = v;\n        }\n\n        const float d = (max - min) / ((1 << 4) - 1);\n        const float id = d ? 1.0f/d : 0.0f;\n\n        dst_data[i00/QK4_1].d = d;\n        dst_data[i00/QK4_1].m = min;\n\n        for (int j = 0; j < QK4_1/2; ++j) {\n            const float x0 = (src[0       + j] - min)*id;\n            const float x1 = (src[QK4_1/2 + j] - min)*id;\n\n            const uint8_t xi0 = MIN(15, (int8_t)(x0 + 0.5f));\n            const uint8_t xi1 = MIN(15, (int8_t)(x1 + 0.5f));\n\n            dst_data[i00/QK4_1].qs[j]  = xi0;\n            dst_data[i00/QK4_1].qs[j] |= xi1 << 4;\n        }\n    }\n}\n\nkernel void kernel_cpy_f32_q5_0(\n        device const float * src0,\n        device        void * dst,\n        constant   int64_t & ne00,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb00,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne0,\n        constant   int64_t & ne1,\n        constant   int64_t & ne2,\n        constant   int64_t & ne3,\n        constant  uint64_t & nb0,\n        constant  uint64_t & nb1,\n        constant  uint64_t & nb2,\n        constant  uint64_t & nb3,\n        uint3 tgpig[[threadgroup_position_in_grid]],\n        uint3 tpitg[[thread_position_in_threadgroup]],\n        uint3   ntg[[threads_per_threadgroup]]) {\n    const int64_t i03 = tgpig[2];\n    const int64_t i02 = tgpig[1];\n    const int64_t i01 = tgpig[0];\n\n    const int64_t n = i03*ne02*ne01*ne00 + i02*ne01*ne00 + i01*ne00;\n\n    const int64_t i3 = n / (ne2*ne1*ne0);\n    const int64_t i2 = (n - i3*ne2*ne1*ne0) / (ne1*ne0);\n    const int64_t i1 = (n - i3*ne2*ne1*ne0 - i2*ne1*ne0) / ne0;\n    const int64_t i0 = (n - i3*ne2*ne1*ne0 - i2*ne1*ne0 - i1*ne0)/QK5_0;\n\n    device block_q5_0 * dst_data = (device block_q5_0 *) ((device char *) dst + i3*nb3 + i2*nb2 + i1*nb1 + i0*nb0);\n\n    for (int64_t i00 = tpitg.x*QK5_0; i00 < ne00; i00 += ntg.x*QK5_0) {\n        device const float * src = (device float *)((device char *) src0 + i03*nb03 + i02*nb02 + i01*nb01 + i00*nb00);\n\n        float amax = 0.0f; // absolute max\n        float max  = 0.0f;\n\n        for (int j = 0; j < QK5_0; j++) {\n            const float v = src[j];\n            if (amax < fabs(v)) {\n                amax = fabs(v);\n                max  = v;\n            }\n        }\n\n        const float d = max / -16;\n        const float id = d ? 1.0f/d : 0.0f;\n\n        dst_data[i00/QK5_0].d = d;\n\n        uint32_t qh = 0;\n        for (int j = 0; j < QK5_0/2; ++j) {\n            const float x0 = src[0       + j]*id;\n            const float x1 = src[QK5_0/2 + j]*id;\n\n            const uint8_t xi0 = MIN(31, (int8_t)(x0 + 16.5f));\n            const uint8_t xi1 = MIN(31, (int8_t)(x1 + 16.5f));\n\n            dst_data[i00/QK5_0].qs[j] = (xi0 & 0xf) | ((xi1 & 0xf) << 4);\n            qh |= ((xi0 & 0x10u) >> 4) << (j + 0);\n            qh |= ((xi1 & 0x10u) >> 4) << (j + QK5_0/2);\n        }\n        thread const uint8_t * qh8 = (thread const uint8_t *)&qh;\n        for (int j = 0; j < 4; ++j) {\n            dst_data[i00/QK5_0].qh[j] = qh8[j];\n        }\n    }\n}\n\nkernel void kernel_cpy_f32_q5_1(\n        device const float * src0,\n        device        void * dst,\n        constant   int64_t & ne00,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb00,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne0,\n        constant   int64