        }\n        thread const uint8_t * qh8 = (thread const uint8_t *)&qh;\n        for (int j = 0; j < 4; ++j) {\n            dst_data[i00/QK5_1].qh[j] = qh8[j];\n        }\n    }\n}\n\nstatic inline int best_index_int8(int n, constant float * val, float x) {\n    if (x <= val[0]) return 0;\n    if (x >= val[n-1]) return n-1;\n    int ml = 0, mu = n-1;\n    while (mu-ml > 1) {\n        int mav = (ml+mu)/2;\n        if (x < val[mav]) mu = mav; else ml = mav;\n    }\n    return x - val[mu-1] < val[mu] - x ? mu-1 : mu;\n}\n\nconstexpr constant static float kvalues_iq4nl_f[16] = {\n    -127.f, -104.f, -83.f, -65.f, -49.f, -35.f, -22.f, -10.f, 1.f, 13.f, 25.f, 38.f, 53.f, 69.f, 89.f, 113.f\n};\n\nkernel void kernel_cpy_f32_iq4_nl(\n        device const float * src0,\n        device        void * dst,\n        constant   int64_t & ne00,\n        constant   int64_t & ne01,\n        constant   int64_t & ne02,\n        constant   int64_t & ne03,\n        constant  uint64_t & nb00,\n        constant  uint64_t & nb01,\n        constant  uint64_t & nb02,\n        constant  uint64_t & nb03,\n        constant   int64_t & ne0,\n        constant   int64_t & ne1,\n        constant   int64_t & ne2,\n        constant   int64_t & ne3,\n        constant  uint64_t & nb0,\n        constant  uint64_t & nb1,\n        constant  uint64_t & nb2,\n        constant  uint64_t & nb3,\n        uint3 tgpig[[threadgroup_position_in_grid]],\n        uint3 tpitg[[thread_position_in_threadgroup]],\n        uint3   ntg[[threads_per_threadgroup]]) {\n    const int64_t i03 = tgpig[2];\n    const int64_t i02 = tgpig[1];\n    const int64_t i01 = tgpig[0];\n\n    const int64_t n = i03*ne02*ne01*ne00 + i02*ne01*ne00 + i01*ne00;\n\n    const int64_t i3 = n / (ne2*ne1*ne0);\n    const int64_t i2 = (n - i3*ne2*ne1*ne0) / (ne1*ne0);\n    const int64_t i1 = (n - i3*ne2*ne1*ne0 - i2*ne1*ne0) / ne0;\n    const int64_t i0 = (n - i3*ne2*ne1*ne0 - i2*ne1*ne0 - i1*ne0)/QK4_NL;\n\n    device block_iq4_nl * dst_data = (device block_iq4_nl *) ((device char *) dst + i3*nb3 + i2*nb2 + i1*nb1 + i0*nb0);\n\n    for (int64_t i00 = tpitg.x*QK4_NL; i00 < ne00; i00 += ntg.x*QK4_NL) {\n        device const float * src = (device float *)((device char *) src0 + i03*nb03 + i02*nb02 + i01*nb01 + i00*nb00);\n\n        float amax = 0.0f; // absolute max\n        float max  = 0.0f;\n\n        for (int j = 0; j < QK4_0; j++) {\n            const float v = src[j];\n            if (amax < fabs(v)) {\n                amax = fabs(v);\n                max  = v;\n            }\n        }\n\n        const float d = max / kvalues_i",
        "q4nl_f[0];\n        const float id = d ? 1.0f/d : 0.0f;\n\n        float sumqx = 0, sumq2 = 0;\n        for (int j = 0; j < QK4_NL/2; ++j) {\n            const float x0 = src[0        + j]*id;\n            const float x1 = src[QK4_NL/2 + j]*id;\n\n            const uint8_t xi0 = best_index_int8(16, kvalues_iq4nl_f, x0);\n            const uint8_t xi1 = best_index_int8(16, kvalues_iq4nl_f, x1);\n\n            dst_data[i00/QK4_NL].qs[j] = xi0 | (xi1 << 4);\n\n            const float v0 = kvalues_iq4nl_f[xi0];\n            const float v1 = kvalues_iq4nl_f[xi1];\n            const float w0 = src[0        + j]*src[0        + j];\n            const float w1 = src[QK4_NL/2 + j]*src[QK4_NL/2 + j];\n            sumqx += w0*v0*src[j] + w1*v1*src[QK4_NL/2 + j];\n            sumq2 += w0*v0*v0 + w1*v1*v1;\n\n        }\n\n        dst_data[i00/QK4_NL].d = sumq2 > 0 ? sumqx/sumq2 : d;\n\n    }\n}\n\nkernel void kernel_concat(\n    device  const char * src0,\n    device  const char * src1,\n    device        char * dst,\n    constant   int64_t & ne00,\n    constant   int64_t & ne01,\n    constant   int64_t & ne02,\n    constant   int64_t & ne03,\n    constant  uint64_t & nb00,\n    constant  uint64_t & nb01,\n    constant  uint64_t & nb02,\n    constant  uint64_t & nb03,\n    constant   int64_t & ne10,\n    constant   int64_t & ne11,\n    constant   int64_t & ne12,\n    constant   int64_t & ne13,\n    constant  uint64_t & nb10,\n    constant  uint64_t & nb11,\n    constant  uint64_t & nb12,\n    constant  uint64_t & nb13,\n    constant   int64_t & ne0,\n    constant   int64_t & ne1,\n    constant   int64_t & ne2,\n    constant   int64_t & ne3,\n    constant  uint64_t & nb0,\n    constant  uint64_t & nb1,\n    constant  uint64_t & nb2,\n    constant  uint64_t & nb3,\n    constant   int32_t & dim,\n    uint3 tgpig[[threadgroup_position_in_grid]],\n    uint3 tpitg[[thread_position_in_threadgroup]],\n    uint3   ntg[[threads_per_threadgroup]]) {\n\n    const int64_t i3 = tgpig.z;\n    const int64_t i2 = tgpig.y;\n    const int64_t i1 = tgpig.x;\n\n    int64_t o[4] = {0, 0, 0, 0};\n    o[dim] = dim == 0 ? ne00 : (dim == 1 ? ne01 : (dim == 2 ? ne02 : ne03));\n\n    device const float * x;\n\n    for (int i0 = tpitg.x; i0 < ne0; i0 += ntg.x) {\n        if (i0 < ne00 && i1 < ne01 && i2 < ne02 && i3 < ne03) {\n            x = (device const float *)(src0 + (i3       )*nb03 + (i2       )*nb02 + (i1       )*nb01 + (i0       )*nb00);\n        } else {\n            x = (device const float *)(src1 + (i3 - o[3])*nb13 + (i2 - o[2])*nb12 + (i1 - o[1])*nb11 + (i0 - o[0])*nb10);\n        }\n\n        device float * y = (device float *)(dst + i3*nb3 + i2*nb2 + i1*nb1 + i0*nb0);\n\n        *y = *x;\n    }\n}\n\nvoid kernel_mul_mv_q2_K_f32_impl(\n        device const  void * src0,\n        device const float * src1,\n        device       float * dst,\n                   int64_t   ne00,\n                   int64_t   ne01,\n                   int64_t   ne02,\n                   int64_t   ne10,\n                   int64_t   ne12,\n                   int64_t   ne0,\n                   int64_t   ne1,\n                   uint      r2,\n                   uint      r3,\n        threadgroup int8_t * shared_values,\n                   uint3     tgpig,\n                   uint      tiisg,\n                   uint      sgitg) {\n\n    const int nb = ne00/QK_K;\n    const int r0 = tgpig.x;\n    const int r1 = tgpig.y;\n    const int im = tgpig.z;\n\n    const int first_row = (r0 * N_SIMDGROUP + sgitg) * N_DST;\n    const int ib_row = first_row * nb;\n\n    const uint i12 = im%ne12;\n    const uint i13 = im/ne12;\n\n    const uint offset0 = (i12/r2)*(nb*ne01) + (i13/r3)*(nb*ne01*ne02);\n\n    device const block_q2_K * x = (device const block_q2_K *) src0 + ib_row + offset0;\n    device const float      * y = (device const float      *) src1 + r1*ne10 + im*ne00*ne1;\n\n    float yl[32];\n    float sumf[N_DST]={0.f}, all_sum;\n\n    const int step = sizeof(block_q2_K) * nb;\n\n    const int ix = tiisg/8;  // 0...3\n    const int it = tiisg%8;  // 0...7\n    const int iq = it/4;     // 0 or 1\n    const int ir = it%4;     // 0...3\n    const int is = (8*ir)/16;// 0 or 1\n\n    device const float * y4 = y + ix * QK_K + 128 * iq + 8 * ir;\n\n    for (int ib = ix; ib < nb; ib += 4) {\n\n        float4 sumy = {0.f, 0.f, 0.f, 0.f};\n        for (int i = 0; i < 8; ++i) {\n            yl[i+ 0] = y4[i+ 0]; sumy[0] += yl[i+ 0];\n            yl[i+ 8] = y4[i+32]; sumy[1] += yl[i+ 8];\n            yl[i+16] = y4[i+64]; sumy[2] += yl[i+16];\n            yl[i+24] = y4[i+96]; sumy[3] += yl[i+24];\n        }\n\n        device const uint8_t  * sc = (device const uint8_t  *)x[ib].scales + 8*iq + is;\n        device const uint16_t * qs = (device const uint16_t *)x[ib].qs + 16 * iq + 4 * ir;\n        device const half     * dh = &x[ib].d;\n\n        for (int row = 0; row < N_DST; row++) {\n\n            float4 acc1 = {0.f, 0.f, 0.f, 0.f};\n            float4 acc2 = {0.f, 0.f, 0.f, 0.f};\n            for (int i = 0; i < 8; i += 2) {\n                acc1[0] += yl[i+ 0] * (qs[i/2] & 0x0003);\n                acc2[0] += yl[i+ 1] * (qs[i/2] & 0x0300);\n                acc1[1] += yl[i+ 8] * (qs[i/2] & 0x000c);\n                acc2[1] += yl[i+ 9] * (qs[i/2] & 0x0c00);\n                acc1[2] += yl[i+16] * (qs[i/2] & 0x0030);\n                acc2[2] += yl[i+17] * (qs[i/2] & 0x3000);\n                acc1[3] += yl[i+24] * (qs[i/2] & 0x00c0);\n                acc2[3] += yl[i+25] * (qs[i/2] & 0xc000);\n            }\n            float dall = dh[0];\n            float dmin = dh[1] * 1.f/16.f;\n            sumf[row] += dall * ((acc1[0] + 1.f/256.f * acc2[0]) * (sc[0] & 0xF) * 1.f/ 1.f +\n                                 (acc1[1] + 1.f/256.f * acc2[1]) * (sc[2] & 0xF) * 1.f/ 4.f +\n                                 (acc1[2] + 1.f/256.f * acc2[2]) * (sc[4] & 0xF) * 1.f/16.f +\n                                 (acc1[3] + 1.f/256.f * acc2[3]) * (sc[6] & 0xF) * 1.f/64.