val RANDOM: String = "#include <metal_stdlib>\n#include <metal_integer>\n#include <metal_atomic>\n\nusing namespace metal;\n\n// Constants\n// 2^32 and 1/2^32. Useful for converting between float and uint.\nstatic constexpr constant ulong UNIF01_NORM32 = 4294967296;\nstatic constexpr constant float UNIF01_INV32 = 2.328306436538696289e-10;\n// 2 * pi\nstatic constexpr constant float TWO_PI = 2.0 * M_PI_F;\nstatic constexpr constant int3 S1 = {13, 19, 12};\nstatic constexpr constant int3 S2 = {2, 25, 4};\nstatic constexpr constant int3 S3 = {3, 11, 17};\n\n// Used to prevent bad seeds.\nstatic constexpr constant uint64_t PHI[16] = {\n    0x9E3779B97F4A7C15,\n    0xF39CC0605CEDC834,\n    0x1082276BF3A27251,\n    0xF86C6A11D0C18E95,\n    0x2767F0B153D27B7F,\n    0x0347045B5BF1827F,\n    0x01886F0928403002,\n    0xC1D64BA40F335E36,\n    0xF06AD7AE9717877E,\n    0x85839D6EFFBD7DC6,\n    0x64D325D1C5371682,\n    0xCADD0CCCFDFFBBE1,\n    0x626E33B8D04B4331,\n    0xBBF73C790D94F79D,\n    0x471C4AB3ED3D82A5,\n    0xFEC507705E4AE6E5,\n};\n\n// Combined Tausworthe and LCG Random Number Generator.\n// https://developer.nvidia.com/gpugems/gpugems3/part-vi-gpu-computing/chapter-37-efficient-random-number-generation-and-application\n// https://indico.cern.ch/event/93877/contributions/2118070/attachments/1104200/1575343/acat3_revised_final.pdf\nstruct HybridTaus {\n\n    float state;\n\n    HybridTaus() thread = default;\n    HybridTaus() threadgroup = default;\n    HybridTaus() device = default;\n    HybridTaus() constant = default;\n\n    // Generate seeds for each thread.\n    METAL_FUNC static uint4 seed_per_thread(const ulong4 seeds) {\n        return uint4(ulong4(seeds) * ulong4(PHI[0], PHI[1], PHI[2], PHI[3]) * ulong4(1099087573UL));\n    }\n\n    // Tausworthe generator.\n    METAL_FUNC static uint taus(const uint z, const int3 s, const uint M) {\n        uint b = (((z << s.x) ^ z) >> s.y);\n        return (((z & M) << s.z) ^ b);\n    }\n\n    // LCG generator.\n    METAL_FUNC static uint lcg(const uint z) {\n        return (1664525 * z + 1013904223UL);\n    }\n\n    // Initialize the RNG state.\n    METAL_FUNC static HybridTaus init(const ulong4 seeds) {\n        uint4 seed = seed_per_thread(seeds);\n\n        // Seed #1\n        uint z1 = taus(seed.x, S1, 4294967294UL);\n        uint z2 = taus(seed.y, S2, 4294967288UL);\n        uint z3 = taus(seed.z, S3, 4294967280UL);\n        uint z4 = lcg(seed.x);\n\n        // Seed #2\n        uint r1 = (z1^z2^z3^z4^seed.y);\n        z1 = taus(r1, S1, 429496729UL);\n        z2 = taus(r1, S2, 4294967288UL);\n        z3 = taus(r1, S3, 429496280UL);\n        z4 = lcg(r1);\n\n        // Seed #3\n        r1 = (z1^z2^z3^z4^seed.z);\n        z1 = taus(r1, S1, 429496729UL);\n        z2 = taus(r1, S2, 4294967288UL);\n        z3 = taus(r1, S3, 429496280UL);\n        z4 = lcg(r1);\n\n        // Seed #4\n        r1 = (z1^z2^z3^z4^seed.w);\n        z1 = taus(r1, S1, 429496729UL);\n        z2 = taus(r1, S2, 4294967288UL);\n        z3 = taus(r1, S3, 429496280UL);\n        z4 = lcg(r1);\n\n        HybridTaus rng;\n        rng.state = (z1^z2^z3^z4) * UNIF01_INV32;\n        return rng;\n    }\n\n    METAL_FUNC float rand() {\n        uint seed = this->state * UNIF01_NORM32;\n        uint z1 = taus(seed, S1, 429496729UL);\n        uint z2 = taus(seed, S2, 4294967288UL);\n        uint z3 = taus(seed, S3, 429496280UL);\n        uint z4 = lcg(seed);\n\n        thread float result = this->state;\n        this->state = (z1^z2^z3^z4) * UNIF01_INV32;\n        return result;\n    }\n};\ntypedef struct\n{\n    atomic_uint seed[2];\n} seed_buffer;\n\n\nMETAL_FUNC ulong atomic_load_seed(device seed_buffer *sb) {\n    uint x = atomic_load_explicit(&sb->seed[0], memory_order_relaxed);\n    uint y = atomic_load_explicit(&sb->seed[1], memory_order_relaxed);\n    return static_cast<ulong>(x) << 32 | y;\n}\n\nMETAL_FUNC void atomic_store_seed(device seed_buffer *sb, ulong desired) {\n    uint x = static_cast<uint>(desired >> 32);\n    uint y = static_cast<uint>(desired & 0xFFFFFFFF);\n    atomic_store_explicit(&sb->seed[0], x, memory_order_relaxed);\n    atomic_store_explicit(&sb->seed[1], y, memory_order_relaxed);\n}\n\ntemplate<typename T> METAL_FUNC void rand_uniform(\n    constant size_t &size,\n    constant float &min,\n    constant float &max,\n    device seed_buffer *sb,\n    device T *out,\n    uint tid [[thread_position_in_grid]]\n) {\n    if (tid >= size) {\n        return;\n    }\n\n    // Evenly sized vectors need an offset when writing the mirror element.\n    uint off = 1 - size % 2;\n    float diff = abs(min - max);\n    ulong s = atomic_load_seed(sb);\n    HybridTaus rng = HybridTaus::init({s, tid, 1, 1});\n    out[tid] = static_cast<T>(rng.rand() * diff + min);\n    if (tid == 0) {\n        atomic_store_seed(sb, rng.rand() * UNIF01_NORM32);\n        // Return early if tid == 0 && off == 0, otherwise we will write to out[size].\n        if (off == 0)\n            return;\n    }\n    // Use symmetry to fill the other half of the array.\n    out[size - off - tid] = static_cast<T>(rng.rand() * diff + min);\n}\n\n// Create Gaussian normal distribution using Box-Muller transform:\n// https://en.wikipedia.org/wiki/Box\u2013Muller_transform\ntemplate<typename T> METAL_FUNC void normal(\n    constant size_t &size,\n    constant float &mean,\n    constant float &stddev,\n    device seed_buffer *sb,\n    device T *out,\n    uint tid [[thread_position_in_grid]]\n) {\n    if (tid >= size) {\n        return;\n    }\n    // Evenly sized vectors need an offset when writing the mirror element.\n    uint off = 1 - size % 2;\n    ulong s = atomic_load_seed(sb);\n    HybridTaus rng = HybridTaus::init({s, tid, 1, 1});\n    float u1 = rng.rand();\n    float u2 = rng.rand();\n\n    float cosval;\n    float sinval = sincos(TWO_PI * u2, cosval);\n    float mag = stddev * sqrt(-2.0 * log(u1));\n    float z0  = mag * cosval + mean;\n    float z1  = mag * sinval + mean;\n\n    out[tid] = static_cast<T>(z0);\n\n    if (tid == 0) {\n        atomic_store_seed(sb, rng.rand() * UNIF01_NORM32);\n        // Return early if tid == 0 && off == 0, otherwise we will write to out[size].\n        if (off == 0)\n            return;\n    }\n    // Use symmetry to fill the other half of the array.\n    out[size - off - tid] = static_cast<T>(z1);\n}\n\n#define UNIFORM_OP(NAME, T)                             \\\nkernel void rand_uniform_##NAME(                        \\\n    constant size_t &size,                              \\\n    constant float &min,                                \\\n    constant float &max,                                \\\n    device seed_buffer *sb,                             \\\n    device T *out,                                      \\\n    uint tid [[thread_position_in_grid]]                \\\n) {                                                     \\\n    rand_uniform<T>(size, min, max, sb, out, tid);      \\\n}                                                       \\\n\n#define NORMAL_OP(NAME, T)                              \\\nkernel void rand_normal_##NAME(                         \\\n    constant size_t &size,                              \\\n    constant float &mean,                               \\\n    constant float &stddev,                             \\\n    device seed_buffer *sb,                             \\\n    device T *out,                                      \\\n    uint tid [[thread_position_in_grid]]                \\\n) {                                                     \\\n    normal<T>(size, mean, stddev, sb, out, tid);        \\\n}                                                       \\\n\n\n#define RANDOM_OPS(NAME, T) \\\nUNIFORM_OP(NAME, T)         \\\nNORMAL_OP(NAME, T)          \\\n\nRANDOM_OPS(f32, float)\nRANDOM_OPS(f16, half)\n\n#if __METAL_VERSION__ >= 310\nRANDOM_OPS(bf16, bfloat)\n#endif\n"

private val REDUCE_PARTS: List<String> =
    listOf(
        "#include <metal_stdlib>\n#include <metal_limits>\nusing namespace metal;\n\ntemplate<uint Y>\nconstexpr uint div_ceil(uint x) {\n    return x / Y + (x % Y > 0);\n}\n\ntemplate<uint X, uint Y>\nconstexpr uint div_ceil() {\n    return X / Y + (X % Y > 0);\n}\n\ntemplate<typename T>\nconstexpr uint work_per_thread() {\n    return div_ceil<8, sizeof(T)>();\n}\n\nMETAL_FUNC uint nonzero(uint n) {\n    return n == 0 ? 1 : n;\n}\n\ntemplate<uint N>\nconstexpr uint nonzero() {\n    return N == 0 ? 1 : N;\n}\n\ntemplate<typename T>\nconstexpr ushort granularity() {\n    return nonzero<vec_elements<T>::value>();\n}\n\nMETAL_FUNC uint next_p2(uint x) {\n    return 1 << (32 - clz(x - 1));\n}\n\nMETAL_FUNC uint prev_p2(uint x) {\n    return 1 << (31 - clz(x));\n}\n\nconstant uint MAX_SHARED_MEM = 32767;\n\ntemplate<typename T>\nMETAL_FUNC uint max_shared_mem(uint n) {\n    return min(n, div_ceil<MAX_SHARED_MEM, sizeof(T)>());\n}\n\n\ntemplate<ushort D, typename IndexT>\nstruct strided_indexer {\n    constant const IndexT *dims;\n    constant const IndexT *strides;\n    strided_indexer<D - 1, IndexT> next {dims, strides};\n\n    METAL_FUNC IndexT operator()(IndexT idx) const {\n        IndexT dim = dims[D - 1];\n        IndexT i = (idx % dim) * strides[D - 1];\n        idx /= dim;\n        return i + next(idx);\n    }\n};\n\ntemplate<typename IndexT>\nstruct strided_indexer<1, IndexT> {\n    constant const IndexT *dims;\n    constant const IndexT *strides;\n\n    METAL_FUNC IndexT operator()(IndexT idx) const {\n        return idx * strides[0];\n    }\n};\n\ntemplate<ushort D, typename IndexT>\nMETAL_FUNC IndexT get_strided_idx_fallback(\n    IndexT idx,\n    constant const IndexT &num_dims,\n    constant const IndexT *dims,\n    constant const IndexT *strides\n) {\n    strided_indexer<D, IndexT> next {dims, strides};\n\n    IndexT strided_i = 0;\n    for (IndexT d = D; d < num_dims; d++) {\n        IndexT dim_idx = num_dims - 1 - d;\n        IndexT dim = dims[dim_idx];\n        strided_i += (idx % dim) * strides[dim_idx];\n        idx /= dim;\n    }\n    return strided_i + next(idx);\n}\n\ntemplate<typename IndexT>\nMETAL_FUNC IndexT get_strided_index_t(\n    IndexT idx,\n    constant const IndexT &num_dims,\n    constant const IndexT *dims,\n    constant const IndexT *strides\n) {\n    switch (num_dims) {\n        case 1: return strided_indexer<1, IndexT>{dims, strides}(idx);\n        case 2: return strided_indexer<2, IndexT>{dims, strides}(idx);\n        case 3: return strided_indexer<3, IndexT>{dims, strides}(idx);\n        case 4: return strided_indexer<4, IndexT>{dims, strides}(idx);\n        //case 5: return strided_indexer<5, IndexT>{dims, strides}(idx);\n        //case 6: return strided_indexer<6, IndexT>{dims, strides}(idx);\n        default: return get_strided_idx_fallback<4, IndexT>(idx, num_dims, dims, strides);\n    }\n}\n\ntemplate<typename IndexT, bool STRIDED>\nstruct indexer_t {\n    typedef IndexT I;\n};\n\ntemplate<typename IndexT>\nstruct indexer_t<IndexT, false> {\n    typedef IndexT I;\n\n    const IndexT last_dim = 0;\n\n    METAL_FUNC IndexT operator()(IndexT i) const {\n        return i;\n    }\n};\n\ntemplate<typename IndexT>\nstruct indexer_t<IndexT, true> {\n    typedef IndexT I;\n\n    constant const IndexT &num_dims;\n    constant const IndexT *dims;\n    constant const IndexT *strides;\n    const IndexT last_dim;\n\n    METAL_FUNC IndexT operator()(IndexT i) const {\n        return get_strided_index_t(i, num_dims, dims, strides);\n    }\n};\n\nstruct Divide {\n    template<typename T>\n    METAL_FUNC T operator()(T a, T b) { return a / b; }\n    METAL_FUNC float  operator()(float  a, float  b) { return fast::divide(a, b); }\n    METAL_FUNC half   operator()(half   a, half   b) { return divide(a, b); }\n    #if defined(__HAVE_BFLOAT__)\n    METAL_FUNC bfloat  operator()(bfloat  a, bfloat  b) { return static_cast<bfloat>(fast::divide(a, b)); }\n    #endif\n};\n\nstruct Exp {\n    template<typename T>\n