 eps,                                            \\\n        shared,                                         \\\n        mu,                                             \\\n        sigma,                                          \\\n        tid,                                            \\\n        dst_id,                                         \\\n        lane_id);                                       \\\n    break;                                              \\\n}\n\n#define impl_layer_norm(NAME, T)                        \\\nkernel void NAME(                                       \\\n    constant uint &src_numel,                           \\\n    constant uint &el_per_block,                        \\\n    device const T *src,                                \\\n    device T *dst,                                      \\\n    device const T *alpha,                              \\\n    device const T *beta,                               \\\n    constant float &eps,                                \\\n    uint tid [[ thread_index_in_threadgroup ]],         \\\n    uint dst_id [[ threadgroup_position_in_grid ]],     \\\n    uint lane_id [[thread_index_in_simdgroup]],         \\\n    uint block_dim [[ threads_per_threadgroup ]]        \\\n) {                                                     \\\n    switch (max_shared_mem<float>(block_dim)) {         \\\n        layer_norm_case(T, 1024);                       \\\n        layer_norm_case(T,  512);                       \\\n        layer_norm_case(T,  256);                       \\\n        layer_norm_case(T,  128);                       \\\n        layer_norm_case(T,   64);                       \\\n        layer_norm_case(T,   32);                       \\\n        layer_norm_case(T,   16);                       \\\n        layer_norm_case(T,    8);                       \\\n        layer_norm_case(T,    4);                       \\\n        layer_norm_case(T,    2);                       \\\n        layer_norm_case(T,    1);                       \\\n    }                                                   \\\n}\n\ntemplate<typename T>\nMETAL_FUNC void ropei(\n    constant size_t &bh,\n    constant size_t &td,\n    constant size_t &stride_b,\n    device const T *src,\n    device const T *cos,\n    device const T *sin,\n    device T *dst,\n    uint tid\n) {\n    if (2 * tid >= bh * td) {\n        return;\n    }\n    size_t rope_idx = tid % (td / 2);\n    if (stride_b > 0) {\n      size_t b_idx = (2 * tid) / stride_b;\n      rope_idx += b_idx * (td / 2);\n    }\n    T c = cos[rope_idx];\n    T s = sin[rope_idx];\n    dst[2 * tid] = src[2 * tid] * c - src[2 * tid + 1] * s;\n    dst[2 * tid + 1] = src[2 * tid] * s + src[2 * tid + 1] * c;\n}\n\ntemplate<typename T>\nMETAL_FUNC void rope(\n    constant size_t &bh,\n    constant size_t &td,\n    constant size_t &d,\n    constant size_t &stride_b,\n    device const T *src,\n    device const T *cos,\n    device const T *sin,\n    device T *dst,\n    uint idx\n) {\n    if (2 * idx >= bh * td) {\n        return;\n    }\n    size_t i_bh = idx / (td / 2);\n    size_t i_td = idx - (td / 2) * i_bh;\n    size_t i_t = i_td / (d / 2);\n    size_t i_d = i_td - (d / 2) * i_t;\n    size_t i1 = i_bh * td + i_t * d + i_d;\n    size_t i2 = i1 + d / 2;\n    size_t i_cs = i_t * (d / 2) + i_d;\n    if (stride_b > 0) {\n      size_t b_idx = (2 * idx) / stride_b;\n      i_cs += b_idx * (td / 2);\n    }\n    T c = cos[i_cs];\n    T s = sin[i_cs];\n    dst[i1] = src[i1] * c - src[i2] * s;\n    dst[i2] = src[i1] * s + src[i2] * c;\n}\n\ntemplate<typename T>\nMETAL_FUNC void rope_thd(\n    constant size_t &b,\n    constant size_t &t,\n    constant size_t &h,\n    constant size_t &d,\n    constant size_t &stride_b,\n    device const T *src,\n    device const T *cos,\n    device const T *sin,\n    device T *dst,\n    uint idx\n) {\n    if (2 * idx >= b * t * h * d) {\n        return;\n    }\n    const size_t i_bth = idx / (d / 2);\n    const size_t i_d = idx - (d / 2) * i_bth;\n    const size_t i_t = (i_bth / h) % t;\n    const size_t i1 = i_bth * d + i_d;\n    const size_t i2 = i1 + d / 2;\n    size_t i_cs = i_t * (d / 2) + i_d;\n    if (stride_b > 0) {\n      const size_t b_idx = (2 * idx) / stride_b;\n      i_cs += b_idx * ((t * d) / 2);\n    }\n    T c = cos[i_cs];\n    T s = sin[i_cs];\n    dst[i1] = src[i1] * c - src[i2] * s;\n    dst[i2] = src[i1] * s + src[i2] * c;\n}\n\n#define ROPE(FN_NAME, FN_NAME_I, FN_NAME_THD, TYPENAME) \\\nkernel void FN_NAME_I( \\\n    constant size_t &bh, \\\n    constant size_t &td, \\\n    constant size_t &stride_b, \\\n    device const TYPENAME *src,  \\\n    device const TYPENAME *cos,  \\\n    device const TYPENAME *sin,  \\\n    device TYPENAME *dst, \\\n    uint tid [[ thread_position_in_grid ]] \\\n) { \\\n    ropei<TYPENAME>(bh, td, stride_b, src, cos, sin, dst, tid); \\\n}\\\nkernel void FN_NAME( \\\n    constant size_t &bh, \\\n    constant size_t &td, \\\n    constant size_t &d, \\\n    constant size_t &stride_b, \\\n    device const TYPENAME *src,  \\\n    device const TYPENAME *cos,  \\\n    device const TYPENAME *sin,  \\\n    device TYPENAME *dst, \\\n    uint idx [[ thread_position_in_grid ]] \\\n) { \\\n    rope<TYPENAME>(bh, td, d, stride_b, src, cos, sin, dst, idx); \\\n}\\\nkernel void FN_NAME_THD( \\\n    constant size_t &b, \\\n    constant size_t &t, \\\n    constant size_t &h, \\\n    constant size_t &d, \\\n    constant size_t &stride_b, \\\n    device const TYPENAME *src,  \\\n    device const TYPENAME *cos,  \\\n    device const TYPENAME *sin,  \\\n    device TYPENAME *dst, \\\n    uint idx [[ thread_position_in_grid ]] \\\n) { \\\n    rope_thd<TYPENAME>(b, t, h, d, stride_b, src, cos, sin, dst, idx); \\\n}\\\n\nimpl_rms_norm(rmsnorm_f32, float)\nimpl_rms_norm(rmsnorm_f16, half)\nimpl_layer_norm(layernorm_f32, float)\nimpl_layer_norm(layernorm_f16, half)\nROPE(rope_f32, rope_i_f32, rope_thd_f32, float)\nROPE(rope_f16, rope_i_f16, rope_thd_f16, half)\n\nimpl_reduce(Sum, fast_sum_f32, float)\nimpl_reduce(Sum, fast_sum_u32, uint)\nimpl_reduce(Sum, fast_sum_f16, half)\nimpl_reduce(Sum, fast_sum_u8, uint8_t)\n\nimpl_reduce(Mul, fast_mul_f32, float)\nimpl_reduce(Mul, fast_mul_u32, uint)\nimpl_reduce(Mul, fast_mul_f16, half)\nimpl_reduce(Mul, fast_mul_u8, uint8_t)\n\nimpl_reduce(Max, fast_max_f32, float)\nimpl_reduce(Max, fast_max_u32, uint)\nimpl_reduce(Max, fast_max_f16, half)\nimpl_reduce(Max, fast_max_u8, uint8_t)\n\nimpl_reduce(Min, fast_min_f32, float)\nimpl_reduce(Min, fast_min_u32, uint)\nimpl_reduce(Min, fast_min_f16, half)\nimpl_reduce(Min, fast_min_u8, uint8_t)\n\nimpl_arg_reduce(Min, fast_argmin_f32, float)\nimpl_arg_reduce(Min, fast_argmin_f16, half)\nimpl_arg_reduce(Min, fast_argmin_u32, uint)\nimpl_arg_reduce(Min, fast_argmin_u8, uint8_t)\n\nimpl_arg_reduce(Max, fast_argmax_f32, float)\nimpl_arg_reduce(Max, fast_argmax_f16, half)\nimpl_arg_reduce(Max, fast_argmax_u32, uint)\nimpl_arg_reduce(Max, fast_argmax_u8, uint8_t)\n\nimpl_softmax(softmax_f32, float)\nimpl_softmax(softmax_f16, half)\n\n#if __METAL_VERSION__ >= 220\nimpl_reduce(Sum, fast_sum_i64, int64_t)\nimpl_reduce(Mul, fast_mul_i64, int64_t)\nimpl_reduce(Min, fast_min_i64, int64_t)\nimpl_reduce(Max, fast_max_i64, int64_t)\n\nimpl_arg_reduce(Min, fast_argmin_i64, int64_t)\nimpl_arg_reduce(Max, fast_argmax_i64, int64_t)\n#endif\n\n#if defined(__HAVE_BFLOAT__)\nimpl_reduce(Sum, fast_sum_bf16, bfloat)\nimpl_reduce(Mul, fast_mul_bf16, bfloat)\nimpl_reduce(Max, fast_max_bf16, bfloat)\nimpl_reduce(Min, fast_min_bf16, bfloat)\n\nimpl_arg_reduce(Min, fast_argmin_bf16, bfloat)\nimpl_arg_reduce(Max, fast_argmax_bf16, bfloat)\n\nimpl_softmax(softmax_bf16, bfloat)\n\nimpl_rms_norm(rmsnorm_bf16, bfloat)\nimpl_layer_norm(layernorm_bf16, bfloat)\nROPE(rope_bf16, rope_i_bf16, rope_thd_bf16, bfloat)\n#endif\n",
    )
val REDUCE: String = REDUCE_PARTS.joinToString("")

val SORT: String = "// Imported from https://github.com/ggerganov/llama.cpp/blob/master/ggml-metal.metal\n#include <metal_stdlib>\nusing namespace metal;\n\n#define SWAP(x, y) { auto tmp = (x); (x) = (y); (y) = tmp; }\n#define SORT_ASC 1\n#define SORT_DESC 0\n\ntemplate<int order, typename T>\nMETAL_FUNC void argsort(\n        device const T        * x,\n        device       uint32_t * dst,\n        constant     int64_t & ncols,\n        constant     int64_t & ncols_pad,\n        threadgroup uint32_t  * shared_values [[threadgroup(0)]],\n        uint3 tgpig[[threadgroup_position_in_grid]],\n        uint3 tpitg[[thread_position_in_threadgroup]]) {\n    int col = tpitg[0];\n    int row = tgpig[1];\n\n    if (col >= ncols_pad) return;\n\n    device const T        * x_row   = x + row * ncols;\n    threadgroup uint32_t  * dst_row = shared_values;\n\n    // initialize indices\n    dst_row[col] = col;\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    for (int k = 2; k <= ncols_pad; k *= 2) {\n        for (int j = k / 2; j > 0; j /= 2) {\n            int ixj = col ^ j;\n            if (ixj > col) {\n                if ((col & k) == 0) {\n                    if (dst_row[col] >= ncols ||\n                        (dst_row[ixj] < ncols && (order == SORT_ASC ?\n                            x_row[dst_row[col]] > x_row[dst_row[ixj]] :\n                            x_row[dst_row[col]] < x_row[dst_row[ixj]]))\n                    ) {\n                        SWAP(dst_row[col], dst_row[ixj]);\n                    }\n                } else {\n                    if (dst_row[ixj] >= ncols ||\n                        (dst_row[col] < ncols && (order == SORT_ASC ?\n                            x_row[dst_row[col]] < x_row[dst_row[ixj]] :\n                            x_row[dst_row[col]] > x_row[dst_row[ixj]]))\n                    ) {\n                        SWAP(dst_row[col], dst_row[ixj]);\n                    }\n                }\n            }\n            threadgroup_barrier(mem_flags::mem_threadgroup);\n        }\n    }\n\n    // copy the result to dst without the padding\n    if (col < ncols) {\n        dst[row * ncols + col] = dst_row[col];\n    }\n}\n\n#define ARGSORT(T, RUST_T) \\\nkernel void asort_asc_##RUST_T( \\\n    device const T        * x, \\\n    device       uint32_t * dst, \\\n    constant     int64_t & ncols, \\\n    constant     int64_t & ncols_pad, \\\n    threadgroup uint32_t  * shared_values [[threadgroup(0)]], \\\n    uint3 tgpig[[threadgroup_position_in_grid]], \\\n    uint3 tpitg[[thread_position_in_threadgroup]] \\\n) {  \\\n    argsort<SORT_ASC, T>(x, dst, ncols, ncols_pad, shared_values, tgpig, tpitg); \\\n} \\\nkernel void asort_desc_##RUST_T( \\\n    device const T        * x, \\\n    device       uint32_t * dst, \\\n    constant     int64_t & ncols, \\\n    constant     int64_t & ncols_pad, \\\n    threadgroup uint32_t  * shared_values [[threadgroup(0)]], \\\n    uint3 tgpig[[threadgroup_position_in_grid]], \\\n    uint3 tpitg[[thread_position_in_threadgroup]] \\\n) {  \\\n    argsort<SORT_DESC, T>(x, dst, ncols, ncols_pad, shared_values, tgpig, tpitg); \\\n} \\\n\nARGSORT(float, f32)\nARGSORT(half, f16)\nARGSORT(uint8_t, u8)\nARGSORT(uint32_t, u32)\n\n#if __METAL_VERSION__ >= 220\nARGSORT(int64_t, i64)\n#endif\n#if defined(__HAVE_BFLOAT__)\nARGSORT(bfloat, bf16)\n#endif\n"

val TERNARY: String = "#include <metal_stdlib>\nusing namespace metal;\n\nconstant bool IDS_CONTIGUOUS [[function_constant(0)]];\nconstant bool T_CONTIGUOUS [[function_constant(1)]];\nconstant bool F_CONTIGUOUS [[function_constant(2)]];\n\n\nMETAL_FUNC uint get_strided_index(\n    uint idx,\n    constant const size_t &num_dims,\n    constant const size_t *dims,\n    constant const size_t *strides\n) {\n    uint strided_i = 0;\n    #pragma clang loop unroll(full)\n    for (uint d = 0; d < num_dims; d++) {\n        uint dim_idx = num_dims - 1 - d;\n        strided_i += (idx % dims[dim_idx]) * strides[dim_idx];\n        idx /= dims[dim_idx];\n    }\n    return strided_i;\n}\n\ntemplate<uint Y>\nconstexpr uint div_ceil(uint x) {\n    return x / Y + (x % Y > 0);\n}\n\ntemplate<uint X, uint Y>\nconstexpr uint div_ceil() {\n    return X / Y + (X % Y > 0);\n}\n\ntemplate<typename T>\nconstexpr uint work_per_thread() {\n    return div_ceil<8, sizeof(T)>();\n}\n\ntemplate<typename T, typename ID, uint W = work_per_thread<T>()>\nMETAL_FUNC void where_cond(\n    constant size_t &numel,\n    constant size_t &num_dims,\n    constant size_t *dims,\n    constant size_t *strides,\n    constant size_t *strides_t,\n    constant size_t *strides_f,\n    device const ID *ids,\n    device const T *t,\n    device const T *f,\n    device T *out,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    uint idx = 0;\n    uint t_idx = 0;\n    uint f_idx = 0;\n\n    const uint step = div_ceil<W>(numel);\n    #pragma clang loop unroll(full)\n    for (uint i = tid; i < numel; i += step) {\n        if (IDS_CONTIGUOUS) {\n            idx = i;\n        } else {\n            idx = get_strided_index(i, num_dims, dims, strides);\n        }\n        if (T_CONTIGUOUS) {\n            t_idx = i;\n        } else {\n            t_idx = get_strided_index(i, num_dims, dims, strides_t);\n        }\n        if (F_CONTIGUOUS) {\n            f_idx = i;\n        } else {\n            f_idx = get_strided_index(i, num_dims, dims, strides_f);\n        }\n        out[i] = select(f[f_idx], t[t_idx], ids[idx]);\n    }\n\n}\n\n#define WHERE_OP(T, ID, FN_NAME)                                                                \\\nkernel void FN_NAME(                                                                            \\\n    constant size_t &numel,                                                                     \\\n    constant size_t &num_dims,                                                                  \\\n    constant size_t *dims,                                                                      \\\n    constant size_t *strides,                                                                   \\\n    constant size_t *strides_t,                                                                 \\\n    constant size_t *strides_f,                                                                 \\\n    device const ID *ids,                                                                       \\\n    device const T *t,                                                                          \\\n    device const T *f,                                                                          \\\n    device T *out,                                                                              \\\n    uint i [[ thread_position_in_grid ]]                                                        \\\n) {                                                                                             \\\n   where_cond<T, ID>(numel, num_dims, dims, strides, strides_t, strides_f, ids, t, f, out, i);  \\\n}                                                                                               \\\n\nWHERE_OP(half, uint32_t, where_u32_f16)\nWHERE_OP(float, uint32_t, where_u32_f32)\nWHERE_OP(uint8_t, uint32_t, where_u32_u8)\nWHERE_OP(uint32_t, uint32_t, where_u32_u32)\n\nWHERE_OP(half, uint8_t, where_u8_f16)\nWHERE_OP(float, uint8_t, where_u8_f32)\nWHERE_OP(uint8_t, uint8_t, where_u8_u8)\nWHERE_OP(uint32_t, uint8_t, where_u8_u32)\n\n#if __METAL_VERSION__ >= 220\nWHERE_OP(int64_t, uint8_t, where_u8_i64)\nWHERE_OP(int64_t, uint32_t, where_u32_i64)\n\nWHERE_OP(half, int64_t, where_i64_f16)\nWHERE_OP(float, int64_t, where_i64_f32)\nWHERE_OP(uint8_t, int64_t, where_i64_u8)\nWHERE_OP(uint32_t, int64_t, where_i64_u32)\nWHERE_OP(int64_t, int64_t, where_i64_i64)\n#if defined(__HAVE_BFLOAT__)\nWHERE_OP(bfloat, int64_t, where_i64_bf16)\n#endif\n#endif\n\n#if defined(__HAVE_BFLOAT__)\nWHERE_OP(bfloat, uint8_t, where_u8_bf16)\nWHERE_OP(bfloat, uint32_t, where_u32_bf16)\n#endif\n"

val UNARY: String = "#include <metal_stdlib>\n#include <metal_math>\nusing namespace metal;\n\n// Utils\nMETAL_FUNC uint get_strided_index(\n    uint idx,\n    constant size_t &num_dims,\n    constant size_t *dims,\n    constant size_t *strides\n) {\n    uint strided_i = 0;\n    for (uint d = 0; d < num_dims; d++) {\n        uint dim_idx = num_dims - 1 - d;\n        strided_i += (idx % dims[dim_idx]) * strides[dim_idx];\n        idx /= dims[dim_idx];\n    }\n    return strided_i;\n}\n\ntemplate<uint Y>\nconstexpr uint div_ceil(uint x) {\n    return x / Y + (x % Y > 0);\n}\n\ntemplate<uint X, uint Y>\nconstexpr uint div_ceil() {\n    return X / Y + (X % Y > 0);\n}\n\ntemplate<typename T>\nconstexpr uint work_per_thread() {\n    return div_ceil<8, sizeof(T)>();\n}\n\n// Kernels\ntemplate <typename T, typename U, typename unary, int W = work_per_thread<T>()>\n[[kernel]] void unary_kernel(\n    constant size_t &dim,\n    device const T* input,\n    device U* output,\n    uint tid [[thread_position_in_grid]]\n) {\n    unary op;\n    const uint step = div_ceil<W>(dim);\n    #pragma clang loop unroll(full)\n    for (uint i = tid; i < dim; i += step) {\n        output[i] = static_cast<U>(op(input[i]));\n    }\n}\n\ntemplate <typename T, typename U, typename unary>\n[[kernel]] void unary_kernel_strided(\n    constant size_t &dim,\n    constant size_t &num_dims,\n    constant size_t *dims,\n    constant size_t *strides,\n    constant const T *input,\n    device U *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    unary op;\n    if (tid >= dim) return;\n    uint idx = get_strided_index(tid, num_dims, dims, strides);\n    output[tid] = static_cast<U>(op(input[idx]));\n}\n\ntemplate <typename T, int W = work_per_thread<T>()>\n[[kernel]] void const_set(\n    constant size_t &dim,\n    device const T &input,\n    device T *output,\n    uint tid [[thread_position_in_grid]]\n) {\n    const uint step = div_ceil<W>(dim);\n    #pragma clang loop unroll(full)\n    for (uint i = tid; i < dim; i += step) {\n        output[i] = input;\n    }\n}\n\ntemplate <typename T>\n[[kernel]] void const_set_strided(\n    constant size_t &dim,\n    constant size_t &num_dims,\n    constant size_t *dims,\n    constant size_t *strides,\n    device const T &input,\n    device T *output,\n    uint tid [[ thread_position_in_grid ]]\n) {\n    if (tid >= dim) return;\n    uint idx = get_strided_index(tid, num_dims, dims, strides);\n    output[idx] = input;\n}\n\ntemplate <typename T>\n[[kernel]] void copy2d(\n    constant int64_t &d1,\n    constant int64_t &d2,\n    constant int64_t &src_s,\n    constant int64_t &dst_s,\n    device const T *input,\n    device T *output,\n    uint2 idx [[thread_position_in_grid]]\n) {\n    if (idx.x >= d1 || idx.y >= d2) return;\n    int64_t src_idx = idx.x * src_s + idx.y;\n    int64_t dst_idx = idx.x * dst_s + idx.y;\n    output[dst_idx] = input[src_idx];\n}\n\n// Unary functions\ntemplate <typename T> METAL_FUNC T erf(T in){\n    // constants\n    constexpr const float a1 =  0.254829592;\n    constexpr const float a2 = -0.284496736;\n    constexpr const float a3 =  1.421413741;\n    constexpr const float a4 = -1.453152027;\n    constexpr const float a5 =  1.061405429;\n    constexpr const float p  =  0.3275911;\n\n    float x = static_cast<float>(in);\n\n    // Save the sign of x\n    int sign = 1;\n    if (x < 0)\n        sign = -1;\n    x = fabs(x);\n\n    // A&S formula 7.1.26\n    float t = 1.0/(1.0 + p*x);\n    float y = 1.0 - (((((a5*t + a4)*t) + a3)*t + a2)*t + a1)*t*exp(-x*x);\n\n    return T(sign*y);\n}\ntemplate <typename T> METAL_FUNC T id(T in) { return in; }\ntemplate <typename T> METAL_FUNC T gelu_erf(T x) {\n    return static_cast<T>(x * (1 + erf(x * M_SQRT1_2_F)) / 2);\n}\ntemplate <typename T> METAL_FUNC T gelu(T x) {\n    if (x > 5) {\n        return x;\n    }\n    T x_sq = x * x;\n    T x_cube = x_sq * x;\n    T alpha = x + static_cast<T>(0.044715) * x_cube;\n    T beta =  (static_cast<T>(M_2_SQRTPI_F * M_SQRT1_2_F) * alpha);\n    return static_cast<T>(0.5) * x * (static_cast<T>(1.0) + T(precise::tanh(beta)));\n}\ntemplate <typename T> METAL_FUNC T relu(T x) {\n    if (x > 5) {\n        return x;\n    }\n    T x_sq = x * x;\n    T x_cube = x_sq * x;\n    T alpha = x + static_cast<T>(0.044715) * x_cube;\n    T beta =  (static_cast<T>(M_2_SQRTPI_F * M_SQRT1_2_F) * alpha);\n    return static_cast<T>(0.5) * x * (static_cast<T>(1.0) + T(precise::tanh(beta)));\n}\ntemplate <typename T> METAL_FUNC T recip(T x) {\n    return static_cast<T>(1.0 / x);\n}\ntemplate <typename T> METAL_FUNC T sigmoid(T x) {\n    return static_cast<T>(recip(1 + exp(-x)));\n}\n\n// Define unary ops\n#define define_unary_op(name, op)   \\\nstruct name {                       \\\n    template <typename T>           \\\n    METAL_FUNC T operator()(T x) {  \\\n        return static_cast<T>(op);  \\\n    }                               \\\n};\n\ndefine_unary_op(usqr, x * x);\ndefine_unary_op(urecip, recip(x));\ndefine_unary_op(uneg, -x);\ndefine_unary_op(uid, x);\ndefine_unary_op(ugelu, gelu(x));\ndefine_unary_op(urelu, x < 0 ? 0 : x);\ndefine_unary_op(usilu, x / (1 + exp(-x)));\ndefine_unary_op(ugelu_erf, gelu_erf(x));\ndefine_unary_op(usqrt, sqrt(x));\ndefine_unary_op(ucos, cos(x));\ndefine_unary_op(usin, sin(x));\ndefine_unary_op(uexp, exp(x));\ndefine_unary_op(ulog, log(x));\ndefine_unary_op(uabs, abs(static_cast<float>(x)));\ndefine_unary_op(uceil, ceil(x));\ndefine_unary_op(ufloor, floor(x));\ndefine_unary_op(uround, round(x));\ndefine_unary_op(uerf, erf(x));\ndefine_unary_op(usign, sign(x));\ndefine_unary_op(usigmoid, sigmoid(x));\n// tanh may create NaN on large values, e.g. 45 rather than outputting 1.\n// This has been an issue for the encodec example.\ndefine_unary_op(utanh, precise::tanh(x));\n\n// Macros to help initialize kernels\n#define init_kernel(name, func, ...) \\\n  template [[host_name(name)]] [[kernel]] decltype(func<__VA_ARGS__>) func<__VA_ARGS__>;\n\n#define init_unary(op_name, unary_op, tname, t)                                         \\\n    init_kernel(#op_name \"_\" #tname, unary_kernel, t, t, unary_op)                      \\\n    init_kernel(#op_name \"_\" #tname \"_strided\", unary_kernel_strided, t, t, unary_op)\n\n#if defined(__HAVE_BFLOAT__)\n#define init_unary_float(op_name, unary_op)   \\\n    init_unary(op_name, unary_op, f32, float) \\\n    init_unary(op_name, unary_op, f16, half)  \\\n    init_unary(op_name, unary_op, bf16, bfloat)\n#else\n#define init_unary_float(op_name, unary_op)   \\\n    init_unary(op_name, unary_op, f32, float) \\\n    init_unary(op_name, unary_op, f16, half)\n#endif\n\n#define init_copy2d(tname, t)  \\\n    init_kernel(\"copy2d_\" #tname, copy2d, t)\n\n#define init_const_set(tname, t)                    \\\n    init_kernel(\"const_set_\" #tname, const_set, t)  \\\n    init_kernel(\"const_set_\" #tname \"_strided\", const_set_strided, t)\n\n// Initialize all unary kernels for floating point types\ninit_unary_float(gelu_erf, ugelu_erf);\ninit_unary_float(sqrt, usqrt);\ninit_unary_float(sqr, usqr);\ninit_unary_float(neg, uneg);\ninit_unary_float(recip, urecip);\ninit_unary_float(copy, uid);\ninit_unary_float(silu, usilu);\ninit_unary_float(gelu, ugelu);\ninit_unary_float(relu, urelu);\ninit_unary_float(cos, ucos);\ninit_unary_float(sin, usin);\ninit_unary_float(exp, uexp);\ninit_unary_float(log, ulog);\ninit_unary_float(abs, uabs);\ninit_unary_float(ceil, uceil);\ninit_unary_float(floor, ufloor);\ninit_unary_float(round, uround);\ninit_unary_float(erf, uerf);\ninit_unary_float(sign, usign);\ninit_unary_float(sigmoid, usigmoid);\ninit_unary_float(tanh, utanh);\n\n// Initialize copy2d kernels\ninit_copy2d(f32, float);\ninit_copy2d(f16, half);\n\n// Initialize const_set kernels\ninit_const_set(f32, float);\ninit_const_set(f16, half);\n\n#if defined(__HAVE_BFLOAT__)\ninit_copy2d(bf16, bfloat);\ninit_const_set(bf16, bfloat);\n#endif\n\n// Initialize unary kernels for integer dtypes\ninit_unary(copy, uid, u8, uint8_t);\ninit_unary(copy, uid, u32, uint32_t);\n\ninit_copy2d(u8, uint8_t);\ninit_copy2d(u32, uint32_t);\n\ninit_const_set(u8, uint8_t);\ninit_const_set(u32, uint32_t);\n\n#if __METAL_VERSION__ >= 220\ninit_unary(copy, uid, i64, int64_t);\ninit_copy2d(i64, int64_t);\ninit_const_set(i64, int64_t);\n#endif\n\ninit_copy2d(i32, int32_t);\ninit_copy2d(i16, int16_t);\n"

private val SDPA_PARTS: List<String> =
    listOf(
        "// Updated from MLX commit has f70764a\n\n#include <metal_stdlib>\n#include <metal_simdgroup>\n\nusing namespace metal;\n\n#define STEEL_CONST static constant constexpr const\n#define STEEL_PRAGMA_UNROLL _Pragma(\"clang loop unroll(full)\")\n\n#if defined(__HAVE_BFLOAT__)\n\ntypedef bfloat bfloat16_t;\ntypedef half float16_t;\n\n#else\n\n/////////////////////////////////////////////////////////////////////////////\n// Helpers\n/////////////////////////////////////////////////////////////////////////////\n\nconstexpr METAL_FUNC uint16_t float_to_bfloat_bits(float x) {\n  // Check for nan\n  if ((as_type<uint32_t>(x) & ~_fp_encoding_traits<float>::sign_mask) >\n      _fp_encoding_traits<float>::inf_mask) {\n    return uint16_t(as_type<uint32_t>(0x7FC0));\n  }\n  // Take bits\n  uint32_t float_bits = as_type<uint32_t>(x);\n\n  // Round to nearest even\n  float_bits += ((float_bits >> 16) & 1) + as_type<uint32_t>(0x7FFF);\n\n  // Take upper 16 bits\n  return float_bits >> 16;\n}\n\nconstexpr METAL_FUNC float bfloat_bits_to_float(uint16_t x) {\n  // Upper 16 bits are the data and lower 16 bits are 0s\n  return as_type<float>((uint32_t)x << 16);\n}\n\nstruct _MLX_BFloat16;\n\ntemplate <typename T>\nstatic constexpr constant bool can_convert_to_bfloat =\n    !is_same_v<T, _MLX_BFloat16> && is_convertible_v<T, float>;\n\ntemplate <typename T>\nstatic constexpr constant bool can_convert_from_bfloat =\n    !is_same_v<T, _MLX_BFloat16> && is_convertible_v<float, T>;\n\n/////////////////////////////////////////////////////////////////////////////\n// Bfloat struct\n/////////////////////////////////////////////////////////////////////////////\n\nstruct _MLX_BFloat16 {\n  /////////////////////////////////////////////////////////////////////////////\n  // Constructors\n  uint16_t bits_;\n  _MLX_BFloat16() thread = default;\n  _MLX_BFloat16() threadgroup = default;\n  _MLX_BFloat16() device = default;\n  _MLX_BFloat16() constant = default;\n\n  struct bits_to_bfloat_struct {};\n  static constexpr METAL_FUNC bits_to_bfloat_struct bits_to_bfloat() {\n    return bits_to_bfloat_struct();\n  }\n  constexpr METAL_FUNC _MLX_BFloat16(uint16_t bits, bits_to_bfloat_struct)\n      : bits_(bits) {}\n\n  /////////////////////////////////////////////////////////////////////////////\n  // Conversions to bfloat\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_to_bfloat<T>>::type>\n  constexpr METAL_FUNC _MLX_BFloat16(T x) thread\n      : bits_(float_to_bfloat_bits(static_cast<float>(x))) {}\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_to_bfloat<T>>::type>\n  constexpr METAL_FUNC _MLX_BFloat16(T x) threadgroup\n      : bits_(float_to_bfloat_bits(static_cast<float>(x))) {}\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_to_bfloat<T>>::type>\n  constexpr METAL_FUNC _MLX_BFloat16(T x) device\n      : bits_(float_to_bfloat_bits(static_cast<float>(x))) {}\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_to_bfloat<T>>::type>\n  constexpr METAL_FUNC _MLX_BFloat16(T x) constant\n      : bits_(float_to_bfloat_bits(static_cast<float>(x))) {}\n\n  /////////////////////////////////////////////////////////////////////////////\n  // Conversions from bfloat\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_from_bfloat<T>>::type>\n  constexpr METAL_FUNC operator T() const thread {\n    return static_cast<T>(bfloat_bits_to_float(bits_));\n  }\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_from_bfloat<T>>::type>\n  constexpr METAL_FUNC operator T() const threadgroup {\n    return static_cast<T>(bfloat_bits_to_float(bits_));\n  }\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_from_bfloat<T>>::type>\n  constexpr METAL_FUNC operator T() const device {\n    return static_cast<T>(bfloat_bits_to_float(bits_));\n  }\n\n  template <\n      typename T,\n      typename = typename enable_if<can_convert_from_bfloat<T>>::type>\n  constexpr METAL_FUNC operator T() const constant {\n    return static_cast<T>(bfloat_bits_to_float(bits_));\n  }\n};\n\n/////////////////////////////////////////////////////////////////////////////\n// Bfloat operators\n/////////////////////////////////////////////////////////////////////////////\n\n/////////////////////////////////////////////////////////////////////////////\n// Unary ops\nconstexpr METAL_FUNC _MLX_BFloat16 operator-(_MLX_BFloat16 x) {\n  return -static_cast<float>(x);\n}\n\n/////////////////////////////////////////////////////////////////////////////\n// Binary operators\n#define bfloat_binop_base(__op__, __operator__, otype, atype, btype, ctype) \\\n  constexpr METAL_FUNC otype __operator__(atype lhs, btype rhs) {           \\\n    return static_cast<ctype>(lhs) __op__ static_cast<ctype>(rhs);          \\\n  }\n\n#define bfloat_binop_helper(__op__, __operator__, otype, itype, ctype)    \\\n  constexpr METAL_FUNC otype __operator__(_MLX_BFloat16 lhs, itype rhs) { \\\n    return static_cast<ctype>(lhs) __op__ static_cast<ctype>(rhs);        \\\n  }                                                                       \\\n  constexpr METAL_FUNC otype __operator__(itype lhs, _MLX_BFloat16 rhs) { \\\n    return static_cast<ctype>(lhs) __op__ static_cast<ctype>(rhs);        \\\n  }\n\n/////////////////////////////////////////////////////////////////////////////\n// Arithmetic Operators\n#define bfloat_binop(_op_, _operator_)                                       \\\n  bfloat_binop_base(                                                         \\\n      _op_, _operator_, _MLX_BFloat16, _MLX_BFloat16, _MLX_BFloat16, float); \\\n  bfloat_binop_helper(_op_, _operator_, float, float, float);                \\\n  bfloat_binop_helper(_op_, _operator_, float, half, float);                 \\\n  bfloat_binop_helper(_op_, _operator_, _MLX_BFloat16, int32_t, float);      \\\n  bfloat_binop_helper(_op_, _operator_, _MLX_BFloat16, uint32_t, float);     \\\n  bfloat_binop_helper(_op_, _operator_, _MLX_BFloat16, int64_t, float);      \\\n  bfloat_binop_helper(_op_, _operator_, _MLX_BFloat16, uint64_t, float);\n\nbfloat_binop(+, operator+);\nbfloat_binop(-, operator-);\nbfloat_binop(*, operator*);\nbfloat_binop(/, operator/);\n\n/////////////////////////////////////////////////////////////////////////////\n// Comparison ops\n#define bfloat_compop(__op__, __operator__)                             \\\n  bfloat_binop_base(                                                    \\\n      __op__, __operator__, bool, _MLX_BFloat16, _MLX_BFloat16, float); \\\n  bfloat_binop_helper(__op__, __operator__, bool, float, float);        \\\n  bfloat_binop_helper(__op__, __operator__, bool, half, float);         \\\n  bfloat_binop_helper(__op__, __operator__, bool, int32_t, float);      \\\n  bfloat_binop_helper(__op__, __operator__, bool, uint32_t, float);     \\\n  bfloat_binop_helper(__op__, __operator__, bool, int64_t, float);      \\\n  bfloat_binop_helper(__op__, __operator__, bool, uint64_t, float);\n\nbfloat_compop(>, operator>);\nbfloat_compop(<, operator<);\nbfloat_compop(>=, operator>=);\nbfloat_compop(<=, operator<=);\nbfloat_compop(==, operator==);\nbfloat_compop(!=, operator!=);\n\n#undef bfloat_compop\n#undef bfloat_binop_base\n#undef bfloat_binop_helper\n#undef bfloat_binop\n\n/////////////////////////////////////////////////////////////////////////////\n// Inplace Operators\n#define bfloat_inplace_op_helper(__op__, __operator__, itype, addr_space) \\\n  constexpr METAL_FUNC addr_space _MLX_BFloat16& __operator__(            \\\n      addr_space _MLX_BFloat16& lhs, itype rhs) {                         \\\n    lhs = static_cast<float>(lhs) __op__ static_cast<float>(rhs);         \\\n    return lhs;                                                           \\\n  }                                                                       \\\n  constexpr METAL_FUNC addr_space itype& __operator__(                    \\\n      addr_space itype& lhs, _MLX_BFloat16 rhs) {                         \\\n    lhs = static_cast<float>(lhs) __op__ static_cast<float>(rhs);         \\\n    return lhs;                                                           \\\n  }\n\n#define bfloat_inplace_op_addr_space_helper(__op__, __operator__, itype) \\\n  bfloat_inplace_op_helper(__op__, __operator__, itype, device);         \\\n  bfloat_inplace_op_helper(__op__, __operator__, itype, thread);         \\\n  bfloat_inplace_op_helper(__op__, __operator__, itype, threadgroup);\n\n#define bfloat_inplace_op(itype)                             \\\n  bfloat_inplace_op_addr_space_helper(+, operator+=, itype); \\\n  bfloat_inplace_op_addr_space_helper(-, operator-=, itype); \\\n  bfloat_inplace_op_addr_space_helper(*, operator*=, itype); \\\n  bfloat_inplace_op_addr_space_helper(/, operator/=, itype);\n\nbfloat_inplace_op(float);\nbfloat_inplace_op(half);\nbfloat_inplace_op(int16_t);\nbfloat_inplace_op(int32_t);\nbfloat_inplace_op(int64_t);\nbfloat_inplace_op(uint16_t);\nbfloat_inplace_op(uint32_t);\nbfloat_inplace_op(uint64_t);\n\n#undef bfloat_inplace_op_helper\n#undef bfloat_inplace_op_addr_space_helper\n#undef bfloat_inplace_op\n\n#define bfloat_inplace_op_helper(__op__, __operator__, addr_space) \\\n  constexpr METAL_FUNC addr_space _MLX_BFloat16& __operator__(     \\\n      addr_space _MLX_BFloat16& lhs, _MLX_BFloat16 rhs) {          \\\n    lhs = static_cast<float>(lhs) __op__ static_cast<float>(rhs);  \\\n    return lhs;                                                    \\\n  }\n\n#define bfloat_inplace_op_addr_space_helper(__op__, __operator__) \\\n  bfloat_inplace_op_helper(__op__, __operator__, device);         \\\n  bfloat_inplace_op_helper(__op__, __operator__, thread);         \\\n  bfloat_inplace_op_helper(__op__, __operator__, threadgroup);\n\nbfloat_inplace_op_addr_space_helper(+, operator+=);\nbfloat_inplace_op_addr_space_helper(-, operator-=);\nbfloat_inplace_op_addr_space_helper(*, operator*=);\nbfloat_inplace_op_addr_space_helper(/, operator/=);\n\n#undef bfloat_inplace_op_helper\n#undef bfloat_inplace_op_addr_space_helper\n\n/////////////////////////////////////////////////////////////////////////////\n// Bfloat typedef\n/////////////////////////////////////////////////////////////////////////////\n\ntypedef struct _MLX_BFloat16 bfloat16_t;\n\n#endif\n\n// ============ \"mlx/backend/metal/kernels/scaled_dot_product_attention_params.h\"\n\nstruct MLXFastAttentionParams {\n  const int M;\n  const int N;\n  const int K;\n\n  const int ldq; // ldq == ldo\n  const int ldk;\n  const int ldv;\n  const int lds;\n  const int ldo;\n\n  const int tiles_n;\n  const int tiles_m;\n\n  const int batch_stride_q;\n  const int batch_stride_k;\n  const int batch_stride_v;\n  const int batch_stride_o;\n\n  const int swizzle_log;\n  const int gemm_n_iterations_aligned;\n  const int gemm_k_iterations_aligned;\n  const int gemm_sv_m_block_iterations;\n\n  const int batch_ndim;\n  const float alpha;\n  const float softcapping;\n};\n\nstruct MLXScaledDotProductAttentionParams {\n  // Associated dimensions & transposition information\n  const uint QUERY_SEQUENCE_LENGTH = 1;\n  const uint N_Q_HEADS = 32;\n  const uint N_KV_HEADS = 32;\n  const uint KV_TILES = 1;\n  const float INV_ALPHA = 0.08838834764831843f;\n};\n\n// ============ \"mlx/backend/metal/kernels/scaled_dot_product_attention_params.sdpa_vector\"\n\nconstant bool sdpa_vector_has_mask [[function_constant(20)]];\n\ntemplate <typename T, int D>\n[[kernel]] void sdpa_vector(\n    const device T* queries [[buffer(0)]],\n    const device T* keys [[buffer(1)]],\n    const device T* values [[buffer(2)]],\n    device T* out [[buffer(3)]],\n    const constant int& gqa_factor,\n    const constant int& N,\n    const constant size_t& k_stride,\n    const constant size_t& v_stride,\n    const constant float& scale,\n    const constant float& softcapping,\n    const device bool* mask [[function_constant(sdpa_vector_has_mask)]],\n    const constant int& mask_seq_stride [[function_constant(sdpa_vector_has_mask)]],\n    const constant int& mask_head_stride [[function_constant(sdpa_vector_has_mask)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint simd_gid [[simdgroup_index_in_threadgroup]],\n    uint simd_lid [[thread_index_in_simdgroup]]) {\n  constexpr int BN = 32;\n  constexpr int BD = 32;\n  constexpr int elem_per_thread = D / BD;\n  constexpr int stride = BN * D;\n\n  typedef float U;\n\n  thread U q[elem_per_thread];\n  thread U k[elem_per_thread];\n  thread U o[elem_per_thread];\n\n  threadgroup U outputs[BN * BD];\n  threadgroup U max_scores[BN];\n  threadgroup U sum_exp_scores[BN];\n\n  // Adjust positions\n  const int head_idx = tid.y;\n  const int kv_head_idx = head_idx / gqa_factor;\n  queries += head_idx * D + simd_lid * elem_per_thread;\n  keys += kv_head_idx * k_stride + simd_gid * D + simd_lid * elem_per_thread;\n  values += kv_head_idx * v_stride + simd_gid * D + simd_lid * elem_per_thread;\n  if (sdpa_vector_has_mask) {\n    mask += head_idx * mask_head_stride + simd_gid * mask_seq_stride;\n  }\n  out += head_idx * D + simd_gid * elem_per_thread;\n\n  // Read the query and 0 the output accumulator\n  for (int i = 0; i < elem_per_thread; i++) {\n    q[i] = static_cast<U>(scale) * queries[i];\n  }\n  for (int i = 0; i < elem_per_thread; i++) {\n    o[i] = 0;\n  }\n\n  U max_score = -INFINITY;\n  U sum_exp_score = 0;\n\n  // For each key\n  for (int i = simd_gid; i < N; i += BN) {\n    if (!sdpa_vector_has_mask || mask[0]) {\n      // Read the key\n      for (int j = 0; j < elem_per_thread; j++) {\n        k[j] = keys[j];\n      }\n\n      // Compute the i-th score\n      U score = 0;\n      for (int j = 0; j < elem_per_thread; j++) {\n        score += q[j] * k[j];\n      }\n      score = simd_sum(score);\n      if (softcapping != 1.) {\n        score = precise::tanh(score);\n        score = score * softcapping;\n      }\n\n      // Update the accumulators\n      U new_max = max(max_score, score);\n      U factor = fast::exp(max_score - new_max);\n      U exp_score = fast::exp(score - new_max);\n\n      max_score = new_max;\n      sum_exp_score = sum_exp_score * factor + exp_score;\n\n      // Update the output accumulator\n      for (int j = 0; j < elem_per_thread; j++) {\n        o[j] = o[j] * factor + exp_score * values[j];\n      }\n    }\n\n    // Move the pointers to the next kv\n    keys += stride;\n    values += stride;\n    if (sdpa_vector_has_mask) {\n      mask += BN * mask_seq_stride;\n    }\n  }\n\n  // Each thread has a partial part of the output so we need to combine them.\n\n  // First let's communicate the max and sum_exp\n  if (simd_lid == 0) {\n    max_scores[simd_gid] = max_score;\n    sum_exp_scores[simd_gid] = sum_exp_score;\n  }\n  threadgroup_barrier(mem_flags::mem_threadgroup);\n  max_score = max_scores[simd_lid];\n  U new_max = simd_max(max_score);\n  U factor = fast::exp(max_score - new_max);\n  sum_exp_score = simd_sum(sum_exp_scores[simd_lid] * factor);\n\n  // Now we need to aggregate all the outputs\n  for (int i = 0; i < elem_per_thread; i++) {\n    outputs[simd_lid * BD + simd_gid] = o[i];\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    o[i] = simd_sum(outputs[simd_gid * BD + simd_lid] * factor) / sum_exp_score;\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n  }\n\n  // And write the output\n  if (simd_lid == 0) {\n    for (int i = 0; i < elem_per_thread; i++) {\n      out[i] = static_cast<T>(o[i]);\n    }\n  }\n}\n\ntemplate <typename T, int D>\n[[kernel]] void sdpa_vector_2pass_1(\n    const device T* queries [[buffer(0)]],\n    const device T* keys [[buffer(1)]],\n    const device T* values [[buffer(2)]],\n    device float* out [[buffer(3)]],\n    device float* sums [[buffer(4)]],\n    device float* maxs [[buffer(5)]],\n    const constant int& gqa_factor,\n    const constant int& N,\n    const con