a_vector_has_mask || mask[0]) {\n      // Read the key\n      for (int i = 0; i < elem_per_thread; i++) {\n        k[i] = keys[i];\n      }\n\n      // Compute the i-th score\n      U score = 0;\n      for (int i = 0; i < elem_per_thread; i++) {\n        score += q[i] * k[i];\n      }\n      score = simd_sum(score);\n      if (softcapping != 1.) {\n        score = precise::tanh(score);\n        score = score * softcapping;\n      }\n\n      // Update the accumulators\n      U new_max = max(max_score, score);\n      U factor = fast::exp(max_score - new_max);\n      U exp_score = fast::exp(score - new_max);\n\n      max_score = new_max;\n      sum_exp_score = sum_exp_score * factor + exp_score;\n\n      // Update the output accumulator\n      for (int i = 0; i < elem_per_thread; i++) {\n        o[i] = o[i] * factor + exp_score * values[i];\n      }\n    }\n\n    // Move the pointers to the next kv\n    keys += blocks * stride;\n    values += blocks * stride;\n    if (sdpa_vector_has_mask) {\n      mask += BN * blocks * mask_seq_stride;\n    }\n  }\n\n  // Each thread has a partial part of the output so we need to combine them.\n\n  // First let's communicate the max and sum_exp\n  if (simd_lid == 0) {\n    max_scores[simd_gid] = max_score;\n    sum_exp_scores[simd_gid] = sum_exp_score;\n  }\n  threadgroup_barrier(mem_flags::mem_threadgroup);\n  max_score = (simd_lid < BN) ? max_scores[simd_lid] : -1e9;\n  U new_max = simd_max(max_score);\n  U factor = fast::exp(max_score - new_max);\n  sum_exp_score = (simd_lid < BN) ? sum_exp_scores[simd_lid] : 0;\n  sum_exp_score = simd_sum(sum_exp_score * factor);\n\n  // Write the sum and new max\n  if (simd_gid == 0) {\n    sums[0] = sum_exp_score;\n    maxs[0] = new_max;\n  }\n\n  // Now we need to aggregate all the outputs\n  for (int i = 0; i < elem_per_thread; i++) {\n    outputs[simd_lid * BN + simd_gid] =\n        o[i] * fast::exp(max_scores[simd_gid] - new_max);\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    // And write the output\n    if (simd_gid == 0) {\n      U output = outputs[simd_lid * BN];\n      for (int j = 1; j < BN; j++) {\n        output += outputs[simd_lid * BN + j];\n      }\n      out[i] = static_cast<T>(output);\n    }\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n  }\n}\n\ntemplate <typename T, int D>\n[[kernel]] void sdpa_vector_2pass_2(\n    const device float* partials [[buffer(0)]],\n    const device float* sums [[buffer(1)]],\n    const device float* maxs [[buffer(2)]],\n    device T* out [[buffer(3)]],\n    uint3 tid [[threadgroup_position_in_grid]],\n    uint simd_gid [[simdgroup_index_in_threadgroup]],\n    u",
        "int simd_lid [[thread_index_in_simdgroup]]) {\n  constexpr int BN = 32;\n  constexpr int BD = 32;\n  constexpr int elem_per_thread = D / BD;\n  constexpr int blocks = 32;\n\n  typedef float U;\n\n  thread U o[elem_per_thread];\n  threadgroup U outputs[BN * BD];\n\n  // Adjust positions\n  const int head_idx = tid.y;\n  partials += head_idx * blocks * D + simd_gid * D + simd_lid * elem_per_thread;\n  sums += head_idx * blocks;\n  maxs += head_idx * blocks;\n  out += head_idx * D + simd_gid * elem_per_thread;\n\n  // First everybody reads the max and sum_exp\n  U max_score = maxs[simd_lid];\n  U new_max = simd_max(max_score);\n  U factor = fast::exp(max_score - new_max);\n  U sum_exp_score = simd_sum(sums[simd_lid] * factor);\n\n  // Now read the block into registers and then use shared memory to transpose\n  // it\n  for (int i = 0; i < elem_per_thread; i++) {\n    o[i] = partials[i];\n  }\n  for (int i = 0; i < elem_per_thread; i++) {\n    outputs[simd_lid * BD + simd_gid] = o[i];\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    o[i] = simd_sum(outputs[simd_gid * BD + simd_lid] * factor) / sum_exp_score;\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n  }\n\n  // And write the output\n  if (simd_lid == 0) {\n    for (int i = 0; i < elem_per_thread; i++) {\n      out[i] = static_cast<T>(o[i]);\n    }\n  }\n}\n\n// ============ \"mlx/backend/metal/kernels/utils.h\"\n\ntemplate <typename U>\nstruct Limits {\n  static const constant U max = metal::numeric_limits<U>::max();\n  static const constant U min = metal::numeric_limits<U>::min();\n  static const constant U finite_max = metal::numeric_limits<U>::max();\n  static const constant U finite_min = metal::numeric_limits<U>::min();\n};\n\n#define instantiate_default_limit(type)                                      \\\n  template <>                                                                \\\n  struct Limits<type> {                                                      \\\n    static constexpr constant type max = metal::numeric_limits<type>::max(); \\\n    static constexpr constant type min = metal::numeric_limits<type>::min(); \\\n    static constexpr constant type finite_max =                              \\\n        metal::numeric_limits<type>::max();                                  \\\n    static constexpr constant type finite_min =                              \\\n        metal::numeric_limits<type>::min();                                  \\\n  };\n\ninstantiate_default_limit(uint8_t);\ninstantiate_default_limit(uint16_t);\ninstantiate_default_limit(uint32_t);\ninstantiate_default_limit(uint64_t);\ninstantiate_default_limit(int8_t);\ninstantiate_default_limit(int16_t);\ninstantiate_default_limit(int32_t);\ninstantiate_default_limit(int64_t);\n\n#define instantiate_float_limit(type)             \\\n  template <>                                     \\\n  struct Limits<type> {                           \\\n    static constexpr constant type max =          \\\n        metal::numeric_limits<type>::infinity();  \\\n    static constexpr constant type min =          \\\n        -metal::numeric_limits<type>::infinity(); \\\n    static constexpr constant type finite_max =   \\\n        metal::numeric_limits<type>::max();       \\\n    static constexpr constant type finite_min =   \\\n        -metal::numeric_limits<type>::max();      \\\n  };\n\ninstantiate_float_limit(half);\ninstantiate_float_limit(float);\ninstantiate_float_limit(bfloat16_t);\n\n\n// ============ \"mlx/backend/metal/kernels/steel/attn/loader.h\"\n\ntemplate <\n    typename T,\n    short BROWS,\n    short BCOLS,\n    short dst_ld,\n    short reduction_dim,\n    short tgp_size,\n    short alignment = 1,\n    short n_reads = (BCOLS * BROWS) / (tgp_size),\n    short TCOLS = BCOLS / n_reads,\n    short TROWS = tgp_size / TCOLS>\nstruct BlockLoader {\n  STEEL_CONST short n_rows = (BROWS + TROWS - 1) / TROWS;\n  STEEL_CONST short vec_size = n_reads;\n\n  // Leading dimension for src\n  const int src_ld;\n  const int tile_stride;\n\n  // Thread location indices\n  const short thread_idx;\n  const short bi;\n  const short bj;\n\n  // threadgroup and device memory\n  threadgroup T* dst;\n  const device T* src;\n\n  struct alignas(alignment * sizeof(T)) ReadVector {\n    uint8_t v[sizeof(T) * vec_size];\n  };\n\n  /* Constructor */\n  METAL_FUNC BlockLoader(\n      const device T* src_,\n      const int src_ld_,\n      threadgroup T* dst_,\n      ushort simd_group_id [[simdgroup_index_in_threadgroup]],\n      ushort simd_lane_id [[thread_index_in_simdgroup]])\n      : src_ld(src_ld_),\n        tile_stride(reduction_dim ? BCOLS : BROWS * src_ld),\n        thread_idx(simd_group_id * 32 + simd_lane_id),\n        bi(thread_idx / TCOLS),\n        bj(vec_size * (thread_idx % TCOLS)),\n        dst(dst_ + bi * dst_ld + bj),\n        src(src_ + bi * src_ld + bj) {}\n\n  /* Apply operation to threadgroup without bound checking */\n  template <typename UnaryOp>\n  METAL_FUNC void apply_inplace_op(thread const UnaryOp& op) const {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < BROWS; i += TROWS) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < vec_size; j++) {\n        dst[i * dst_ld + j] = op.apply(dst[i * dst_ld + j]);\n      }\n    }\n  }\n\n  /* Load from device memory into threadgroup memory - without bound checking */\n  METAL_FUNC void load_unsafe() const {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < BROWS; i += TROWS) {\n      *((threadgroup ReadVector*)(&dst[i * dst_ld])) =\n          *((const device ReadVector*)(&src[i * src_ld]));\n    }\n  }\n\n  /* Load from device memory into threadgroup memory - with bound checking */\n  METAL_FUNC void load_safe(short2 src_tile_dim) const {\n    src_tile_dim = src_tile_dim - short2(bj, bi);\n\n    // Skip loading if thread has no valid reads\n    if (src_tile_dim.x <= 0 || src_tile_dim.y <= 0) {\n      STEEL_PRAGMA_UNROLL\n      for (short i = 0; i < BROWS; i += TROWS) {\n        STEEL_PRAGMA_UNROLL