\n  typedef metal::vec<T, kElemRows> row_frag_type;\n  typedef metal::vec<T, kElemCols> col_frag_type;\n\n  template <typename U>\n  using dtype_mat_t = typename metal::simdgroup_matrix<U, kFragRows, kFragCols>;\n\n  template <typename U>\n  using dtype_frag_t = typename metal::vec<U, kElemsPerFrag>;\n\n  METAL_FUNC static constexpr short2 get_coord(ushort simd_lane_id\n                                               [[thread_index_in_simdgroup]]) {\n    const short qid = simd_lane_id / 4;\n    const short fm = (qid & 4) + ((simd_lane_id / 2) % 4);\n    const short fn = (qid & 2) * 2 + (simd_lane_id % 2) * 2;\n    return short2{fn, fm};\n  }\n\n  template <typename SrcPtrType, typename StrX, typename StrY>\n  METAL_FUNC static constexpr void\n  load(thread frag_type& dst, SrcPtrType src, StrX str_x, StrY str_y) {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < kElemRows; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < kElemCols; j++) {\n        dst[i * kElemCols + j] = static_cast<T>(src[i * str_x.value + j * str_y.value]);\n      }\n    }\n  }\n\n  template <\n      typename SrcPtrType,\n      typename StrX,\n      typename StrY,\n      typename LimX,\n      typename LimY,\n      typename OffX,\n      typename OffY>\n  METAL_FUNC static constexpr void load_safe(\n      thread frag_type& dst,\n      SrcPtrType src,\n      StrX str_x,\n      StrY str_y,\n      LimX lim_x,\n      LimY lim_y,\n      OffX off_x = Int<0>{},\n      OffY off_y = Int<0>{}) {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < kElemRows; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < kElemCols; j++) {\n        if ((off_x + i) < lim_x && (off_y + j) < lim_y) {\n          dst[i * kElemCols + j] =\n              static_cast<T>(src[(off_x + i) * str_x + (off_y + j) * str_y.value]);\n        } else {\n          dst[i * kElemCols + j] = T(0);\n        }\n      }\n    }\n  }\n\n  template <typename DstPtrType, typename StrX, typename StrY>\n  METAL_FUNC static cons